-- Wipe experimental data (and dependent rows) safely
DO $$
DECLARE t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['episodes','podcasts','hosts','listening_history','favorites','host_follows','episode_bookmarks','podcast_reviews','host_reviews'] LOOP
    IF to_regclass('public.' || t) IS NOT NULL THEN
      EXECUTE 'TRUNCATE TABLE public.' || t || ' CASCADE';
    END IF;
  END LOOP;
END $$;

-- ---------- بودكاست وعي| podcast@wahe4 ----------
DO $$
DECLARE
  v_host_id uuid;
  v_pod_id uuid;
  v_cat uuid;
BEGIN
  SELECT id INTO v_cat FROM categories WHERE name_ar = 'المسيرة المهنية' LIMIT 1;
  INSERT INTO hosts (name_ar, slug, photo_url, cover_url, title_ar, specialty_ar, bio_ar, country, category_id, is_verified, followers_count)
  VALUES ('Podcast@wahe4| بودكاست وعي', 'podcast-wahe4', 'https://is1-ssl.mzstatic.com/image/thumb/Podcasts221/v4/a0/7a/ca/a07acae5-8be6-3250-1147-c558efd56f88/mza_7440152408459235285.jpg/600x600bb.jpg', 'https://is1-ssl.mzstatic.com/image/thumb/Podcasts221/v4/a0/7a/ca/a07acae5-8be6-3250-1147-c558efd56f88/mza_7440152408459235285.jpg/600x600bb.jpg', 'مقدم', 'المسيرة المهنية', 'بودكاست حقيقي: بودكاست وعي| podcast@wahe4', 'أونلاين', v_cat, true, 50000)
  RETURNING id INTO v_host_id;

  INSERT INTO podcasts (title, description, host_id, category_id, type, cover_url, audience_level, plays_count, rating_avg)
  VALUES ('بودكاست وعي| podcast@wahe4', '❤️ما تنسوا تتابعوا القناة على اليوتيوب podcast@wahe4 رابط القناة https://www.youtube.com/@Wahe4 السلام عليكم أهلا و سهلا بكم في قناة [بودكاست وعي] قناة هدفها توعوية مخصصة للبنات، بنفتح فيها مواضيع مهمة عن العلاقات، النفس، والمجتمع… بكل صراحة ووعي وبدون أحكام. هدفنا إن كل بنت تعرف قيمتها، وتفهم مشاعرها، وتتعلم تختار صح في حياتها العاطفية والاجتماعية. 📌 نقدم لك حلقات عن: •العلاقات العاطفية: كيف تميزي بين الحب الحقيقي والتلاعب؟ •فهم الذات: كيف تحبي نفسك وتحطي حدود صحية؟ •الوعي المجتمعي: نتكلم عن العادات اللي بتأثر علينا كفتيات ونفهم كيف نواجهها بذكاء. •التعافي والنضج العاطفي:', v_host_id, v_cat, 'professional', 'https://is1-ssl.mzstatic.com/image/thumb/Podcasts221/v4/a0/7a/ca/a07acae5-8be6-3250-1147-c558efd56f88/mza_7440152408459235285.jpg/600x600bb.jpg', 'beginner', 100000, 4.7)
  RETURNING id INTO v_pod_id;

  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'سر الانوثة و الهدوء النفسي| بودكاست وعي', 'اتمنى لكم مشاهده ممتعة❤️ الحلقة كاملة من هنا 👇🏻 https://youtu.be/V_I5UL4AuaA?si=ihzq2n8M7Qu8lJSh', 'https://anchor.fm/s/108148058/podcast/play/128488111/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2026-9-31%2F435503294-44100-2-3c4b0a03fca9c.mp3', 420, '2026-10-31 10:26:39'::timestamptz, 5000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'بنت فوقي لنفسك | الطيبة مصيبة| بودكاست وعي', 'في الحلقة الجديدة من بودكاست &quot;فوقي حبيبتي&quot; ، جمعنا ليكِ أقوى وأصدق النصائح اللي كل بنت محتاجة تسمعها عن العلاقات، وضع الحدود، واختيار الشريك المناسب من غير ما تفقدي نفسك في الطريق. 🎧✨ جاهزة تشوفي العلاقات من منظور جديد؟ #فوقي_حبيبتي #نصائح_للبنات #علاقات_صحية #بودكاست_عربي #تطوير_الذات', 'https://anchor.fm/s/108148058/podcast/play/127628504/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2026-9-17%2F434378349-44100-2-31bee088c8d3a.mp3', 276, '2026-10-17 17:12:59'::timestamptz, 6000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'لا تضيعي عمرك| بوكاست وعي للبنات', 'رابط الحلقة كا مل هنا 👇🏻 https://youtu.be/_dgmQfjmikA?si=SYEdZtrk7n4ZXepX', 'https://anchor.fm/s/108148058/podcast/play/125669285/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2026-8-13%2F431799959-44100-2-5dc75b73a8346.mp3', 355, '2026-09-13 13:33:24'::timestamptz, 7000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, '‏قوة الشخصية للبنات| بودكاست وعي', 'رابط الحلقة كاملة https://youtu.be/s8zegjNXAKk?si=gJmoV5KtqB_5fjE_ منورة يا جميلة! 🌸 في هذه الحلقة من بودكاست وعي، نغوص في أحد أكثر المواضيع بحثًا واهتمامًا لكل بنت تسعى للنجاح والاستقلال النفسي: كيف تكونين قوية الشخصية ومستقلة عاطفيًا دون أن تفقدي أنوثتك وهدوءك؟ القوة الحقيقية لا تعني الصوت العالي أو التصرف بحدّة، بل تبدأ من الداخل: من تقديرك لذاتك، وفهم قيمتك، ومعرفة كيفية وضع حدود صارمة وحماية مساحتك الشخصية بثبات وذكاء. 💡 أهم المحاور والمواضيع الناقشة في هذه الحلقة: بناء الثقة بالنفس من الصفر: خطوات عملية للتخلص من الشك في الذات والتردد. فن وضع الحدود: كيف تقولين &quot;لا&quot; بثقة ودون', 'https://anchor.fm/s/108148058/podcast/play/124660435/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2026-7-24%2F430437170-44100-2-e97f0b360b51a.mp3', 344, '2026-08-24 14:05:33'::timestamptz, 8000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'أسرار الذكاء الاجتماعي للبنات | بودكاست وعي', 'مشاهدة الحلقة كاملة من خلال الرابط https://youtu.be/ycokpig8Fp0?si=TU624bLFMg90xHEs في الحلقة دي من بودكاست وعي، هنفك مع بعض شفرة &quot;الذكاء الاجتماعي&quot; للبنات بلغة بسيطة وأمثلة من حياتنا اليومية! 💡✨ كتير بنسأل نفسنا: ليه في بنت الكل بيحترمها وحضورها طاغي من غير ما تتكلم كتير؟ وإزاي تفهمي الكلام اللي بين السطور وتكشفي الشخص المزيّف أو اللي بيحاول يستغلك؟ هنتكلم عن أسرار الذكاء الاجتماعي والكاريزما في كل مجالات حياتك: إزاي تتصرفي في الشغل والمهنة بهيبة وقوة بدون ما تصنعي مشاكل؟ 💼 إزاي تقرأي رسائل الانسحاب الخفية وتحطي حدود صارمة في العلاقات والتواصل؟ 💖 إزاي تتعاملي مع الأصدقاء، الأقارب', 'https://anchor.fm/s/108148058/podcast/play/124269784/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2026-7-15%2F429907921-44100-2-d08193c022502.mp3', 324, '2026-08-15 21:30:10'::timestamptz, 9000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'اسرار قوة الشخصية للبنات|بودكاست وعي |جزء ٣', 'الحلقة كاملة الرابط هنا https://youtu.be/lcQl5iesN9c?si=zo5SKjoishR00dct أسرار قوة الشخصية و الثقة بالنفس للبنات | بودكاست وعي أهلاً بيكي يا بطلة في حلقة جديدة من البودكاست.. النهاردة القعدة &quot;بيني وبينك&quot;. ☕✨ لو حاسة إن حقك بيضيع، أو إنك &quot;حساسة زيادة&quot; من كلام الناس، أو نفسك يكون ليكي حضور وكاريزما أول ما تدخلي أي مكان.. فالحلقة دي معمولة عشانك! في حلقة النهاردة من بودكاست وعي، هنتكلم في كلام حقيقي وعملي عن: 🔹 إزاي تفرضي هيبتك و قوة شخصيتك وتتكلمي بذكاء (قليل ودل). 🔹 سر الثقة بالنفس 🔹 إزاي تبني صداقات قوية وناجحة من غير ما تخسري نفسك. 🔹 حل نهائي لـ الحساسية المفرطة من ردو', 'https://anchor.fm/s/108148058/podcast/play/123642996/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2026-7-2%2F429052784-44100-2-886356e5771a5.mp3', 223, '2026-08-02 08:57:04'::timestamptz, 10000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'أسرار قوة الشخصية و الثقة للبنات | بودكاست وعي', 'الحلقة كاملة الرابط هنا https://youtu.be/lcQl5iesN9c?si=zo5SKjoishR00dct أسرار قوة الشخصية و الثقة بالنفس للبنات | بودكاست وعي أهلاً بيكي يا بطلة في حلقة جديدة من البودكاست.. النهاردة القعدة &quot;بيني وبينك&quot;. ☕✨ لو حاسة إن حقك بيضيع، أو إنك &quot;حساسة زيادة&quot; من كلام الناس، أو نفسك يكون ليكي حضور وكاريزما أول ما تدخلي أي مكان.. فالحلقة دي معمولة عشانك! في حلقة النهاردة من بودكاست وعي، هنتكلم في كلام حقيقي وعملي عن: 🔹 إزاي تفرضي هيبتك و قوة شخصيتك وتتكلمي بذكاء (قليل ودل). 🔹 سر الثقة بالنفس 🔹 إزاي تبني صداقات قوية وناجحة من غير ما تخسري نفسك. 🔹 حل نهائي لـ الحساسية المفرطة من ردو', 'https://anchor.fm/s/108148058/podcast/play/122659032/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2026-6-10%2F427723060-44100-2-2c03ee82951a4.mp3', 303, '2026-07-10 15:45:10'::timestamptz, 11000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'بودكاست وعي| حب الذات و الاكتفاء بالنفس', 'بنات رابط الحلقة كامل من هنا ما تنسوا الاشتراك بحبكم ❤️ https://youtu.be/wJhClyVQ5N4?si=Ma_NTZ3xDSCMnXcD لو عايزة حياتك تتبدل بجد.. قربي أكتر من نفسك، واشتغلي عليها، وماتستنيش النهاية لأن المتعة في الطريق.. استمتعي بالرحلة! ✨ أهلاً بيكي في حلقة جديدة من بودكاست وعي بعنوان &quot;غيري حياتك 180 درجة&quot;. في الجلسة النفسية دي، هنتكلم براحتنا وبأمثلة من حياتنا اليومية عن: إزاي تكتفي بنفسك وتحبيها سر الاكتفاء بالذات: إيه هي أسباب عدم اكتفائي بنفسي؟ وليه بنخاف من الوحدة؟ وإيه هي علامات إنك بدأتي تكتفي بنفسك فعلاً ومابقتيش مستنية حد يكملك؟ ، وتعرفي طاقة اللي حواليكي (بيحبوكي ولا لأ)، وتكتشفي العلام', 'https://anchor.fm/s/108148058/podcast/play/121437950/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2026-5-13%2F426086143-44100-2-d8d4fd2206d5a.mp3', 133, '2026-06-13 20:30:56'::timestamptz, 12000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'ليه لازم تسمعى صوتك الداخلى؟ | بودكاست وعي', 'بنات الحلقة كامله على الرابط https://youtu.be/1rKfgCwOhRM?si=DayeJGKDFQdS5peC بودكاست وعى للبنات نصائح يا هلا بيكي يا بطلة في حلقة جديدة وعميقة جداً من بودكاست وعي ☕✨ حلقة النهاردة مش مجرد نصايح، دي جلسة نفسية (Psychological Session) من القلب لكل بنت حاسة إنها تايهة، مطفية، أو بتيجي على نفسها زيادة عن اللزوم عنوان حلقتنا النهاردة هو السر اللي هيغير حياتك: &quot;لا تهملي إحساسك&quot; كم مرة حصلك موقف في الشغل، أو مع صحابك، أو حتى وسط عيلتك، وحسيتي بـ قبضة في قلبك أو إشارة بتقولك الموقف ده مش مريح، وبدل ما تسمعي لصوتك الداخلي ، دوّستي على إحساسك وقولتي: أنا أكيد متهيألي.. بلاش نكد بقى؟ في الحلقة', 'https://anchor.fm/s/108148058/podcast/play/120784633/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2026-4-31%2F425213885-44100-2-799905135fe47.mp3', 178, '2026-05-31 07:41:23'::timestamptz, 13000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'أسرار الكاريزما والهيبة للبنات | بودكاست وعي', 'رابط الحلقة كامله من هنا ما تنسي الاشتراك بالقناة https://youtu.be/tKFtuFIICgU?si=6Lsds6ET7YMwxkWd أهلاً بيكي يا بطلة في حلقة جديدة من البودكاست.. النهاردة القعدة &quot;بيني وبينك&quot;. ☕✨ لو حاسة إن حقك بيضيع، أو إنك &quot;حساسة زيادة&quot; من كلام الناس، أو نفسك يكون ليكي حضور وكاريزما أول ما تدخلي أي مكان.. فالحلقة دي معمولة عشانك! هنتكلم في الحلقة دي عن: إزاي تفرضي هيبتك وتتكلمي بذكاء (قليل ودل). سر الثقة بالنفس وإزاي متبقيش &quot;مدلوقة&quot; في العلاقات. إزاي تبني صداقات قوية وناجحة من غير ما تخسري نفسك. حل نهائي لـ الحساسية المفرطة من ردود أفعال الآخرين. إزاي توازني بين شغلك، حياتك، وو', 'https://anchor.fm/s/108148058/podcast/play/117347991/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2026-2-23%2F420591429-44100-2-2cdf09f7a3a95.mp3', 238, '2026-03-23 12:52:44'::timestamptz, 14000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'بودكاست وعي| تعلمى الانجاز الصامت و اسرار النجاح', 'لمشاهده الحلقة كاملة من الرابط https://youtu.be/0UnHRVB-BSc?si=hl0hjbpj-Rqbmf6- بودكاست وعي| تعلمى الانجاز الصامت و اسرار النجاح تطوير الذات -الثقة بالنفس- الاكتفاء بالذات', 'https://anchor.fm/s/108148058/podcast/play/115875301/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2026-1-22%2F418596984-44100-2-7db42b448aa2.mp3', 142, '2026-02-22 17:36:09'::timestamptz, 15000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'بودكاست وعي| غيري تفكيرك تتغير حياتك كلها', 'رابط الحلقة كامله https://youtu.be/AT1QcM31Hbg?si=6_E3gPSuLeOZYssq هل حاسة إن حياتك واقفة؟ أو دايمًا بتدخلي علاقات متعبة؟ أو بتحسي إنك مش مختارة؟ في الفيديو ده هنعمل جلسة بنات عميقة نتكلم فيها عن: إزاي تفكيرك بيتكوّن وبيأثر على حياتك إيه اللي بيشوّه طريقة تفكيرك من غير ما تحسي إزاي تغيّري تفكيرك من الجذور مش بشكل مؤقت إزاي تفكيرك الإيجابي الواعي يجذب الناس ليكي أسرار العلاقات الصحية وحدود احترام النفس قصص حقيقية من الحياة عن بنات غيروا تفكيرهم فاتغيرت حياتهم الفيديو مناسب لكل بنت: تعبت من العلاقات السامة حابة تطوّر نفسها عايزة تعيش بهدوء واستحقاق وعايزة تفهم نفسها بعمق 📌 لو الفيديو لمس قلبك، ', 'https://anchor.fm/s/108148058/podcast/play/113283518/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2025-11-30%2F415213545-44100-2-7aec72fae680d.mp3', 1760, '2025-12-30 12:14:10'::timestamptz, 16000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'بودكاست وعي | تطوير الذات| التفكير الايجابي', 'رابط الحلقة كامله https://youtu.be/AT1QcM31Hbg?si=6_E3gPSuLeOZYssq هل حاسة إن حياتك واقفة؟ أو دايمًا بتدخلي علاقات متعبة؟ أو بتحسي إنك مش مختارة؟ في الفيديو ده هنعمل جلسة بنات عميقة نتكلم فيها عن: إزاي تفكيرك بيتكوّن وبيأثر على حياتك إيه اللي بيشوّه طريقة تفكيرك من غير ما تحسي إزاي تغيّري تفكيرك من الجذور مش بشكل مؤقت إزاي تفكيرك الإيجابي الواعي يجذب الناس ليكي أسرار العلاقات الصحية وحدود احترام النفس قصص حقيقية من الحياة عن بنات غيروا تفكيرهم فاتغيرت حياتهم الفيديو مناسب لكل بنت: تعبت من العلاقات السامة حابة تطوّر نفسها عايزة تعيش بهدوء واستحقاق وعايزة تفهم نفسها بعمق 📌 لو الفيديو لمس قلبك، ', 'https://anchor.fm/s/108148058/podcast/play/112869429/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2025-11-19%2F414686923-44100-2-54f3d52af99ee.mp3', 119, '2025-12-19 12:58:31'::timestamptz, 17000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'بودكاست وعي| لا تكوني حساسة تعلمي الهدوء و القوة', 'الحلقة كاملة على الرابط https://www.youtube.com/@Wahe4 هنتكلم عن: • أسباب الحساسية الزايدة عند المرأة • التعامل مع الزوج بدون توتر أو مبالغة • إزاي طاقتك بتأثر على طاقة البيت • خطوات بناء هدوء داخلي وثقة بالنفس • الهدوء كقوة أنثوية جذابة #العلاقات #تطوير_الذات #الطاقة_الأنثوية #الزواج #وعي_أنثوي #الثقة_بالنفس #الحب #الأنوثة #الهدوء #سلام_نفسي #الحساسية_الزائدة #قوة_الأنثى #طاقة_الهدوء #وعي #علاقات_زوجية #طاقة_إيجابية #نضج_عاطفي #ازاي_اتعامل_مع_جوزي #قوة_الهدوء #اتزني #خليك_هادية #ما_تكونيش_حساسة', 'https://anchor.fm/s/108148058/podcast/play/111404334/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2025-10-19%2F412768641-44100-2-d3cfb9853cb03.mp3', 216, '2025-11-19 12:20:37'::timestamptz, 18000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'بودكاست وعي| الانوثة الجذابة للجميع كوني انثي مكتملة', 'الحلقة كامله علي للمتابعة على يوتيوب قناة بودكاست وعي ابحثى عن @wahe4 ‎رابط القناة https://www.youtube.com/@Wahe4 ‎بودكاست وعي يتحدث عن ‎❤️تابعونا هنا و الفيديو كامل على اليوتيوب لو حسيتي إنك فقدتي لمسة الأنوثة في العلاقة أو بقيتي مضغوطة من كتر المسؤوليات، الفيديو ده ليكي 💖 هنتكلم بعمق عن: • إزاي ترجعي تمارسي أنوثتك مع جوزك بطريقة ذكية ومتوازنة • إزاي تتعاملي معاه بحب وهدوء من غير ما تفقدي احترامك • خطوات يومية وأمثلة حقيقية تخليه يحبك أكتر ويقرب منك من غير ما تطلبي • تمارين صوت وجسد بسيطة ترجّع جاذبيتك الطبيعية ✨ الفيديو فيه أسرار الأنثى الهادية القوية، واللي بتعرف تمسك قلب الراجل وتخليه ميش', 'https://anchor.fm/s/108148058/podcast/play/110502158/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2025-9-31%2F410349703-44100-2-179ade1453f3c.mp3', 113, '2025-10-31 17:31:03'::timestamptz, 19000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'بودكاست وعي| غيري تجاهل الرجل الي إهتمام', '‎الحلقة كامله علي اليوتيوب قناة بودكاست وعي ابحثى عن @wahe4 ‎رابط القناة https://www.youtube.com/@Wahe4 بودكاست وعي ‎تابعونا هنا و الفيديو كامل على اليوتيوب ‎بودكاست غيري تجاهل الرجل الى اهتمام فى العلاقة ‎ في الفيديو هنتكلم عن 👇 ‎💬 أسباب التجاهل وليه بيحصل. ‎💬 الأخطاء اللي بتخلي التجاهل يزيد. ‎💬 خطوات ذكية تخلي الشخص اللي تجاهلك يرجع يهتم بيكي من تاني. ‎💬 إزاي تستخدمي قوة أنوثتك وثقتك بنفسك علشان تكوني دايمًا في مكان القوة. ‎الفيديو ده ليكي لو: ‎ • اتجرحتي من تجاهل شخص كنتي بتحبيه. ‎ • نفسك تفهمي إزاي تردي بقوة وذكاء. ‎ • عايزة تخليه هو اللي يسعى وراكي بدل ما تكوني انتي اللي بتجري وراه ‎', 'https://anchor.fm/s/108148058/podcast/play/110288206/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2025-9-27%2F410068211-44100-2-4f0372e1326ae.mp3', 96, '2025-10-27 17:59:05'::timestamptz, 20000);
