  VALUES (v_pod_id, 'بودكاست وعي| كيف تجذبي الرجل لك|فن العلاقات', 'بودكاست كيف تجعلي الرجل يراك كزوجة فن العلاقات هل هو حب ام تسلية اجابه علي اسئلة كثيرة عن العلاقات الصحيحة و الناجحة فك التعلق حب الذات تطوير الذات', 'https://anchor.fm/s/108148058/podcast/play/106780802/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fstaging%2F2025-7-12%2F405554251-44100-2-6e333cb8638da.mp3', 1311, '2025-08-12 18:46:15'::timestamptz, 29000);
