-- ---------- Culips Everyday English Podcast ----------
DO $$
DECLARE
  v_host_id uuid;
  v_pod_id uuid;
  v_cat uuid;
BEGIN
  SELECT id INTO v_cat FROM categories WHERE name_ar = 'ثقافة وأدب' LIMIT 1;
  INSERT INTO hosts (name_ar, slug, photo_url, cover_url, title_ar, specialty_ar, bio_ar, country, category_id, is_verified, followers_count)
  VALUES ('Culips English Podcast', 'culips-everyday-english-podcast', 'https://is1-ssl.mzstatic.com/image/thumb/Podcasts125/v4/ca/bd/be/cabdbe46-9408-6ff9-dd4c-fa944d90d9f4/mza_9088968848133222748.jpg/600x600bb.jpg', 'https://is1-ssl.mzstatic.com/image/thumb/Podcasts125/v4/ca/bd/be/cabdbe46-9408-6ff9-dd4c-fa944d90d9f4/mza_9088968848133222748.jpg/600x600bb.jpg', 'مقدم', 'ثقافة وأدب', 'بودكاست حقيقي: Culips Everyday English Podcast', 'أونلاين', v_cat, true, 50000)
  RETURNING id INTO v_host_id;

  INSERT INTO podcasts (title, description, host_id, category_id, type, cover_url, audience_level, plays_count, rating_avg)
  VALUES ('Culips Everyday English Podcast', 'Culips English Podcast: Practical English Learning Made Fun Learn and Explore: Join Culips for an exciting English learning journey. Our podcast focuses on teaching English idioms, slang, and phrasal verbs through fun and engaging conversations. Each episode helps you master English for real-life situations. Unique Learning Experience: Culips stands out by blending language skills with cultural insights. Our diverse hosts make learning relatable, covering a variety of everyday topics. You&#8217;ll pick up practical language skills and gain cultural understanding, enhancing your English fluency', v_host_id, v_cat, 'cultural', 'https://is1-ssl.mzstatic.com/image/thumb/Podcasts125/v4/ca/bd/be/cabdbe46-9408-6ff9-dd4c-fa944d90d9f4/mza_9088968848133222748.jpg/600x600bb.jpg', 'beginner', 100000, 4.7)
  RETURNING id INTO v_pod_id;

  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Chatterbox #355 &#8211; Hobbyamory', 'Andrew and Anna talk about a New York Times article on “hobbyamory,” a new trend where young single people stop using dating apps and fill their lives with hobbies instead. They also ask whether the trend is good news, or a sign that many young people are lonely and struggling with money. Along the way, you&#8217;ll learn useful English vocabulary like “to have reservations,” “mutually exclusive,” “cope,” “to not fit the mold,” “underpinnings,” and “to keep afloat.” The brand-new Culips app is live! Study this episode with an interactive transcript and vocabulary glossary: Open this lesson in ', 'https://media.blubrry.com/culips/content.blubrry.com/culips/CB355_Regular.mp3', 2488, '2026-11-13 22:16:29'::timestamptz, 5000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Simplified Speech #256 &#8211; Naps', 'Do you feel better or worse after a nap? Andrew and Indiana compare their napping habits, and Andrew explains his favorite trick, the coffee nap. They also talk about why it&#8217;s so common to see people sleeping on the subway in Korea. Along the way, you&#8217;ll learn useful English vocabulary like “to squeeze something in,” “cottonmouth,” “to defeat the purpose,” “for something to hit,” and “to keep something up.” The brand-new Culips app is live! Study this episode with an interactive transcript and vocabulary glossary: Open this lesson in the Culips app . The Best Way to Learn with This', 'https://media.blubrry.com/culips/content.blubrry.com/culips/SS256_Regular.mp3', 790, '2026-11-03 18:07:37'::timestamptz, 6000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Bonus Episode #183 &#8211; Chestnut Hunter', 'Have you ever been so focused on one goal that you forgot to slow down? In this bonus episode, Andrew spends a holiday afternoon trying something new with his family, and it makes him rethink how he spends his free time. Listen along to learn some vocabulary that will help make your English more natural and to improve your listening fluency. The brand new Culips app is live! Study this episode with an interactive transcript and vocabulary glossary: Open this lesson in the Culips app . Study materials for this episode The interactive transcript and vocabulary glossary are free for everyone. No ', 'https://media.blubrry.com/culips/content.blubrry.com/culips/B183_Regular.mp3', 1558, '2026-10-30 21:52:29'::timestamptz, 7000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Simplified Speech #255 &#8211; Halloween 2026', 'Is Halloween a big deal where you live? Andrew and Indiana share their favorite childhood Halloween memories and the costumes they&#8217;re most proud of, and Indiana explains how trick-or-treating works for anyone who didn&#8217;t grow up with it. Along the way, you&#8217;ll learn useful English vocabulary like “to go hard,” “to liven up,” “to be over something,” “a gripe,” “to wane,” and “groundless.” The brand-new Culips app is live! Study this episode with an interactive transcript and vocabulary glossary: Open this lesson in the Culips app . The Best Way to Learn with This Episode: Culips', 'https://media.blubrry.com/culips/content.blubrry.com/culips/SS255_Regular.mp3', 1837, '2026-10-25 17:55:22'::timestamptz, 8000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Simplified Speech #254 &#8211; The death of the landline', 'Do you still remember your best friend&#8217;s phone number from when you were a kid? Andrew and Indiana share some fun memories from the days when every home had a phone connected to the wall, and talk about the pros and cons of life with a landline. Along the way, you&#8217;ll learn useful English vocabulary like “a peek behind the curtain,” “to get through to someone,” “a comedy of errors,” “fishy,” “to come in handy,” and “peak something.” The brand-new Culips app is live! Study this episode with an interactive transcript and vocabulary glossary: Open this lesson in the Culips app . The Be', 'https://media.blubrry.com/culips/content.blubrry.com/culips/SS254_Regular.mp3', 1637, '2026-10-17 00:32:12'::timestamptz, 9000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Chatterbox #354 &#8211; Giving it your all', 'Would you keep going in a race if something embarrassing happened to you halfway through? Andrew and Anna talk about an Australian athlete who had a bathroom accident during a Hyrox race in Beijing and kept going until she won. They discuss why the story traveled so fast online, what it meant for her sponsors, and whether pushing yourself to your limit is always a good thing. Along the way, you&#8217;ll hear expressions like “to have one&#8217;s blinkers on,” “a perfect storm,” “blowback,” “plastered all over,” “to spread like wildfire,” and “to lay low.” Listening to Andrew and Anna share the', 'https://media.blubrry.com/culips/content.blubrry.com/culips/CB354_Regular.mp3', 822, '2026-10-10 16:34:48'::timestamptz, 10000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Bonus Episode #182 &#8211; Feel the Burn', 'In this bonus episode, Andrew tells the story of something new that he and his wife recently started together, and what it&#8217;s like to be a total beginner again. Listen along to learn some vocabulary that will help make your English more natural and to improve your listening fluency. The brand new Culips app is live! Study this episode with an interactive transcript and vocabulary glossary: Open this lesson in the Culips app . Tell us about a time you were a beginner! Record a two-minute audio story about an awkward, funny, or embarrassing moment from trying something new, and Andrew might', 'https://media.blubrry.com/culips/content.blubrry.com/culips/B182_Regular.mp3', 1837, '2026-10-05 01:03:36'::timestamptz, 11000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Simplified Speech #253 &#8211; What&#8217;s your Achilles Heel?', 'What&#8217;s the one thing you just can&#8217;t say no to? Andrew and Indiana share their biggest weaknesses when it comes to food, shopping, screen time, and a few basic life skills, and Andrew tells a story about an unexpected visitor at his desk. Along the way, you&#8217;ll learn how to use “Achilles heel,” “a goody two-shoes,” “mid,” “cooked,” “your own worst enemy,” and “a coping mechanism.” The brand-new Culips app is live! Study this episode with an interactive transcript and vocabulary glossary: Open this lesson in the Culips app . The Best Way to Learn with This Episode: Culips member', 'https://media.blubrry.com/culips/content.blubrry.com/culips/SS253_Regular.mp3', 1747, '2026-09-26 17:43:23'::timestamptz, 12000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Chatterbox #353 &#8211; United by Sport', 'Does sport bring people together, or does it divide us? Andrew and Anna&#8217;s conversation moves from the World Cup to the Olympics, the Commonwealth Games, and even esports. Along the way, you&#8217;ll hear expressions like “in the wake of,” “to not have a dog in the fight,” “emotionally charged,” “over the top,” “good grief,” and “to check a box.” The brand-new Culips app is live! Study this episode with an interactive transcript and vocabulary glossary: Open this lesson in the Culips app . The Best Way to Learn with This Episode: Culips members get an interactive transcript, helpful study', 'https://media.blubrry.com/culips/content.blubrry.com/culips/CB353_Regular.mp3', 1969, '2026-09-20 17:59:18'::timestamptz, 13000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Catch Word #295 &#8211; 5 Must-Know Meeting Expressions', 'In this Catch Word lesson, Andrew and Indiana teach you five English expressions that are often used in meetings and in the workplace: &#8220;circle back,&#8221; &#8220;touch base,&#8221; &#8220;drop the ball,&#8221; &#8220;in the weeds,&#8221; and &#8220;move the needle.&#8221; Learning these expressions will help you be a clearer speaker and a better listener the next time you find yourself in a meeting. The brand-new Culips app is live! Study this episode with an interactive transcript and vocabulary glossary: Open this lesson in the Culips app . Keep an ear out for these phrases during the', 'https://media.blubrry.com/culips/content.blubrry.com/culips/CW295_Regular.mp3', 1484, '2026-09-13 17:34:21'::timestamptz, 14000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Bonus Episode #181 &#8211; Summer&#8217;s Last Hurrah', 'In this bonus episode, Andrew takes one day off at the end of the summer and heads to the beach with his wife. They are only away for 24 hours, but they fit a lot into it. Listen along to learn some vocabulary that will help make your English more natural and to improve your listening fluency. The brand new Culips app is live! Study this episode with an interactive transcript and vocabulary glossary: Open this lesson in the Culips app. Study materials for this episode The interactive transcript and vocabulary glossary are free for everyone. No membership needed. The comprehension quiz and the ', 'https://media.blubrry.com/culips/content.blubrry.com/culips/B181_Regular.mp3', 2227, '2026-09-07 18:35:39'::timestamptz, 15000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Simplified Speech #252 &#8211; Bikes, gardens, art, and AI coaches', 'Hang out with your English-speaking friends, Andrew and Indiana, for a catch-up! Indiana has been growing tomatillos on her patio, and she rode 40 miles along New York&#039;s Empire State Trail on a very hot day, though the ride did not go the way she planned. Andrew went to see a Damien Hirst exhibition at the National Museum of Modern and Contemporary Art in Seoul, and he has been letting an AI design his marathon training plan. The brand-new Culips app is live! Study this episode with an interactive transcript and vocabulary glossary: Open this lesson in the Culips app. Keep an ear out for ', 'https://media.blubrry.com/culips/content.blubrry.com/culips/SS252_Regular.mp3', 2220, '2026-08-31 20:26:57'::timestamptz, 16000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Bonus Episode #180 &#8211; Fall Between the Cracks', 'In this bonus episode, Andrew tells the story of the most stressful morning he&#039;s had in a long time, and it all started with something small that ended up in a place he couldn&#039;t reach. Listen along to learn some vocabulary that will help make your English more natural and to improve your listening fluency. The brand new Culips app is live! Study this episode with an interactive transcript and vocabulary glossary: Open this lesson in the Culips app. Tell us about your own terrible morning! Record a two-minute audio story and Andrew might share it in a future episode: Record your story', 'https://media.blubrry.com/culips/content.blubrry.com/culips/B180_Regular.mp3', 1761, '2026-08-26 00:29:45'::timestamptz, 17000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Chatterbox #352 &#8211; Hot hot summer', 'What does a heat wave actually do to your day? Andrew and Anna compare their summers from opposite sides of the world. Anna is in Madrid, where a hot day reaches 40 degrees and the blinds stay closed until evening. Andrew is in Seoul, where the rainy season just ended but the humidity stayed. They talk about air conditioning, lost sleep, cold showers, and the wildfires that burned west of Madrid this summer. Keep an ear out for these phrases during the episode: Not so fast Respite Bar none To do one&#039;s business Bone dry To burn to a crisp Study Materials: Episode link: The 2026 Spain wildf', 'https://media.blubrry.com/culips/content.blubrry.com/culips/CB352_Regular.mp3', 2222, '2026-08-18 02:59:12'::timestamptz, 18000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Bonus Episode #179 &#8211; One More Try', 'In this bonus episode, Andrew picks up the story he started last time and tells you what happened next. He heads out to the edge of the city on a hot summer evening and gets home much later than he planned. Listen along to learn some vocabulary that will help make your English more natural and to improve your listening fluency. The brand-new Culips app is live! Study this episode with an interactive transcript and vocabulary glossary: Open this lesson in the Culips app. Expressions To set the stage To count down the days Headlining The tail end A certain je ne sais quoi When all is said and do', 'https://media.blubrry.com/culips/content.blubrry.com/culips/B179_Regular.mp3', 1881, '2026-08-11 20:50:55'::timestamptz, 19000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Chatterbox #351 &#8211; From Intermediate to Fluent', 'How do you get from intermediate English to sounding almost like a native speaker? Jesús Florez did it, and he&#039;s back on the show to tell Andrew how. He explains the years he spent creating his own English immersion at home and names the four shows that finally moved him up to an advanced level. Listen in to hear his story and his advice for taking your own English to the next level. The brand-new Culips app is live! Study this episode with an interactive transcript and vocabulary glossary: Open this lesson in the Culips app. Free Resources and Links The interactive transcript, study guid', 'https://media.blubrry.com/culips/content.blubrry.com/culips/CB351_Regular.mp3', 3201, '2026-08-06 20:18:41'::timestamptz, 20000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Bonus Episode #178 &#8211; Once in a Lifetime', 'Have you ever gotten a second chance at something you thought you would only get to do once? In this bonus episode, Andrew talks about the first Culips meetup in Seoul and then tells the story of trying to see one of his favorite bands play a second time. Listen along to learn some vocabulary that will help make your English more natural and improve your listening fluency. The brand-new Culips app is live! Study this episode with an interactive transcript and vocabulary glossary: Open this lesson in the Culips app. Expressions A turnout To talk into the void To be taken aback A high-water mark', 'https://media.blubrry.com/culips/content.blubrry.com/culips/B178_Regular.mp3', 1605, '2026-08-03 18:29:45'::timestamptz, 21000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Catch Word #294 &#8211; Touch Grass', 'Have you ever looked up from your phone and realized that an hour just disappeared? In this Catch Word lesson, Andrew and Indiana teach you how to tell someone to &quot;touch grass&quot; and how to describe a person as &quot;terminally online&quot; or &quot;chronically online.&quot; They explain the difference in tone between these expressions, why &quot;touch grass&quot; can sound like a real insult, and when each one is appropriate to use. The brand-new Culips app is live! Study this episode with an interactive transcript and vocabulary glossary: Open this lesson in the Culips app. Keep an e', 'https://media.blubrry.com/culips/content.blubrry.com/culips/CW294_Regular.mp3', 1264, '2026-07-26 22:04:31'::timestamptz, 22000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Chatterbox #350 &#8211; Hyperblanding', 'Have you ever traveled to a city far from home and felt like you had already been there? The same coffee shops, the same clothing stores, even the same songs playing inside the cafes. In this Chatterbox episode, Andrew and Anna talk about hyperblanding, the idea that fashion, music, food, and design all over the world are slowly becoming the same. The word comes from a 2026 trend report, and you can read more about it here. Listen to the full conversation to learn what hyperblanding is, decide if you agree with the idea, and build your English fluency at the same time. The brand-new Culips app', 'https://media.blubrry.com/culips/content.blubrry.com/culips/CB350_Regular.mp3', 2184, '2026-07-19 18:03:00'::timestamptz, 23000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Simplified Speech #251 &#8211; Popular baby names', 'What does a name really say about a person? In this episode, Andrew and Indiana talk about baby names and the stories behind them. They chat about how naming has changed in North America since the 1950s. You&#039;ll also hear about old-fashioned virtue names, why so many parents today want something different, and the existence of &quot;middle names&quot; in the U.S. and Canada. The brand-new Culips app is live! Study this episode with an interactive transcript and vocabulary glossary: Open this lesson in the Culips app. To build your fluency, try listening to the episode more than once and sa', 'https://media.blubrry.com/culips/content.blubrry.com/culips/SS251_Regular.mp3', 1862, '2026-07-11 19:59:39'::timestamptz, 24000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Simplified Speech #250 &#8211; Weird and wacky questions', 'How do you like your eggs? It sounds like a small question, but the answer can tell you a lot about a person. In this episode, Andrew surprises his co-host Kassy with a list of weird, wacky, and random questions. She hasn&#039;t seen them before, so you get to hear her real, unplanned answers. They talk about all sorts of everyday things, from what they would want to be famous for to how they wake up in the morning, and they use some natural expressions that native speakers say all the time. The brand-new Culips app is live! Study this episode with an interactive transcript and vocabulary glos', 'https://media.blubrry.com/culips/content.blubrry.com/culips/SS250_Regular.mp3', 1847, '2026-07-04 23:28:18'::timestamptz, 25000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Bonus Episode #177 &#8211; Three Horses in the Race', 'In this bonus episode, Andrew shares a few quick updates from behind the scenes at Culips and tells a story about following the World Cup as a fan with more than one team to cheer for. Listen along to learn some vocabulary that will help make your English more natural and improve your listening fluency. The brand-new Culips app is live! Study this episode with an interactive transcript and vocabulary glossary: Open this lesson in the Culips app. Free study guide: This episode comes with a free study guide for everyone. Download it to review the vocabulary, follow along with the episode, and pr', 'https://media.blubrry.com/culips/content.blubrry.com/culips/B177_Regular.mp3', 1086, '2026-06-28 21:12:08'::timestamptz, 26000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Chatterbox #349 &#8211; Using AI for health advice', 'Have you ever asked the internet about a health problem before asking a doctor? In this episode, Andrew and Anna talk about using AI tools like ChatGPT and Gemini for health advice, and whether you can really trust them. Andrew shares a small health problem of his own and the answer he got from AI, and together they work out when a chatbot is actually helpful and when it is time to see a real doctor. Along the way they get into how confident these tools sound, who should be responsible when the advice is wrong, and what a visit to the doctor might look like in the future. The brand-new Culips ', 'https://media.blubrry.com/culips/content.blubrry.com/culips/CB349_Regular.mp3', 2008, '2026-06-25 18:41:54'::timestamptz, 27000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Simplified Speech #249 &#8211; iPod Archeology', 'What do you think is hiding on a 20-year-old iPod that someone forgot in a drawer? In this episode, Andrew and Indiana share three news stories and trends they came across recently. The first is about a woman who buys old iPods and shares the playlists she finds on them, like a small window into strangers&#039; lives. After that, they talk about a new idea for spending less time on your phone, and a surprising change in what makes food popular today. To build your fluency, try listening to the episode more than once and saying the new expressions out loud until you feel comfortable using them ', 'https://media.blubrry.com/culips/content.blubrry.com/culips/SS249_Regular.mp3', 2041, '2026-06-18 16:18:28'::timestamptz, 28000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Bonus Episode #176 &#8211; Take Me Out', 'Have you ever loved something your partner just won&#039;t try? For years, Andrew&#039;s wife said no to baseball. In this bonus episode, he finally gets her to the ballpark and finds out what she really thinks. Listen along to learn some vocabulary that will help make your English more natural and to improve your listening fluency. The brand-new Culips app is live! Study this episode with an interactive transcript and vocabulary glossary: Open this lesson in the Culips app. Study resources: Become a Culips member: Join the Culips Discord server: Get the interactive transcript and vocabulary g', 'https://media.blubrry.com/culips/content.blubrry.com/culips/B176_Regular.mp3', 1842, '2026-06-14 17:21:58'::timestamptz, 29000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Chatterbox #348 &#8211; Digital Twins', 'What if there were a copy of you at work, answering emails and joining meetings while you slept? After Anna read a BBC article about people who are building AI versions of themselves, she brought the idea to Andrew, and the two of them talk about what these &quot;digital twins&quot; could mean for the rest of us. They look at the same question from three sides, the worker, the boss, and the business owner, and they keep coming back to one worry. If a company has a copy of you, do they still need you? Read the original BBC article on digital twins here: The brand-new Culips app is live! Study t', 'https://media.blubrry.com/culips/content.blubrry.com/culips/CB348_Regular.mp3', 1696, '2026-06-11 22:07:46'::timestamptz, 30000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Catch Word #293 &#8211; Chinamaxxing', 'Have you started seeing videos that celebrate Chinese culture all over your feed, like someone swapping coffee for green tea? Andrew and Indiana noticed this trend too, and in this episode they teach three pieces of China-related slang and ask why it is all happening now. Their answer touches on the Djo song that went viral on TikTok, the move from TikTok to RedNote, soft power, and Canada&#039;s anti-tariff billboards in the US. The brand-new Culips app is live! Study this episode with an interactive transcript and vocabulary glossary: Open this lesson in the Culips app. To build your fluency', 'https://media.blubrry.com/culips/content.blubrry.com/culips/CW293_Regular.mp3', 1968, '2026-06-04 21:25:11'::timestamptz, 31000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Bonus episode #175 &#8211; Time on My Mind', 'In this bonus episode, Andrew shares some thoughts that have been on his mind lately about time and the way we experience it. He looks back a little, sits with the present moment, and wonders about what&#039;s coming. Listen along to learn some vocabulary that will help make your English more natural and to improve your listening fluency. The brand-new Culips app is live! Study this episode with an interactive transcript and vocabulary glossary: Open this lesson in the Culips app. Links mentioned in this episode: Spem in Alium by Thomas Tallis: Click here The Orchestra of the Age of Enlightenm', 'https://media.blubrry.com/culips/content.blubrry.com/culips/B175_Regular.mp3', 1406, '2026-05-31 23:10:03'::timestamptz, 32000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Simplified Speech #248 &#8211; Life lately', 'What have you been up to lately? In this Simplified Speech catch-up episode, Andrew and Kassy share stories from the past month. Kassy talks about a family visit to Jeju Island, where rainy weather didn&#039;t stop them from hiking Hallasan, the tallest mountain in South Korea, and seeing some of the island&#039;s stranger attractions. Andrew shares what happened during his birthday and fifth wedding anniversary, which fell in the same week and involved more cake than one person should eat in seven days. The brand-new Culips app is live! Study this episode with an interactive transcript and vo', 'https://media.blubrry.com/culips/content.blubrry.com/culips/SS248_Regular.mp3', 1679, '2026-05-28 16:51:35'::timestamptz, 33000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Chatterbox #347 &#8211; Things I wish I knew earlier', 'What&#039;s one thing you wish you had known sooner? In this Chatterbox episode, Andrew sits down with Michael Lavers from the Level Up English Podcast for an honest conversation about regrets, missed chances, and the things we wish we had figured out earlier. They share stories about money mistakes, bad clothing buys, language learning, and the surprising lessons that come with getting older. The brand-new Culips app is live! Study this episode with an interactive transcript and vocabulary glossary: Open this lesson in the Culips app. Check Out Michael&#039;s Work: Level Up English website: T', 'https://media.blubrry.com/culips/content.blubrry.com/culips/CB347_Regular.mp3', 2441, '2026-05-21 20:38:40'::timestamptz, 34000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Simplified Speech #247 &#8211; Why do we dream', 'Why do we dream? In this Simplified Speech episode, Andrew and Indiana share their own theories about what dreams are for, the strangest recurring nightmares they&#039;ve had, and a uniquely Korean kind of dream that&#039;s said to predict pregnancy. They also get into sleepwalking, snoring, and the small habits that can quietly ruin your sleep. The brand-new Culips app is live! Study this episode with an interactive transcript and vocabulary glossary: Open this lesson in the Culips app. References: Wikipedia, Conception dreams — Read here: Keep an ear out for these phrases during the episode:', 'https://media.blubrry.com/culips/content.blubrry.com/culips/SS247_Regular.mp3', 2106, '2026-05-15 17:05:05'::timestamptz, 35000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Bonus episode #174 &#8211; Out-of-town Trip', 'In this bonus episode, Andrew shares a story about a weekend trip he took to visit two old friends in another city. They met up to hang out, do a challenging activity, and then enjoy some good times together. Listen along to learn some vocabulary that will help make your English more natural and to improve your listening fluency. The brand-new Culips app is live! Study this episode with an interactive transcript and vocabulary glossary: Open this lesson in the Culips app. GLOSSARY EXPRESSIONS Get your act together In for a world of pain Talk your ear off Crash out Kaput Rip-off Putter around L', 'https://media.blubrry.com/culips/content.blubrry.com/culips/B174_Regular.mp3', 1964, '2026-05-11 17:32:43'::timestamptz, 36000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Chatterbox #346 &#8211; The psychology of spending money', 'Why does paying with cash feel different from tapping your phone? In this Chatterbox episode, Andrew and Anna talk about the psychology of spending money. They share what they happily pay extra for, what they refuse to spend on, and the small tricks companies use to get more money out of our wallets. Along the way, they look at why we sometimes feel like we got a great deal even when we just spent five times what we intended. Listening to many natural responses is one of the best ways to build your everyday listening skills in English. The brand-new Culips app is live! Study this episode with ', 'https://media.blubrry.com/culips/content.blubrry.com/culips/CB346_Regular.mp3', 1940, '2026-05-07 21:00:49'::timestamptz, 37000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Real Talk #67 &#8211; How to answer the question &#8216;how are you?&#8217;', 'How do you answer the question, &quot;How are you?&quot; It sounds simple, but native English speakers actually use a wide variety of answers. In this Real Talk episode, Andrew and Kassy share more than 30 common replies, including standard answers, sarcastic ones, and phrases people use on a busy or tough day. They explain what each phrase really means and the situations where you&#039;ll hear it. Listening to many natural responses is one of the best ways to build your everyday listening skills in English. The brand-new Culips app is live! Study this episode with an interactive transcript an', 'https://media.blubrry.com/culips/content.blubrry.com/culips/RT67_regular.mp3', 1635, '2026-05-01 02:25:14'::timestamptz, 38000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Bonus episode #173 &#8211; A Tale of FOMO', 'Have you ever felt the fear of missing out on something exciting? In this bonus episode, Andrew talks about FOMO, finding yourself in a funk, exercising your green thumb, and growing your own food. Listen along to learn some vocabulary that will help make your English more natural and to improve your listening fluency. The brand-new Culips app is live! Study this episode with an interactive transcript and vocabulary glossary: Open this lesson in the Culips app. English Expressions featured in this episode FOMO On the ball To full send (it) To throw your hat into the ring To keep your eyes peel', 'https://media.blubrry.com/culips/content.blubrry.com/culips/B173_Regular.mp3', 1757, '2026-04-26 15:44:36'::timestamptz, 39000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Chatterbox #345 &#8211; Interview with Michael Lavers', 'From Cornwall to Bangkok: Cycling, Podcasting, and Pop Culture with Michael Lavers Would you leave England to start a new life in Bangkok? Would you plan a cycling trip across an entire country? In this episode, Andrew interviews Michael Lavers from the Level Up English Podcast, a British podcaster who is doing exactly that. They chat about growing up in Cornwall, moving to Thailand, cycling adventures, and the challenges of learning Thai. Andrew ends the conversation with some quick questions about British pop culture that surprise even Michael! Listening to long conversations like this one i', 'https://media.blubrry.com/culips/content.blubrry.com/culips/CB345_Regular.mp3', 2181, '2026-04-22 20:08:31'::timestamptz, 40000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Simplified Speech #246 &#8211; Never have I ever', 'Have you ever returned food at a restaurant? Fired a real gun? Used a fake ID to buy alcohol? Andrew and Indiana play Never Have I Ever in this episode, a popular North American game where players share the surprising things they have or have not done in their lives. Who has done more? Listen to find out, and learn some useful English expressions along the way. Listening to natural English conversations like this one is a great way to improve your fluency. The brand-new Culips app is live! Study this episode with an interactive transcript and vocabulary glossary: Open this lesson in the Culips', 'https://media.blubrry.com/culips/content.blubrry.com/culips/SS246_Regular.mp3', 1470, '2026-04-17 06:27:12'::timestamptz, 41000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Bonus episode #172 &#8211; Spring Stories', 'In this bonus episode, Andrew shares a couple of stories about what he&#039;s been up to so far this spring, including a hike up a mountain in Seoul to see some spring flowers and doing a big deep clean of his house. Listen along to learn some vocabulary that will help make your English more natural and to improve your listening fluency. The brand-new Culips app is live! Study this episode with an interactive transcript and vocabulary glossary: Open this lesson in the Culips app.', 'https://media.blubrry.com/culips/content.blubrry.com/culips/B172_Regular.mp3', 1706, '2026-04-12 21:08:30'::timestamptz, 42000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Simplified Speech #245 &#8211; Robots and fantasy investing', 'Are robots about to take over our houses? In this Simplified Speech episode, Andrew and Kassy catch up and share what&#039;s new in their lives. Kassy talks about the new robotics program at her school and the family members coming to visit her in Korea, and Andrew explains the strange little experiment he tried to finally get over his fear of the stock market. Kassy also mentions an older episode about the GameStop story, which you can hear in Chatterbox 261 - “Meme stocks” The brand-new Culips app is live! Study this episode with an interactive transcript and vocabulary glossary: Open this l', 'https://media.blubrry.com/culips/content.blubrry.com/culips/SS245_Regular.mp3', 1387, '2026-04-10 21:02:29'::timestamptz, 43000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Chatterbox #344 &#8211; The Ick', 'Have you ever been on a great date, only to suddenly feel completely turned off by something small and unexpected? In this Chatterbox episode, Andrew and Anna talk about &quot;the ick,&quot; that sudden feeling of disgust toward someone you&#039;re dating. They share their own icks, from almond milk to vocal fry, and look at why these reactions happen. Are they silly snap judgments, or could they actually be rooted in something deeper, like evolution or personal values? Practice using the expressions from this episode in your own conversations, and you&#039;ll sound more natural in no time. - ', 'https://media.blubrry.com/culips/content.blubrry.com/culips/CB344_Regular.mp3', 2010, '2026-04-03 06:58:02'::timestamptz, 44000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Bonus episode #171 &#8211; March Madness', 'In this episode, Andrew looks back on March. He ran the Seoul Marathon for the third year in a row after a rough winter of injuries and almost no training. He also tells you about the construction project he and his wife tackled in their yard, and why two weekends of mixing cement felt harder than running 42 kilometers. The brand-new Culips app is live! Study this episode with an interactive transcript and vocabulary glossary: Open this lesson in the Culips app.', 'https://media.blubrry.com/culips/content.blubrry.com/culips/B171_Regular.mp3', 1771, '2026-03-30 07:59:25'::timestamptz, 45000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Real Talk # 66 &#8211; How to tell your server you have food allergies', 'What would you say if you sat down at a restaurant and needed to tell your server about a food allergy? In this episode of Real Talk, Andrew and Indiana teach you practical phrases and expressions for talking about food allergies, food safety, and common menu abbreviations you&#039;ll see in English-speaking countries. Listen to this episode and practice the expressions in the study guide to feel more confident the next time you eat out. The brand-new Culips app is live! Study this episode with an interactive transcript and vocabulary glossary: Open this lesson in the Culips app. Expressions i', 'https://media.blubrry.com/culips/content.blubrry.com/culips/RT66_Regular.mp3', 1450, '2026-03-26 15:09:14'::timestamptz, 46000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Simplified Speech #244 &#8211; Using AI for personal messages', 'Would you use AI to write a birthday message to your best friend? What about a condolence note when someone loses a parent? Inspired by this Guardian article, Andrew and Indiana share their honest opinions on a question a lot of people are asking: is it ever OK to let AI speak for you in your personal life? You&#039;ll learn some useful expressions along the way and probably finish with a stronger opinion than you started with. Listening to real conversations between native speakers is one of the best ways to build your fluency and feel more confident in English. The brand-new Culips app is li', 'https://media.blubrry.com/culips/content.blubrry.com/culips/SS244_Regular.mp3', 2045, '2026-03-19 03:46:11'::timestamptz, 47000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Bonus episode #170 &#8211; Four days in Fukuoka', 'What is it like to travel to Japan for a quick getaway? In this week’s bonus episode, Andrew shares stories from his recent 4-day trip to Fukuoka, Japan with his wife. They explored record stores, enjoyed incredible food, and visited a beautiful art museum. Andrew also tells you about an unexpected running adventure at a local park that turned into a secret competition with a stranger. Listening to this story will help you improve your English fluency. You will also learn useful, everyday words about travel, shopping, food, and city life. The brand-new Culips app is live! Study this episode wi', 'https://media.blubrry.com/culips/content.blubrry.com/culips/B170_Regular.mp3', 1694, '2026-03-16 06:35:25'::timestamptz, 48000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Catch Word #292 &#8211; Stick to your guns', 'In this Catch Word lesson, Andrew and Indiana teach you two useful English idioms: &quot;stick to your guns&quot; and &quot;double down.&quot; Both expressions describe a person who refuses to change their mind, even when they face pressure or criticism. They discuss the small differences between these idioms, explaining why one is often seen as a sign of respect while the other is usually considered stubborn. By listening to their conversation, you will learn how to use these idioms naturally in your own everyday speaking. The brand-new Culips app is live! Study this episode with an interacti', 'https://media.blubrry.com/culips/content.blubrry.com/culips/CW292_Regular.mp3', 1969, '2026-03-12 04:39:50'::timestamptz, 49000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Simplified Speech #243 &#8211; How we learn our second languages', 'In this episode of Simplified Speech, Andrew and Indiana share their personal experiences as language learners. Even though they are English teachers, they also study second languages themselves. They talk about their history with languages like Japanese, German, and Korean, and discuss their favorite study methods and give advice on how to improve your skills. They chat about some of the different ways they remember new vocabulary and why spending time with the language every day is so important. Finally, they also share some funny and unusual tips for practicing speaking without feeling emba', 'https://media.blubrry.com/culips/content.blubrry.com/culips/SS243_Regular.mp3', 2610, '2026-03-05 19:25:54'::timestamptz, 50000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Bonus episode #169 &#8211; Stories from Canada', 'Canada is famous for its cold winters, but what is it really like to visit in January? In this week&#039;s bonus episode, Andrew shares stories about his recent trip back to his hometown in Canada. He traveled there to enjoy the snow and do some classic winter activities. However, the weather didn&#039;t exactly match his plans! You will hear about his experience ice skating high up in the mountains and his trip to watch a local ice hockey game that had a very wild and surprising moment. Listening to this story will help you improve your English fluency. You will also learn useful, everyday wo', 'https://media.blubrry.com/culips/content.blubrry.com/culips/B169_Regular.mp3', 1910, '2026-03-01 19:48:35'::timestamptz, 51000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Simplified Speech # 242 &#8211; Separating the art from the artist', 'In this Simplified Speech episode, Andrew and Indiana discuss a difficult question: Can you separate the art from the artist? Sometimes, famous singers, writers, or actors do bad things or share opinions that hurt other people. Andrew and Indiana talk about if it is OK to still enjoy their music, books, or movies when this happens. By listening to this conversation, you will learn useful vocabulary to talk about controversy and personal values. This lesson will help you practice listening to natural English conversations and express your own thoughts about famous people who make bad choices. T', 'https://media.blubrry.com/culips/content.blubrry.com/culips/SS242_Regular.mp3', 1685, '2026-02-26 22:08:00'::timestamptz, 52000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Bonus episode #168 &#8211; Sick as a dog', 'Traveling abroad is usually a fun adventure, but what happens when you get sick in a different country? In this week&#039;s bonus episode, Andrew shares a story about his recent trip to Tokyo. He traveled there to see a concert and meet Culips listeners. However, a sudden illness almost ruined his plans. You will hear about how he tried to finish his trip and his long journey back to South Korea to find a doctor. Listening to this story will help you improve your English fluency. You will also learn useful, everyday words about traveling, being sick, and getting better. The brand-new Culips ap', 'https://media.blubrry.com/culips/content.blubrry.com/culips/B168_Regular.mp3', 1174, '2026-02-22 19:36:51'::timestamptz, 53000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Simplified Speech #241 &#8211; Keeping secrets', 'Can you keep a secret? In this episode, Andrew and Kassy talk about the difference between being an &quot;open book&quot; and a &quot;closed book.&quot; They discuss their own habits for keeping things private, share funny stories about childhood crushes, and debate whether it is harder to keep good news or bad news a secret. The brand-new Culips app is live! Study this episode with an interactive transcript and vocabulary glossary: Open this lesson in the Culips app. Fun Fact Andrew mentions being &quot;in a pickle.&quot; This is a funny way of saying you are in a difficult situation. While w', 'https://media.blubrry.com/culips/content.blubrry.com/culips/SS241_Regular.mp3', 1459, '2026-02-19 19:24:52'::timestamptz, 54000);
END $$;

