  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, '#58 - Back to School', 'Follow us on instagram! @easyenglish.scs', 'https://anchor.fm/s/4783b3e0/podcast/play/73799384/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fproduction%2F2023-6-24%2F340514291-44100-2-99bd34c3672cb.m4a', 225, '2023-07-24 19:38:51'::timestamptz, 5000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, '#57 - Working Holiday', 'Follow us on instagram! @easyenglish.scs', 'https://anchor.fm/s/4783b3e0/podcast/play/73555003/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fproduction%2F2023-6-18%2F339756640-44100-2-513c4b6a1cdb8.m4a', 255, '2023-07-18 15:19:13'::timestamptz, 6000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, '#56 - The Lost Treasure', 'Welcome to another exciting episode of our podcast! Today, we have a captivating story to share with you. Get ready to embark on a thrilling adventure as we dive into "The Lost Treasure." Sit back, relax, and let your imagination soar! Our story begins in a small coastal town called Portville. Our protagonist, Emily, stumbles upon an old and weathered map while exploring her grandfather''s attic. Little does she know that this map holds the key to an incredible treasure. Fueled by curiosity and a thirst for adventure, Emily enlists the help of her best friend, Jake. Together, they decipher the ', 'https://anchor.fm/s/4783b3e0/podcast/play/71223679/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fproduction%2F2023-4-29%2F332228106-44100-2-60ab8d138b368.m4a', 224, '2023-05-29 23:05:00'::timestamptz, 7000);
