  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, '#47 - Christmas Tale: The Night Right Before Christmas', 'TRANSCRIPTION: It was the night before Christmas when RIGHT through the house. Not a creature was LEFT stirring, not even a mouse The stockings were hung RIGHT by the chimney with care, In hopes that St. Nicholas soon would be there. The children were nestled RIGHT snug in their beds, While visions of sugarplums danced RIGHT in their heads. And mama in her kerchief, and I in my cap Had just settled RIGHT down for a long winter''s nap. When out on the LEFT lawn there rose such a clatter, I sprang RIGHT from my bed to see what was the matter. Away to the window I LEFT like a flash; Tore open the ', 'https://anchor.fm/s/4783b3e0/podcast/play/62311255/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fproduction%2F2022-11-16%2F303502154-44100-2-6a21524fed9b3.m4a', 149, '2022-12-16 19:01:27'::timestamptz, 16000);
