  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, '#43 - Halloween', 'Follow us on instagram for more!', 'https://anchor.fm/s/4783b3e0/podcast/play/59862667/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fproduction%2F2022-9-31%2F294198814-44100-2-348d6c5b55e61.m4a', 339, '2022-10-31 17:51:06'::timestamptz, 20000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, '#42 - The Tale of Peter Rabbit | Part 2', 'TRANSCRIPTION: Mr. McGregor tried to put his foot upon Peter, who jumped out of a window, upsetting three plants. The window was too small for Mr. McGregor, and he was tired of running after Peter. He went back to his work. PETER sat down to rest; he was out of breath and trembling with fright, and he had not the least idea which way to go. Also he was very damp with sitting in that can. After a time he began to wander about, going lippity— lippity—not very fast, and looking all around. HE found a door in a wall; but it was locked, and there was no room for a fat little rabbit to squeeze under', 'https://anchor.fm/s/4783b3e0/podcast/play/59567295/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fproduction%2F2022-9-25%2F293067139-44100-2-26f9cc60777bb.m4a', 187, '2022-10-25 19:13:45'::timestamptz, 21000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, '#41 - The Tale of Peter Rabbit | Part 1', 'Keep up for part two next week! This is 1/2 of the Tale of Peter Rabbit, practice your listening and enjoy! ONCE upon a time there were four little Rabbits, and their names were— Flopsy, Mopsy, Cotton-tail, and Peter. They lived with their Mother in a sand-bank, underneath the root of a very big fir tree "NOW, my dears," said old Mrs. Rabbit one morning, "you may go into the fields or down the lane, but don''t go into Mr. McGregor''s garden: your Father had an accident there; he was put in a pie by Mrs. McGregor." "NOW run along, and don''t get into mischief. I am going out." THEN old Mrs. Rabbit', 'https://anchor.fm/s/4783b3e0/podcast/play/58264761/https%3A%2F%2Fd3ctxlq1ktw2nl.cloudfront.net%2Fproduction%2F2022-8-28%2F288151529-44100-2-4d8dd9770ea79.m4a', 229, '2022-09-28 16:32:30'::timestamptz, 22000);
