BEGIN
  SELECT id INTO v_cat FROM categories WHERE name_ar = 'ثقافة وأدب' LIMIT 1;
  INSERT INTO hosts (name_ar, slug, photo_url, cover_url, title_ar, specialty_ar, bio_ar, country, category_id, is_verified, followers_count)
  VALUES ('HAHA Podcast', 'haha-podcast', 'https://is1-ssl.mzstatic.com/image/thumb/Podcasts211/v4/78/9d/12/789d1261-d224-abe5-b641-4ab05ecc0a0d/mza_7511211403408741048.jpg/600x600bb.jpg', 'https://is1-ssl.mzstatic.com/image/thumb/Podcasts211/v4/78/9d/12/789d1261-d224-abe5-b641-4ab05ecc0a0d/mza_7511211403408741048.jpg/600x600bb.jpg', 'مقدم', 'ثقافة وأدب', 'بودكاست حقيقي: HAHA Podcast', 'أونلاين', v_cat, true, 50000)
  RETURNING id INTO v_host_id;

  INSERT INTO podcasts (title, description, host_id, category_id, type, cover_url, audience_level, plays_count, rating_avg)
  VALUES ('HAHA Podcast', 'Welcome to Haha Podcast — hosted by the Ha Sisters: Evelyn, Emily, and Erica. We’re inviting you into our unfiltered group chat, where we spill the real tea on sisterhood, fights, love, careers, and everything in between. It’s chaotic, it’s honest, it’s us — the reality behind our lives, one laugh at a time. Available on ⁠⁠⁠Youtube⁠⁠⁠⁠⁠⁠⁠⁠⁠⁠ | Spotify⁠⁠⁠ ⁠⁠⁠| Apple ⁠⁠⁠⁠⁠⁠⁠⁠⁠⁠| Amazon⁠⁠ ⁠⁠⁠⁠⁠Socials ⁠⁠⁠https://www.tiktok.com/@haha.podcast⁠⁠⁠ Business Inquiries: ⁠⁠⁠hahapodcast@hasisters.com⁠⁠', v_host_id, v_cat, 'cultural', 'https://is1-ssl.mzstatic.com/image/thumb/Podcasts211/v4/78/9d/12/789d1261-d224-abe5-b641-4ab05ecc0a0d/mza_7511211403408741048.jpg/600x600bb.jpg', 'beginner', 100000, 4.7)
  RETURNING id INTO v_pod_id;

