  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'ARE GHOSTS REAL? | SAM &amp; COLBY', 'Today we interviewed @samandcolby who have amassed over 15 million subscribers investigating paranormal spots all over the world. Let us know who we should interview on season 2 of the haha podcast & thank you guys so much for tuning in! New episodes every Tuesday!! Available on ⁠⁠Youtube⁠ ⁠⁠⁠ ⁠⁠Spotify⁠⁠ ⁠⁠Apple⁠ ⁠⁠⁠ ⁠⁠Amazon⁠ ⁠⁠⁠ Socials ⁠⁠https://www.tiktok.com/@haha.podcast⁠⁠ Business Inquiries: ⁠⁠hahapodcast@hasisters.com⁠ Hosted by Simplecast, an AdsWizz company. See pcm.adswizz.com for information about our collection and use of personal data for advertising.', 'https://dts.podtrac.com/redirect.mp3/stitcher.simplecastaudio.com/2fa36b2b-a9fc-46b0-b2cb-c3a3964399dd/episodes/da9656e3-f965-453e-83dd-24af1c6748ae/audio/128/default.mp3?aid=rss_feed&amp;awCollectionId=2fa36b2b-a9fc-46b0-b2cb-c3a3964399dd&amp;awEpisodeId=da9656e3-f965-453e-83dd-24af1c6748ae&amp;feed=C8KWN7oI', 3294, '2025-10-21 23:30:00'::timestamptz, 54000);
