-- ---------- Economist Podcasts ----------
DO $$
DECLARE
  v_host_id uuid;
  v_pod_id uuid;
  v_cat uuid;
BEGIN
  SELECT id INTO v_cat FROM categories WHERE name_ar = 'ثقافة وأدب' LIMIT 1;
  INSERT INTO hosts (name_ar, slug, photo_url, cover_url, title_ar, specialty_ar, bio_ar, country, category_id, is_verified, followers_count)
  VALUES ('The Economist', 'economist-podcasts', 'https://is1-ssl.mzstatic.com/image/thumb/Podcasts211/v4/37/6e/6f/376e6f90-6694-48d4-32cf-cda596a2e95d/mza_17201510968398707530.png/600x600bb.jpg', 'https://is1-ssl.mzstatic.com/image/thumb/Podcasts211/v4/37/6e/6f/376e6f90-6694-48d4-32cf-cda596a2e95d/mza_17201510968398707530.png/600x600bb.jpg', 'مقدم', 'ثقافة وأدب', 'بودكاست حقيقي: Economist Podcasts', 'أونلاين', v_cat, true, 50000)
  RETURNING id INTO v_host_id;

  INSERT INTO podcasts (title, description, host_id, category_id, type, cover_url, audience_level, plays_count, rating_avg)
  VALUES ('Economist Podcasts', '&lt;p&gt;Sound reasoning. Every weekday, our global network of correspondents explain the world&apos;s most important stories.&lt;/p&gt;&lt;p&gt;&amp;nbsp;&lt;/p&gt;&lt;hr&gt;&lt;p style=&apos;color:grey; font-size:0.75em;&apos;&gt; Hosted on Acast. See &lt;a style=&apos;color:grey;&apos; target=&apos;_blank&apos; rel=&apos;noopener noreferrer&apos; href=&apos;https://acast.com/privacy&apos;&gt;acast.com/privacy&lt;/a&gt; for more information.&lt;/p&gt;', v_host_id, v_cat, 'cultural', 'https://is1-ssl.mzstatic.com/image/thumb/Podcasts211/v4/37/6e/6f/376e6f90-6694-48d4-32cf-cda596a2e95d/mza_17201510968398707530.png/600x600bb.jpg', 'beginner', 100000, 4.7)
  RETURNING id INTO v_pod_id;

  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Delayed but not denied: justice for the Rohingyas', '&lt;p&gt;After decades of persecution, and seven years after the case was first brought before the UN’s highest court, judges ruled that &lt;u&gt;&lt;a href=&quot;https://www.economist.com/asia/2026/11/19/myanmars-regime-is-convicted-of-genocide?utm_campaign=a.io&amp;utm_medium=audio.podcast.np&amp;utm_source=theintelligence&amp;utm_content=discovery.content.anonymous.tr_shownotes_na-na_article&amp;utm_term=sa.listeners&quot; rel=&quot;noopener noreferrer&quot; target=&quot;_blank&quot;&gt;Myanmar&lt;/a&gt;&lt;/u&gt; has committed genocide against the muslim minority. AI has facilitated new me', 'https://sphinx.acast.com/p/open/s/d556eb54-6160-4c85-95f4-47d9f5216c49/a/theeconomistallaudio/e/6b0029dc322405712ca22bff/media.mp3?tk=eyJ0ayI6ImRlZmF1bHQiLCJhZHMiOnRydWUsInNwb25zIjp0cnVlLCJzdGF0dXMiOiJwdWJsaWMifQ==&amp;sig=3NeVmxxZZSH8YjgdiyPEW9bMWTZfW4suGFkZk8xFDtg', 1638, '2026-11-20 11:07:08'::timestamptz, 5000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Racing ahead: Anthropic’s big IPO', '&lt;p&gt;The leading AI lab is expected to raise over $80bn, the largest sum ever raised at an initial public offering. Where does this leave its rival &lt;u&gt;&lt;a href=&quot;https://www.economist.com/business/2026/11/15/anthropics-giant-ipo-puts-the-heat-on-openai?utm_campaign=a.io&amp;utm_medium=audio.podcast.np&amp;utm_source=theintelligence&amp;utm_content=discovery.content.anonymous.tr_shownotes_na-na_article&amp;utm_term=sa.listeners&quot; rel=&quot;noopener noreferrer&quot; target=&quot;_blank&quot;&gt;OpenAI&lt;/a&gt;&lt;/u&gt;? The countries profiting from China and America’s battl', 'https://sphinx.acast.com/p/open/s/d556eb54-6160-4c85-95f4-47d9f5216c49/a/theeconomistallaudio/e/6afeca038f8ad2908f6bec2e/media.mp3?tk=eyJ0ayI6ImRlZmF1bHQiLCJhZHMiOnRydWUsInNwb25zIjp0cnVlLCJzdGF0dXMiOiJwdWJsaWMifQ==&amp;sig=Ebd42IwvnJ2r7-b2ED9WdQ-HgVIKaH9Ux_GjiYDSPXo', 1351, '2026-11-19 10:23:56'::timestamptz, 6000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Third wheeling: Xi, Putin and Trump meet in China', '&lt;p&gt;The APEC &lt;u&gt;&lt;a href=&quot;https://www.economist.com/international/2026/11/17/the-incredible-shrinking-legacy-of-donald-j-trump?utm_campaign=a.io&amp;utm_medium=audio.podcast.np&amp;utm_source=theintelligence&amp;utm_content=discovery.content.anonymous.tr_shownotes_na-na_article&amp;utm_term=sa.listeners&quot; rel=&quot;noopener noreferrer&quot; target=&quot;_blank&quot;&gt;summit&lt;/a&gt;&lt;/u&gt; began in Shenzhen today and the leaders of China, Russia and America are set to sit down tomorrow. Will it amount to much? Scientists are finally taking a closer look at what caus', 'https://sphinx.acast.com/p/open/s/d556eb54-6160-4c85-95f4-47d9f5216c49/a/theeconomistallaudio/e/6afd876f5ca4ff63ce3ea45e/media.mp3?tk=eyJ0ayI6ImRlZmF1bHQiLCJhZHMiOnRydWUsInNwb25zIjp0cnVlLCJzdGF0dXMiOiJwdWJsaWMifQ==&amp;sig=xQawY0EcyL_TLiKyOZT9MWlTIag-N5MHHXucNJdakOU', 1384, '2026-11-18 11:09:34'::timestamptz, 7000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Transchipment: Huang and the AI aftershocks', '&lt;p&gt;Jensen Huang probably is not coming back to lead Nvidia. We look to other signals of what &lt;u&gt;&lt;a href=&quot;https://www.economist.com/business/2026/11/12/jensen-huangs-recklessness-leaves-nvidia-with-no-good-options?utm_campaign=a.io&amp;utm_medium=audio.podcast.np&amp;utm_source=theintelligence&amp;utm_content=discovery.content.anonymous.tr_shownotes_na-na_article&amp;utm_term=sa.listeners&quot; rel=&quot;noopener noreferrer&quot; target=&quot;_blank&quot;&gt;lies ahead&lt;/a&gt;&lt;/u&gt; for the AI juggernaut, from earnings calls to export controls. Britain’s politicians ha', 'https://sphinx.acast.com/p/open/s/d556eb54-6160-4c85-95f4-47d9f5216c49/a/theeconomistallaudio/e/6afc30ca27224dadceb682ee/media.mp3?tk=eyJ0ayI6ImRlZmF1bHQiLCJhZHMiOnRydWUsInNwb25zIjp0cnVlLCJzdGF0dXMiOiJwdWJsaWMifQ==&amp;sig=yxQlJrzJSv-ATXFbQy84JrCMXNzfQ1UTcJ-5bv2upVw', 1339, '2026-11-17 10:47:38'::timestamptz, 8000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Cede of doubt: a NATO offer to Ukraine', '&lt;p&gt;Reasons abound for scepticism about America’s Donbas-for-membership gambit. The truth that it reveals is &lt;u&gt;&lt;a href=&quot;https://www.economist.com/europe/2026/11/09/donald-trump-is-in-a-hurry-for-peace-in-ukraine-vladimir-putin-is-not?utm_campaign=a.io&amp;utm_medium=audio.podcast.np&amp;utm_source=theintelligence&amp;utm_content=discovery.content.anonymous.tr_shownotes_na-na_article&amp;utm_term=sa.listeners&quot; rel=&quot;noopener noreferrer&quot; target=&quot;_blank&quot;&gt;the hurry&lt;/a&gt;&lt;/u&gt; the administration and its envoys are now in. A veto-loving preside', 'https://sphinx.acast.com/p/open/s/d556eb54-6160-4c85-95f4-47d9f5216c49/a/theeconomistallaudio/e/6afae373b2404cde2fe7d916/media.mp3?tk=eyJ0ayI6ImRlZmF1bHQiLCJhZHMiOnRydWUsInNwb25zIjp0cnVlLCJzdGF0dXMiOiJwdWJsaWMifQ==&amp;sig=oD87VhyoW7Bacj-mo8w8QQZAv1dlhPukpFLlemS4TDE', 1445, '2026-11-16 11:05:23'::timestamptz, 9000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Invidious position: finding Jensen Huang’s successor', '&lt;p&gt;Nvidia’s micromanaging supremo is out and a caretaker boss is in. We ask how the AI-chip giant might survive &lt;u&gt;&lt;a href=&quot;https://www.economist.com/business/2026/11/12/jensen-huang-is-out-his-successor-has-the-toughest-job-in-tech?utm_campaign=a.io&amp;utm_medium=audio.podcast.np&amp;utm_source=theintelligence&amp;utm_content=discovery.content.anonymous.tr_shownotes_na-na_article&amp;utm_term=sa.listeners&quot; rel=&quot;noopener noreferrer&quot; target=&quot;_blank&quot;&gt;the transition&lt;/a&gt;&lt;/u&gt;. We look at the &lt;u&gt;&lt;a href=&quot;https://www.economist', 'https://sphinx.acast.com/p/open/s/d556eb54-6160-4c85-95f4-47d9f5216c49/a/theeconomistallaudio/e/6af6e7991f9433e997b64a63/media.mp3?tk=eyJ0ayI6ImRlZmF1bHQiLCJhZHMiOnRydWUsInNwb25zIjp0cnVlLCJzdGF0dXMiOiJwdWJsaWMifQ==&amp;sig=Z5s6lcdh_oUAKWAt7QXQEp3hprobFDWLX4uyV1Mjdk0', 1338, '2026-11-13 11:09:22'::timestamptz, 10000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Abate and switch: how China’s emissions fell', '&lt;p&gt;The world’s largest carbon emitter is finally turning a corner and the rest of the world ought to pay attention. El Salvador’s president Nayib Bukele is taking his &lt;u&gt;&lt;a href=&quot;https://www.economist.com/the-americas/2026/11/05/el-salvadors-president-thinks-he-can-eliminate-haitis-gangs?utm_campaign=a.io&amp;utm_medium=audio.podcast.np&amp;utm_source=theintelligence&amp;utm_content=discovery.content.anonymous.tr_shownotes_na-na_article&amp;utm_term=sa.listeners&quot; rel=&quot;noopener noreferrer&quot; target=&quot;_blank&quot;&gt;gangbusting&lt;/a&gt;&lt;/u&gt; tactics be', 'https://sphinx.acast.com/p/open/s/d556eb54-6160-4c85-95f4-47d9f5216c49/a/theeconomistallaudio/e/6af5967413c30781a320173d/media.mp3?tk=eyJ0ayI6ImRlZmF1bHQiLCJhZHMiOnRydWUsInNwb25zIjp0cnVlLCJzdGF0dXMiOiJwdWJsaWMifQ==&amp;sig=iei-oy7wkDfjMbalx_I3N2uJr0FooeOw7-0fB3XvN7c', 1253, '2026-11-12 10:35:32'::timestamptz, 11000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Let’s get this party restarted: Republicans reel from the midterms', '&lt;p&gt;As Donald Trump’s party &lt;u&gt;&lt;a href=&quot;https://www.economist.com/united-states/2026/11/08/the-fight-over-republicans-future-has-begun?utm_campaign=a.io&amp;utm_medium=audio.podcast.np&amp;utm_source=theintelligence&amp;utm_content=discovery.content.anonymous.tr_shownotes_na-na_article&amp;utm_term=sa.listeners&quot; rel=&quot;noopener noreferrer&quot; target=&quot;_blank&quot;&gt;absorbs&lt;/a&gt;&lt;/u&gt; a sobering defeat at the ballot box, politicians are in reflective mood. Is Trumpism over? &lt;u&gt;&lt;a href=&quot;https://www.economist.com/finance-and-economics/2026', 'https://sphinx.acast.com/p/open/s/d556eb54-6160-4c85-95f4-47d9f5216c49/a/theeconomistallaudio/e/6af4462e36d94b58ef827a8a/media.mp3?tk=eyJ0ayI6ImRlZmF1bHQiLCJhZHMiOnRydWUsInNwb25zIjp0cnVlLCJzdGF0dXMiOiJwdWJsaWMifQ==&amp;sig=yMTo-DMwSRUVM7FAhiqPoWuRprkML-TaG0xN0vXPr74', 1378, '2026-11-11 10:43:06'::timestamptz, 12000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'When chips are down: Nvidia CEO’s risky relationship', '&lt;p&gt;The &lt;u&gt;&lt;a href=&quot;https://www.economist.com/business/2026/11/09/can-nvidias-boss-survive-a-chinese-spy-controversy?utm_campaign=a.io&amp;utm_medium=audio.podcast.np&amp;utm_source=theintelligence&amp;utm_content=discovery.content.anonymous.tr_shownotes_na-na_article&amp;utm_term=sa.listeners&quot; rel=&quot;noopener noreferrer&quot; target=&quot;_blank&quot;&gt;liaison&lt;/a&gt;&lt;/u&gt; has become more than just family business as Jensen Huang’s lover is allegedly a Chinese spy. The FBI and Nvidia’s board are investigating, but what will become of the man at the centre o', 'https://sphinx.acast.com/p/open/s/d556eb54-6160-4c85-95f4-47d9f5216c49/a/theeconomistallaudio/e/6af2f4ae43e2f445c2499225/media.mp3?tk=eyJ0ayI6ImRlZmF1bHQiLCJhZHMiOnRydWUsInNwb25zIjp0cnVlLCJzdGF0dXMiOiJwdWJsaWMifQ==&amp;sig=aCwgqQVYQXrPf1PcEa7tMEYraYSBbC4o75DV-1lfNRM', 1340, '2026-11-10 10:40:46'::timestamptz, 13000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'All eyes on Eisenkot: Israel’s could-be prime minister', '&lt;p&gt;The president has tasked the former general – and Binyamin Netanyahu’s strongest rival – with building a &lt;u&gt;&lt;a href=&quot;https://www.economist.com/middle-east-and-africa/2026/11/08/gadi-eisenkot-has-a-chance-to-form-a-new-government-in-israel?utm_campaign=a.io&amp;utm_medium=audio.podcast.np&amp;utm_source=theintelligence&amp;utm_content=discovery.content.anonymous.tr_shownotes_na-na_article&amp;utm_term=sa.listeners&quot; rel=&quot;noopener noreferrer&quot; target=&quot;_blank&quot;&gt;new government&lt;/a&gt;&lt;/u&gt;. With just six weeks and barely a third of the Knesset', 'https://sphinx.acast.com/p/open/s/d556eb54-6160-4c85-95f4-47d9f5216c49/a/theeconomistallaudio/e/6af19d18e7c6d309d1116743/media.mp3?tk=eyJ0ayI6ImRlZmF1bHQiLCJhZHMiOnRydWUsInNwb25zIjp0cnVlLCJzdGF0dXMiOiJwdWJsaWMifQ==&amp;sig=AJ7QEFBeCTjZRhb2P1Ds93cf0XpWjfC9Taby5V2XJNE', 1426, '2026-11-09 10:14:48'::timestamptz, 14000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, '“Britain is back”: an interview with Andy Burnham', '&lt;p&gt;Ahead of the G20 summit in Manchester, Britain’s prime minister sets out his &lt;u&gt;&lt;a href=&quot;https://www.economist.com/britain/2026/11/05/andy-burnham-promises-three-foreign-policy-overhauls?utm_campaign=a.io&amp;utm_medium=audio.podcast.np&amp;utm_source=theintelligence&amp;utm_content=discovery.content.anonymous.tr_shownotes_na-na_article&amp;utm_term=sa.listeners&quot; rel=&quot;noopener noreferrer&quot; target=&quot;_blank&quot;&gt;foreign-policy plans&lt;/a&gt;&lt;/u&gt;. From reviewing EU links, to brokering the relationship between America and China, he is making big ', 'https://sphinx.acast.com/p/open/s/d556eb54-6160-4c85-95f4-47d9f5216c49/a/theeconomistallaudio/e/6aedac35dabcb4d1f2d2092c/media.mp3?tk=eyJ0ayI6ImRlZmF1bHQiLCJhZHMiOnRydWUsInNwb25zIjp0cnVlLCJzdGF0dXMiOiJwdWJsaWMifQ==&amp;sig=aTrr4TFzJTriNe54qgAf3CcTMb-_qhrKbYX2rwF8NOA', 1572, '2026-11-06 10:30:13'::timestamptz, 15000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Forever young: the business of longevity drugs', '&lt;p&gt;The success of GLP-1s has prompted biotechs to approach the challenge differently. After years of false starts and disappointing results, &lt;u&gt;&lt;a href=&quot;https://www.economist.com/business/2026/11/02/the-quest-for-immortality-has-become-serious-business?utm_campaign=a.io&amp;utm_medium=audio.podcast.np&amp;utm_source=theintelligence&amp;utm_content=discovery.content.anonymous.tr_shownotes_na-na_article&amp;utm_term=sa.listeners&quot; rel=&quot;noopener noreferrer&quot; target=&quot;_blank&quot;&gt;longevity drugs&lt;/a&gt;&lt;/u&gt; could be on the horizon. Do immigrants fro', 'https://sphinx.acast.com/p/open/s/d556eb54-6160-4c85-95f4-47d9f5216c49/a/theeconomistallaudio/e/6aec4fff51ac9ecbba3b7818/media.mp3?tk=eyJ0ayI6ImRlZmF1bHQiLCJhZHMiOnRydWUsInNwb25zIjp0cnVlLCJzdGF0dXMiOiJwdWJsaWMifQ==&amp;sig=XPCAFGU-HxUsIfXgxur2116IZHJjeeY3U5wMeaCskH4', 1403, '2026-11-05 09:55:01'::timestamptz, 16000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Not in Kansas any more: Republicans get a thrashing', '&lt;p&gt;In the end, the result was clear and uncontested: Democrats had an &lt;u&gt;&lt;a href=&quot;https://www.economist.com/interactive/2026/us-midterms/results/summary?utm_campaign=a.io&amp;utm_medium=audio.podcast.np&amp;utm_source=theintelligence&amp;utm_content=discovery.content.anonymous.tr_shownotes_na-na_article&amp;utm_term=sa.listeners&quot; rel=&quot;noopener noreferrer&quot; target=&quot;_blank&quot;&gt;astonishingly good night&lt;/a&gt;&lt;/u&gt;. Our editors and correspondents across America report on the proceedings, and we ask &lt;u&gt;&lt;a href=&quot;https://www.economist.', 'https://sphinx.acast.com/p/open/s/d556eb54-6160-4c85-95f4-47d9f5216c49/a/theeconomistallaudio/e/6aeb148e2d18c73dd5116294/media.mp3?tk=eyJ0ayI6ImRlZmF1bHQiLCJhZHMiOnRydWUsInNwb25zIjp0cnVlLCJzdGF0dXMiOiJwdWJsaWMifQ==&amp;sig=jZ1BW8Koxr2nZuOW71yRGZ0wnjN7_lQ7uHLaBu_itB8', 1314, '2026-11-04 11:18:38'::timestamptz, 17000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Fertile ambitions: scientists’ plans to slow the biological clock', '&lt;p&gt;Two European startups are tackling the chromosomal abnormalities that make it difficult for older women to get pregnant. Their &lt;u&gt;&lt;a href=&quot;https://www.economist.com/science-and-technology/2026/10/26/treatments-for-age-related-infertility-are-being-developed-at-last?utm_campaign=a.io&amp;utm_medium=audio.podcast.np&amp;utm_source=theintelligence&amp;utm_content=discovery.content.anonymous.tr_shownotes_na-na_article&amp;utm_term=sa.listeners&quot; rel=&quot;noopener noreferrer&quot; target=&quot;_blank&quot;&gt;innovations&lt;/a&gt;&lt;/u&gt; might also prevent younger wom', 'https://sphinx.acast.com/p/open/s/d556eb54-6160-4c85-95f4-47d9f5216c49/a/theeconomistallaudio/e/6ae9b5979cb48f65eaf31c3f/media.mp3?tk=eyJ0ayI6ImRlZmF1bHQiLCJhZHMiOnRydWUsInNwb25zIjp0cnVlLCJzdGF0dXMiOiJwdWJsaWMifQ==&amp;sig=mlshDWUpNFQzKtx-n5ZWNxwxqxnBDGpcRauj5eiw3-A', 1297, '2026-11-03 10:21:11'::timestamptz, 18000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Off to the races: our American-midterms preview', '&lt;p&gt;Ahead of tomorrow’s legislative elections we consider &lt;u&gt;&lt;a href=&quot;https://www.economist.com/interactive/2026/us-midterms/prediction-model/house?utm_campaign=a.io&amp;utm_medium=audio.podcast.np&amp;utm_source=theintelligence&amp;utm_content=discovery.content.anonymous.tr_shownotes_na-na_article&amp;utm_term=sa.listeners&quot; rel=&quot;noopener noreferrer&quot; target=&quot;_blank&quot;&gt;the chances&lt;/a&gt;&lt;/u&gt; of a “blue wave”, the most &lt;u&gt;&lt;a href=&quot;https://www.economist.com/leaders/2026/10/29/the-americans-changing-politics-for-the-better?utm_cam', 'https://sphinx.acast.com/p/open/s/d556eb54-6160-4c85-95f4-47d9f5216c49/a/theeconomistallaudio/e/6ae852a798a5c8b2e347e723/media.mp3?tk=eyJ0ayI6ImRlZmF1bHQiLCJhZHMiOnRydWUsInNwb25zIjp0cnVlLCJzdGF0dXMiOiJwdWJsaWMifQ==&amp;sig=-d9jM-4BwixA_QqfQmLxWLQLsqGNC7dywnrDdqc8jTs', 1462, '2026-11-02 10:45:10'::timestamptz, 19000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Silver-year strongman: 25 years of Narendra Modi', '&lt;p&gt;We examine the record of the man at the helm of India’s government. As protests pose a fresh threat, where will he take the country next? From New Hampshire to Virginia, our American-midterms series takes you to the races you might be missing. And the life of Winston Churchill’s last personal secretary. &lt;/p&gt;&lt;br&gt;&lt;p&gt;Guests and host:&lt;/p&gt;&lt;ul&gt;&lt;li&gt;Tom Sasse, South Asia bureau chief&lt;/li&gt;&lt;li&gt;Daniella Raz, US correspondent&lt;/li&gt;&lt;li&gt;Ann Wroe, obituaries editor&lt;/li&gt;&lt;li&gt;Ọrẹ Ogunbiyi, co-host of “The Intelligence”&lt;/li&gt;&lt', 'https://sphinx.acast.com/p/open/s/d556eb54-6160-4c85-95f4-47d9f5216c49/a/theeconomistallaudio/e/6ae45f7ce96b052ecaf43184/media.mp3?tk=eyJ0ayI6ImRlZmF1bHQiLCJhZHMiOnRydWUsInNwb25zIjp0cnVlLCJzdGF0dXMiOiJwdWJsaWMifQ==&amp;sig=vlaLO7GL-SE9QDTYs1sXjZtyulz82DIgVIx35zfKKbs', 1670, '2026-10-30 09:46:52'::timestamptz, 20000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Effective non-altruism: Elon Musk’s foundation', '&lt;p&gt;The world’s richest person does not say much nice about philanthropy, and his foundation does not say much about itself. Our correspondent &lt;u&gt;&lt;a href=&quot;https://www.economist.com/business/2026/10/13/elon-musks-foundation-is-opaque-miserly-and-self-serving?utm_campaign=a.io&amp;utm_medium=audio.podcast.np&amp;utm_source=theintelligence&amp;utm_content=discovery.content.anonymous.tr_shownotes_na-na_article&amp;utm_term=sa.listeners&quot; rel=&quot;noopener noreferrer&quot; target=&quot;_blank&quot;&gt;digs deeper&lt;/a&gt;&lt;/u&gt;. The next stop for our &lt;u&gt;&lt;a href', 'https://sphinx.acast.com/p/open/s/d556eb54-6160-4c85-95f4-47d9f5216c49/a/theeconomistallaudio/e/6ae30277305baddee189d087/media.mp3?tk=eyJ0ayI6ImRlZmF1bHQiLCJhZHMiOnRydWUsInNwb25zIjp0cnVlLCJzdGF0dXMiOiJwdWJsaWMifQ==&amp;sig=uZJphBnplDuhrd-cgw1l_MtpR7kClKQi5fDOrKziatw', 1382, '2026-10-29 08:36:11'::timestamptz, 21000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Bye bye Bibi? Israel’s election results', '&lt;p&gt;Binyamin Netanyahu has underperformed but so has his main opponent, Gadi Eisenkot. Who will form a government? We decipher what the &lt;u&gt;&lt;a href=&quot;https://www.economist.com/middle-east-and-africa/2026/10/28/israels-voters-deny-binyamin-netanyahu-a-majority?utm_campaign=a.io&amp;utm_medium=audio.podcast.np&amp;utm_source=theintelligence&amp;utm_content=discovery.content.anonymous.tr_shownotes_na-na_article&amp;utm_term=sa.listeners&quot; rel=&quot;noopener noreferrer&quot; target=&quot;_blank&quot;&gt;messy results&lt;/a&gt;&lt;/u&gt; mean for Israel. Our American-midterms s', 'https://sphinx.acast.com/p/open/s/d556eb54-6160-4c85-95f4-47d9f5216c49/a/theeconomistallaudio/e/6ae1b4ac092a0dff193c7811/media.mp3?tk=eyJ0ayI6ImRlZmF1bHQiLCJhZHMiOnRydWUsInNwb25zIjp0cnVlLCJzdGF0dXMiOiJwdWJsaWMifQ==&amp;sig=3ADtLb_G4zf0EDKTjL_SNABhIdRDX0q20QOUb94igDM', 1279, '2026-10-28 09:57:01'::timestamptz, 22000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Act of Claude: Anthropic’s IPO bid', '&lt;p&gt;It would be the first public listing from a frontier-AI firm—and perhaps the largest IPO of all time. We comb through &lt;u&gt;&lt;a href=&quot;https://www.economist.com/business/2026/10/26/dont-expect-supersize-profits-from-anthropic-any-time-soon?utm_campaign=a.io&amp;utm_medium=audio.podcast.np&amp;utm_source=theintelligence&amp;utm_content=discovery.content.anonymous.tr_shownotes_na-na_article&amp;utm_term=sa.listeners&quot; rel=&quot;noopener noreferrer&quot; target=&quot;_blank&quot;&gt;the filing&lt;/a&gt;&lt;/u&gt; to understand how the company is thinking about itself and its', 'https://sphinx.acast.com/p/open/s/d556eb54-6160-4c85-95f4-47d9f5216c49/a/theeconomistallaudio/e/6ae076c0feb8d1e39c686d1a/media.mp3?tk=eyJ0ayI6ImRlZmF1bHQiLCJhZHMiOnRydWUsInNwb25zIjp0cnVlLCJzdGF0dXMiOiJwdWJsaWMifQ==&amp;sig=YvMG_vcfQccT9zH153fCE0XYDGLn8PpfRZ79_5Eqbp4', 1414, '2026-10-27 10:02:40'::timestamptz, 23000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'From this day, fourth: Lula’s surprise win', '&lt;p&gt;Brazil’s president, Luiz Inácio Lula da Silva, staged a &lt;u&gt;&lt;a href=&quot;https://www.economist.com/the-americas/2026/10/26/lula-the-great-survivor-makes-history?utm_campaign=a.io&amp;utm_medium=audio.podcast.np&amp;utm_source=theintelligence&amp;utm_content=discovery.content.anonymous.tr_shownotes_na-na_article&amp;utm_term=sa.listeners&quot; rel=&quot;noopener noreferrer&quot; target=&quot;_blank&quot;&gt;historic comeback&lt;/a&gt;&lt;/u&gt; to win a fourth term. We ask how he did it, and what he must do next. Each day this week our correspondents in America are focusing on', 'https://sphinx.acast.com/p/open/s/d556eb54-6160-4c85-95f4-47d9f5216c49/a/theeconomistallaudio/e/6adf22dfdd5d6293db62cd9d/media.mp3?tk=eyJ0ayI6ImRlZmF1bHQiLCJhZHMiOnRydWUsInNwb25zIjp0cnVlLCJzdGF0dXMiOiJwdWJsaWMifQ==&amp;sig=R60o12Pdb-IwJKKwhzdWxHzRghaWypdyHnRdW0RcgiM', 1642, '2026-10-26 10:23:37'::timestamptz, 24000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Songs of disenchantment: the sorrow of Nigeria', '&lt;p&gt;&lt;u&gt;&lt;a href=&quot;https://www.economist.com/middle-east-and-africa/2026/10/01/nigerians-dislike-their-president-but-may-re-elect-him-anyway?utm_campaign=a.io&amp;utm_medium=audio.podcast.np&amp;utm_source=theintelligence&amp;utm_content=discovery.content.anonymous.tr_shownotes_na-na_article&amp;utm_term=sa.listeners&quot; rel=&quot;noopener noreferrer&quot; target=&quot;_blank&quot;&gt;Nigeria&lt;/a&gt;&lt;/u&gt; is suffering a worsening security crisis, compounded by a lean harvest, global aid cuts and rising energy prices. So why is President Bola Tinubu likely to win Januar', 'https://sphinx.acast.com/p/open/s/d556eb54-6160-4c85-95f4-47d9f5216c49/a/theeconomistallaudio/e/6adb2359a25058b22ad882a3/media.mp3?tk=eyJ0ayI6ImRlZmF1bHQiLCJhZHMiOnRydWUsInNwb25zIjp0cnVlLCJzdGF0dXMiOiJwdWJsaWMifQ==&amp;sig=UZzNp9EkLIJY0BpEsAMvzpxlwFcehWopywkJh54cxy0', 1480, '2026-10-23 09:09:45'::timestamptz, 25000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Dunes and gloom: MBS’s annus horribilis', '&lt;p&gt;This week, &lt;u&gt;&lt;a href=&quot;https://www.economist.com/middle-east-and-africa/2026/10/19/everything-is-going-wrong-for-muhammad-bin-salman?utm_campaign=a.io&amp;utm_medium=audio.podcast.np&amp;utm_source=theintelligence&amp;utm_content=discovery.content.anonymous.tr_shownotes_na-na_article&amp;utm_term=sa.listeners&quot; rel=&quot;noopener noreferrer&quot; target=&quot;_blank&quot;&gt;Muhammad bin Salman&lt;/a&gt;&lt;/u&gt;, crown prince of Saudi Arabia, was forced to postpone his annual investment summit. His other big bets on the kingdom’s future are also floundering. &lt;u&', 'https://sphinx.acast.com/p/open/s/d556eb54-6160-4c85-95f4-47d9f5216c49/a/theeconomistallaudio/e/6ad9d01c3ad7f68551457388/media.mp3?tk=eyJ0ayI6ImRlZmF1bHQiLCJhZHMiOnRydWUsInNwb25zIjp0cnVlLCJzdGF0dXMiOiJwdWJsaWMifQ==&amp;sig=fvZnUS5kc_2bEmCrGJn-133ypwdny8nyfYdLhMp3QVw', 1461, '2026-10-22 09:11:24'::timestamptz, 26000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Cash test: can Europe support Ukraine alone?', '&lt;p&gt;Donald Trump’s administration is turning against &lt;u&gt;&lt;a href=&quot;https://www.economist.com/europe/2026/10/18/as-america-turns-against-ukraine-europe-stands-alone?utm_campaign=a.io&amp;utm_medium=audio.podcast.np&amp;utm_source=theintelligence&amp;utm_content=discovery.content.anonymous.tr_shownotes_na-na_article&amp;utm_term=sa.listeners&quot; rel=&quot;noopener noreferrer&quot; target=&quot;_blank&quot;&gt;Ukraine&lt;/a&gt;&lt;/u&gt;. But as European powers confront trouble at home, they are struggling to replace American support. Are US &lt;u&gt;&lt;a href=&quot;https://ww', 'https://sphinx.acast.com/p/open/s/d556eb54-6160-4c85-95f4-47d9f5216c49/a/theeconomistallaudio/e/6ad870aa3ad7f68551e3a1a2/media.mp3?tk=eyJ0ayI6ImRlZmF1bHQiLCJhZHMiOnRydWUsInNwb25zIjp0cnVlLCJzdGF0dXMiOiJwdWJsaWMifQ==&amp;sig=9Cw2B5pm2cYhHkkkvyZiQrXaTi2kVsc76DZxxXJgZFg', 1430, '2026-10-21 09:03:15'::timestamptz, 27000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Disorder of magnitude: France’s riots', '&lt;p&gt;What started as student protests ballooned into national lawlessness. The disorder plays into the hands of France’s political extremes; &lt;u&gt;&lt;a href=&quot;https://www.economist.com/europe/2026/10/18/expect-violent-protests-to-erupt-in-france-again?utm_campaign=a.io&amp;utm_medium=audio.podcast.np&amp;utm_source=theintelligence&amp;utm_content=discovery.content.anonymous.tr_shownotes_na-na_article&amp;utm_term=sa.listeners&quot; rel=&quot;noopener noreferrer&quot; target=&quot;_blank&quot;&gt;expect more of it&lt;/a&gt;&lt;/u&gt;. In Zimbabwe white farmers are &lt;u&gt;&lt;a hre', 'https://sphinx.acast.com/p/open/s/d556eb54-6160-4c85-95f4-47d9f5216c49/a/theeconomistallaudio/e/6ad73d9d6a9e2a41c3da84e6/media.mp3?tk=eyJ0ayI6ImRlZmF1bHQiLCJhZHMiOnRydWUsInNwb25zIjp0cnVlLCJzdGF0dXMiOiJwdWJsaWMifQ==&amp;sig=J-cq8ZlvxUfXWUJ16mE6T1XjSkcG5ttmbfdZrUS7_0s', 1287, '2026-10-20 10:08:29'::timestamptz, 28000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Independence eh? Canada’s referendum', '&lt;p&gt;The province of Alberta will vote on secession today. It is unlikely to go ahead, but the separatist vibe is just one of Prime Minister Mark Carney’s &lt;u&gt;&lt;a href=&quot;https://www.economist.com/briefing/2026/10/15/donald-trump-may-save-canada?utm_campaign=a.io&amp;utm_medium=audio.podcast.np&amp;utm_source=theintelligence&amp;utm_content=discovery.content.anonymous.tr_shownotes_na-na_article&amp;utm_term=sa.listeners&quot; rel=&quot;noopener noreferrer&quot; target=&quot;_blank&quot;&gt;many headaches&lt;/a&gt;&lt;/u&gt;. Our correspondent examines China’s efforts toward brain', 'https://sphinx.acast.com/p/open/s/d556eb54-6160-4c85-95f4-47d9f5216c49/a/theeconomistallaudio/e/6ad5db120c6b30397bf5bec0/media.mp3?tk=eyJ0ayI6ImRlZmF1bHQiLCJhZHMiOnRydWUsInNwb25zIjp0cnVlLCJzdGF0dXMiOiJwdWJsaWMifQ==&amp;sig=tVWAtGO7wNMA_UohaUiqKdwFZx3MbsSbTnjIH2aBv3k', 1303, '2026-10-19 08:55:46'::timestamptz, 29000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Schrödinger’s chat: can AI and scientists co-exist?', '&lt;p&gt;In recent weeks, AI has solved hundreds of previously unanswered maths problems. Our correspondents ask if machines can do the same in other areas of &lt;u&gt;&lt;a href=&quot;https://www.economist.com/leaders/2026/10/15/what-if-the-machines-take-over-science?utm_campaign=a.io&amp;utm_medium=audio.podcast.np&amp;utm_source=theintelligence&amp;utm_content=discovery.content.anonymous.tr_shownotes_na-na_article&amp;utm_term=sa.listeners&quot; rel=&quot;noopener noreferrer&quot; target=&quot;_blank&quot;&gt;science&lt;/a&gt;&lt;/u&gt; and what role human researchers may play. Why crisps a', 'https://sphinx.acast.com/p/open/s/d556eb54-6160-4c85-95f4-47d9f5216c49/a/theeconomistallaudio/e/6ad1fd1765f99a36ebb7243f/media.mp3?tk=eyJ0ayI6ImRlZmF1bHQiLCJhZHMiOnRydWUsInNwb25zIjp0cnVlLCJzdGF0dXMiOiJwdWJsaWMifQ==&amp;sig=uKoQr1zjoTFUIosoEQd0W_txp8hrlUA2k60usFjTy18', 1673, '2026-10-16 10:31:51'::timestamptz, 30000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'An interview with Alice Weidel', '&lt;p&gt;Under Alice Weidel’s leadership the Alternative for Germany (AfD), a right-wing populist party, has been riding high. A series of successes in state elections have brought it closer than ever to power at national level. Ms Weidel is perhaps best known for her calls for “remigration” and criticism of Germany’s support for Ukraine. She spoke to &lt;em&gt;The Economist&lt;/em&gt;’s editor-in-chief, Zanny Minton Beddoes, for &lt;u&gt;&lt;a href=&quot;https://www.economist.com/insider&quot; rel=&quot;noopener noreferrer&quot; target=&quot;_blank&quot;&gt;The Insider&lt;/a&gt;&lt;/u&gt;, ou', 'https://sphinx.acast.com/p/open/s/d556eb54-6160-4c85-95f4-47d9f5216c49/a/theeconomistallaudio/e/6ad0f9cc3b418431370456ec/media.mp3?tk=eyJ0ayI6ImRlZmF1bHQiLCJhZHMiOnRydWUsInNwb25zIjp0cnVlLCJzdGF0dXMiOiJwdWJsaWMifQ==&amp;sig=xAGlTnlzQDVefJRYzKFVER0LXjW3twOCF7tI-j-Ctdo', 3660, '2026-10-15 17:17:47'::timestamptz, 31000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Who wants to be a millennial? Generation comeback', '&lt;p&gt;Their struggles to get jobs or buy homes once propelled political movements. Now many &lt;u&gt;&lt;a href=&quot;https://www.economist.com/finance-and-economics/2026/10/11/dont-feel-sorry-for-millennials-they-are-living-it-up-now?utm_campaign=a.io&amp;utm_medium=audio.podcast.np&amp;utm_source=theintelligence&amp;utm_content=discovery.content.anonymous.tr_shownotes_na-na_article&amp;utm_term=sa.listeners&quot; rel=&quot;noopener noreferrer&quot; target=&quot;_blank&quot;&gt;millennials&lt;/a&gt;&lt;/u&gt; are out-earning their parents and in positions of power. Our correspondent explai', 'https://sphinx.acast.com/p/open/s/d556eb54-6160-4c85-95f4-47d9f5216c49/a/theeconomistallaudio/e/6ad0aad75f788808a7715263/media.mp3?tk=eyJ0ayI6ImRlZmF1bHQiLCJhZHMiOnRydWUsInNwb25zIjp0cnVlLCJzdGF0dXMiOiJwdWJsaWMifQ==&amp;sig=bXVCaiOt8xiYUJIzxeyCy0mC26snJYRw7I9i-0DusRg', 1338, '2026-10-15 10:28:38'::timestamptz, 32000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Kicking Kyiv: Trump’s doubtful deals', '&lt;p&gt;Donald Trump claims to have &lt;u&gt;&lt;a href=&quot;https://www.economist.com/europe/2026/10/12/donald-trump-is-again-threatening-to-cut-off-arms-to-ukraine?utm_campaign=a.io&amp;utm_medium=audio.podcast.np&amp;utm_source=theintelligence&amp;utm_content=discovery.content.anonymous.tr_shownotes_na-na_article&amp;utm_term=sa.listeners&quot; rel=&quot;noopener noreferrer&quot; target=&quot;_blank&quot;&gt;brokered a deal&lt;/a&gt;&lt;/u&gt; to import Russian diesel and an energy ceasefire between Russia and Ukraine. As attacks on Kyiv continue, our deputy editor says Trump is risking U', 'https://sphinx.acast.com/p/open/s/d556eb54-6160-4c85-95f4-47d9f5216c49/a/theeconomistallaudio/e/6acf5699937a3c900fd4f56f/media.mp3?tk=eyJ0ayI6ImRlZmF1bHQiLCJhZHMiOnRydWUsInNwb25zIjp0cnVlLCJzdGF0dXMiOiJwdWJsaWMifQ==&amp;sig=mLpT7V7XEPrMp9VDZ79IaMZJYQ8PSmwITy6c9gH0VYo', 1583, '2026-10-14 10:16:56'::timestamptz, 33000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Unrest in peace: misery in Gaza', '&lt;p&gt;A year ago Donald Trump created the Board of Peace to rebuild &lt;u&gt;&lt;a href=&quot;https://www.economist.com/middle-east-and-africa/2026/10/01/jared-kushner-has-a-245bn-recovery-plan-for-gaza?utm_campaign=a.io&amp;utm_medium=audio.podcast.np&amp;utm_source=theintelligence&amp;utm_content=discovery.content.anonymous.tr_shownotes_na-na_article&amp;utm_term=sa.listeners&quot; rel=&quot;noopener noreferrer&quot; target=&quot;_blank&quot;&gt;Gaza&lt;/a&gt;&lt;/u&gt;. Yet for many Palestinians, life is even harder, as the ceasefire is repeatedly violated, crime is rising and poverty ri', 'https://sphinx.acast.com/p/open/s/d556eb54-6160-4c85-95f4-47d9f5216c49/a/theeconomistallaudio/e/6ace029d37f0bd18cc1c7df0/media.mp3?tk=eyJ0ayI6ImRlZmF1bHQiLCJhZHMiOnRydWUsInNwb25zIjp0cnVlLCJzdGF0dXMiOiJwdWJsaWMifQ==&amp;sig=wTHANCMrOFvtucsBsP73zMU-JkSDtZPqPmGZOgVAfgc', 1495, '2026-10-13 10:06:21'::timestamptz, 34000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Saudi under siege: Houthis attack airport', '&lt;p&gt;This weekend, Yemeni rebels &lt;u&gt;&lt;a href=&quot;https://www.economist.com/middle-east-and-africa/2026/10/11/saudi-arabia-is-increasingly-under-siege?utm_campaign=a.io&amp;utm_medium=audio.podcast.np&amp;utm_source=theintelligence&amp;utm_content=discovery.content.anonymous.tr_shownotes_na-na_article&amp;utm_term=sa.listeners&quot; rel=&quot;noopener noreferrer&quot; target=&quot;_blank&quot;&gt;struck Saudi Arabia&lt;/a&gt;&lt;/u&gt;’s international airport in the deadliest attack on a Gulf Arab country since the Iran war began in February. Our correspondent reports from Riyadh.', 'https://sphinx.acast.com/p/open/s/d556eb54-6160-4c85-95f4-47d9f5216c49/a/theeconomistallaudio/e/6accaf58eea51f2aa376ee05/media.mp3?tk=eyJ0ayI6ImRlZmF1bHQiLCJhZHMiOnRydWUsInNwb25zIjp0cnVlLCJzdGF0dXMiOiJwdWJsaWMifQ==&amp;sig=bTbDchcY3PoaoHto0YZM2PVkqKW7KfGvHyfMROp9ZTc', 1358, '2026-10-12 10:03:26'::timestamptz, 35000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Saving your bacon: healthy-eating policy evolves', '&lt;p&gt;Decades of messaging have not worked, so governments are trying &lt;u&gt;&lt;a href=&quot;https://www.economist.com/international/2026/10/08/nagging-people-to-eat-healthily-does-not-work?utm_campaign=a.io&amp;utm_medium=audio.podcast.np&amp;utm_source=theintelligence&amp;utm_content=discovery.content.anonymous.tr_shownotes_na-na_article&amp;utm_term=sa.listeners&quot; rel=&quot;noopener noreferrer&quot; target=&quot;_blank&quot;&gt;new ways&lt;/a&gt;&lt;/u&gt; to get citizens to eat well, from scary labelling to taxing the junkiest foods. Will it work? The death of a &lt;u&gt;&lt;a hr', 'https://sphinx.acast.com/p/open/s/d556eb54-6160-4c85-95f4-47d9f5216c49/a/theeconomistallaudio/e/6ac8c16cd3bfab176e10a5a7/media.mp3?tk=eyJ0ayI6ImRlZmF1bHQiLCJhZHMiOnRydWUsInNwb25zIjp0cnVlLCJzdGF0dXMiOiJwdWJsaWMifQ==&amp;sig=ghiZ4ss4qRv6Zaqb5nhHOlfC0m2Aj5K80CksgsJg9cw', 1482, '2026-10-09 10:26:52'::timestamptz, 36000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Valley of the shadow of debt: bond-market jitters', '&lt;p&gt;Bond yields across the rich world keep ticking up. We take a global look at where the risks are mounting most, and just how much worry is warranted. What might have once seemed fanciful is becoming real: delivering daylight to dark parts of the world using &lt;u&gt;&lt;a href=&quot;https://www.economist.com/science-and-technology/2026/09/23/space-going-mirrors-could-offer-daylight-on-demand?utm_campaign=a.io&amp;utm_medium=audio.podcast.np&amp;utm_source=theintelligence&amp;utm_content=discovery.content.anonymous.tr_shownotes_na-na_article&amp;utm_term=sa.listeners&quot; rel=&quot;noo', 'https://sphinx.acast.com/p/open/s/d556eb54-6160-4c85-95f4-47d9f5216c49/a/theeconomistallaudio/e/6ac76b2739599f7c56294e34/media.mp3?tk=eyJ0ayI6ImRlZmF1bHQiLCJhZHMiOnRydWUsInNwb25zIjp0cnVlLCJzdGF0dXMiOiJwdWJsaWMifQ==&amp;sig=Jkia7Xo6855jzuIBKB5UcUHa42-TymCo3zSed8vI3xY', 1299, '2026-10-08 10:06:31'::timestamptz, 37000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Gilets jeunes? France’s school protests', '&lt;p&gt;What started as a small protest about conditions of a school and of schooling has &lt;u&gt;&lt;a href=&quot;https://www.economist.com/europe/2026/10/02/schoolyard-protests-are-setting-france-ablaze?utm_campaign=a.io&amp;utm_medium=audio.podcast.np&amp;utm_source=theintelligence&amp;utm_content=discovery.content.anonymous.tr_shownotes_na-na_article&amp;utm_term=sa.listeners&quot; rel=&quot;noopener noreferrer&quot; target=&quot;_blank&quot;&gt;mushroomed&lt;/a&gt;&lt;/u&gt;, and tapped into national anxieties that may prove hard to tame. In the context of the “Cornell 7” case we examin', 'https://sphinx.acast.com/p/open/s/d556eb54-6160-4c85-95f4-47d9f5216c49/a/theeconomistallaudio/e/6ac617ea8f90a39dfc5baf52/media.mp3?tk=eyJ0ayI6ImRlZmF1bHQiLCJhZHMiOnRydWUsInNwb25zIjp0cnVlLCJzdGF0dXMiOiJwdWJsaWMifQ==&amp;sig=Nx7pxUUORy_4_0SIvFDY6dNfMGuevwW_c7-xeBvvHH0', 1176, '2026-10-07 10:38:48'::timestamptz, 38000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'House call: Spain’s snap election', '&lt;p&gt;Prime Minister Pedro Sánchez is gambling that anger about housing might solidify his mandate in a &lt;u&gt;&lt;a href=&quot;https://www.economist.com/europe/2026/10/05/pedro-sanchez-gambles-on-a-snap-election-and-populist-policies?utm_campaign=a.io&amp;utm_medium=audio.podcast.np&amp;utm_source=theintelligence&amp;utm_content=discovery.content.anonymous.tr_shownotes_na-na_article&amp;utm_term=sa.listeners&quot; rel=&quot;noopener noreferrer&quot; target=&quot;_blank&quot;&gt;snap poll&lt;/a&gt;&lt;/u&gt;. Most probably it will instead add to the rightward shift in European politics. A', 'https://sphinx.acast.com/p/open/s/d556eb54-6160-4c85-95f4-47d9f5216c49/a/theeconomistallaudio/e/6ac4ce946c844f245fde3434/media.mp3?tk=eyJ0ayI6ImRlZmF1bHQiLCJhZHMiOnRydWUsInNwb25zIjp0cnVlLCJzdGF0dXMiOiJwdWJsaWMifQ==&amp;sig=gN9V51EqMHOJ2C2kKAaFnXbDKOKnQee2wJidRMHcbBY', 1353, '2026-10-06 10:33:56'::timestamptz, 39000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Here comes the son? Brazil’s election tips rightward', '&lt;p&gt;Flávio Bolsonaro, populist-right son of the imprisoned coup architect Jair, received the &lt;u&gt;&lt;a href=&quot;https://www.economist.com/the-americas/2026/10/05/all-signs-point-to-a-bolsonaro-comeback-in-brazil?utm_campaign=a.io&amp;utm_medium=audio.podcast.np&amp;utm_source=theintelligence&amp;utm_content=discovery.content.anonymous.tr_shownotes_na-na_article&amp;utm_term=sa.listeners&quot; rel=&quot;noopener noreferrer&quot; target=&quot;_blank&quot;&gt;most votes&lt;/a&gt;&lt;/u&gt; in the presidential first round. We ask why Luiz Inácio Lula da Silva, the incumbent, fell behin', 'https://sphinx.acast.com/p/open/s/d556eb54-6160-4c85-95f4-47d9f5216c49/a/theeconomistallaudio/e/6ac36ea80d8a484144c61eb9/media.mp3?tk=eyJ0ayI6ImRlZmF1bHQiLCJhZHMiOnRydWUsInNwb25zIjp0cnVlLCJzdGF0dXMiOiJwdWJsaWMifQ==&amp;sig=QEvYVl9lbLB78b9-EzgaaO4WAzYQtfWcN_yalxlj9BE', 1361, '2026-10-05 10:01:24'::timestamptz, 40000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Coffer stop: AI may shrink tax base', '&lt;p&gt;If Artificial Intelligence results in job losses or lower salaries, &lt;u&gt;&lt;a href=&quot;https://www.economist.com/finance-and-economics/2026/09/29/how-the-ai-boom-could-worsen-the-rich-worlds-fiscal-crunch?utm_campaign=a.io&amp;utm_medium=audio.podcast.np&amp;utm_source=theintelligence&amp;utm_content=discovery.content.anonymous.tr_shownotes_na-na_article&amp;utm_term=sa.listeners&quot; rel=&quot;noopener noreferrer&quot; target=&quot;_blank&quot;&gt;government revenues&lt;/a&gt;&lt;/u&gt; will fall. Our correspondent explains how best to tax the windfalls from AI. &lt;u&gt;&lt;', 'https://sphinx.acast.com/p/open/s/d556eb54-6160-4c85-95f4-47d9f5216c49/a/theeconomistallaudio/e/6abf81fdb06169dc7218d384/media.mp3?tk=eyJ0ayI6ImRlZmF1bHQiLCJhZHMiOnRydWUsInNwb25zIjp0cnVlLCJzdGF0dXMiOiJwdWJsaWMifQ==&amp;sig=uKw5d-undlensCv4X8eonxnFM2ErdO_IlRpF2TsHaZw', 1588, '2026-10-02 10:05:49'::timestamptz, 41000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Trial and terror: Russia escalates Kyiv campaign', '&lt;p&gt;Russia has embarked on a &lt;u&gt;&lt;a href=&quot;https://www.economist.com/europe/2026/09/29/putins-new-bombardment-of-kyiv-has-a-terrible-logic?utm_campaign=a.io&amp;utm_medium=audio.podcast.np&amp;utm_source=theintelligence&amp;utm_content=discovery.content.anonymous.tr_shownotes_na-na_article&amp;utm_term=sa.listeners&quot; rel=&quot;noopener noreferrer&quot; target=&quot;_blank&quot;&gt;new campaign&lt;/a&gt;&lt;/u&gt; to quell Ukraine, focused on supermarkets, playgrounds and other civilian targets. Our correspondent reports on the toll on daily life in Kyiv. Despite the backla', 'https://sphinx.acast.com/p/open/s/d556eb54-6160-4c85-95f4-47d9f5216c49/a/theeconomistallaudio/e/6abe39c382177b9ab8a8904c/media.mp3?tk=eyJ0ayI6ImRlZmF1bHQiLCJhZHMiOnRydWUsInNwb25zIjp0cnVlLCJzdGF0dXMiOiJwdWJsaWMifQ==&amp;sig=RwAt1peDw6V1IkewUUnc9Ek25yoIUX8yac9ZTW6Yofg', 1300, '2026-10-01 10:45:23'::timestamptz, 42000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Cheques and the City: Premier League disgrace', '&lt;p&gt;An independent commission has found Manchester City guilty of breaching over 100 rules. What penalty will the Premier League exact? Russia’s increasingly &lt;u&gt;&lt;a href=&quot;https://www.economist.com/europe/2026/09/21/russias-grey-zone-attacks-on-europe-are-growing-more-brazen?utm_campaign=a.io&amp;utm_medium=audio.podcast.np&amp;utm_source=theintelligence&amp;utm_content=discovery.content.anonymous.tr_shownotes_na-na_article&amp;utm_term=sa.listeners&quot; rel=&quot;noopener noreferrer&quot; target=&quot;_blank&quot;&gt;brazen attempts&lt;/a&gt;&lt;/u&gt; to provoke and undermi', 'https://sphinx.acast.com/p/open/s/d556eb54-6160-4c85-95f4-47d9f5216c49/a/theeconomistallaudio/e/6abcdaab4e059d44b566ca74/media.mp3?tk=eyJ0ayI6ImRlZmF1bHQiLCJhZHMiOnRydWUsInNwb25zIjp0cnVlLCJzdGF0dXMiOiJwdWJsaWMifQ==&amp;sig=ZCoL0m1-x67xqi7nZtHBlp5nao3vuSXy3E_6_F4e5R0', 1252, '2026-09-30 09:47:23'::timestamptz, 43000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Brazil rut: Lula v Bolsonaro, again', '&lt;p&gt;On October 4th, Brazil faces a polarising &lt;u&gt;&lt;a href=&quot;https://www.economist.com/leaders/2026/09/24/brazil-turns-its-back-on-the-future?utm_campaign=a.io&amp;utm_medium=audio.podcast.np&amp;utm_source=theintelligence&amp;utm_content=discovery.content.anonymous.tr_shownotes_na-na_article&amp;utm_term=sa.listeners&quot; rel=&quot;noopener noreferrer&quot; target=&quot;_blank&quot;&gt;general election&lt;/a&gt;&lt;/u&gt;: re-elect the octogenarian incumbent or pick the son of a former president jailed for attempting a coup. In some countries &lt;u&gt;&lt;a href=&quot;https:/', 'https://sphinx.acast.com/p/open/s/d556eb54-6160-4c85-95f4-47d9f5216c49/a/theeconomistallaudio/e/6abb8653ed4e198024b38eb5/media.mp3?tk=eyJ0ayI6ImRlZmF1bHQiLCJhZHMiOnRydWUsInNwb25zIjp0cnVlLCJzdGF0dXMiOiJwdWJsaWMifQ==&amp;sig=u1EbP8FyXKVDmFedQ0I8pe3y6gyGFOgYUxoKwyWfdig', 1271, '2026-09-29 09:35:15'::timestamptz, 44000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Foiled plot: did Iran plan British base attack?', '&lt;p&gt;Five men are in custody under suspicion of explosives and terrorism offences after being arrested near a British military base used by American aircraft. This could mark a significant escalation in Iranian hybrid warfare. What &lt;u&gt;&lt;a href=&quot;https://www.economist.com/business/2026/09/13/how-an-oil-supply-crisis-could-bring-about-an-investment-boom?utm_campaign=a.io&amp;utm_medium=audio.podcast.np&amp;utm_source=theintelligence&amp;utm_content=discovery.content.anonymous.tr_shownotes_na-na_article&amp;utm_term=sa.listeners&quot; rel=&quot;noopener noreferrer&quot; target=&qu', 'https://sphinx.acast.com/p/open/s/d556eb54-6160-4c85-95f4-47d9f5216c49/a/theeconomistallaudio/e/6aba32b170b66274d96fb345/media.mp3?tk=eyJ0ayI6ImRlZmF1bHQiLCJhZHMiOnRydWUsInNwb25zIjp0cnVlLCJzdGF0dXMiOiJwdWJsaWMifQ==&amp;sig=2wPYslr6liYsNPWF5hdFoqXznM_lxEGrYLihUV6iqBo', 1203, '2026-09-28 09:26:09'::timestamptz, 45000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Big meet, little meat: the Trump-Xi summit', '&lt;p&gt;Not much of real substance appears to have emerged from the get-together. But our correspondent says there are clues of how both sides view an evolving relationship. Tommy Robinson, a British far-right influencer, is increasingly well known to MAGA types in America; we examine his rise to prominence. And remembering Bob Mackie, daring dressmaker to the stars. &lt;/p&gt;&lt;p&gt;&lt;em&gt;Watch extended clips from Insider &lt;u&gt;&lt;a href=&quot;https://www.economist.com/interactive/insider/previews?utm_campaign=a.brand_fy2627_q1_awareness-imp-tr_prospecting_global-global_direct_na&a', 'https://sphinx.acast.com/p/open/s/d556eb54-6160-4c85-95f4-47d9f5216c49/a/theeconomistallaudio/e/6ab6401bbd67ce4b534215db/media.mp3?tk=eyJ0ayI6ImRlZmF1bHQiLCJhZHMiOnRydWUsInNwb25zIjp0cnVlLCJzdGF0dXMiOiJwdWJsaWMifQ==&amp;sig=BiSxXSUhtMDceOtb5tzJsty5g8xRh77bzbtPjO__nQ4', 1633, '2026-09-25 09:53:25'::timestamptz, 46000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Home disadvantage: risks in housing markets', '&lt;p&gt;Rich-world house prices survived the last fit of interest-rate rises; our correspondent lays out why they &lt;u&gt;&lt;a href=&quot;https://www.economist.com/finance-and-economics/2026/09/20/house-prices-survived-the-last-interest-rate-rise-will-they-this-time?utm_campaign=a.io&amp;utm_medium=audio.podcast.np&amp;utm_source=theintelligence&amp;utm_content=discovery.content.anonymous.tr_shownotes_na-na_article&amp;utm_term=sa.listeners&quot; rel=&quot;noopener noreferrer&quot; target=&quot;_blank&quot;&gt;may not this time&lt;/a&gt;&lt;/u&gt;. Nine months after Australia banned social ', 'https://sphinx.acast.com/p/open/s/d556eb54-6160-4c85-95f4-47d9f5216c49/a/theeconomistallaudio/e/6ab4e209079b46c819b12f5e/media.mp3?tk=eyJ0ayI6ImRlZmF1bHQiLCJhZHMiOnRydWUsInNwb25zIjp0cnVlLCJzdGF0dXMiOiJwdWJsaWMifQ==&amp;sig=WoAVljw78-RHyhvPdkoXB13Z85b-D7g4JUHRyEcAppw', 1390, '2026-09-24 08:49:31'::timestamptz, 47000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'National front-runner: who can beat Le Pen?', '&lt;p&gt;Marine Le Pen, party leader of France’s populist-right National Rally, starts her fourth presidential bid with a commanding lead. The country’s political centre is broad, fragmented—and &lt;u&gt;&lt;a href=&quot;https://www.economist.com/europe/2026/09/14/frances-centre-has-one-question-who-can-beat-marine-le-pen?utm_campaign=a.io&amp;utm_medium=audio.podcast.np&amp;utm_source=theintelligence&amp;utm_content=discovery.content.anonymous.tr_shownotes_na-na_article&amp;utm_term=sa.listeners&quot; rel=&quot;noopener noreferrer&quot; target=&quot;_blank&quot;&gt;flagging&lt;/a&gt;&lt;/u&gt', 'https://sphinx.acast.com/p/open/s/d556eb54-6160-4c85-95f4-47d9f5216c49/a/theeconomistallaudio/e/6ab3960493749e4c0ba24e60/media.mp3?tk=eyJ0ayI6ImRlZmF1bHQiLCJhZHMiOnRydWUsInNwb25zIjp0cnVlLCJzdGF0dXMiOiJwdWJsaWMifQ==&amp;sig=g5l_2f30MSeBpZi9jivwpw3LE0hnCsI80BdSMSL1lxM', 1188, '2026-09-23 09:04:04'::timestamptz, 48000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'The mob rule: criminality consumes South Africa', '&lt;p&gt;An illicit shadow economy, rampant extortion and the capture of the criminal justice system: mafia members and tactics are &lt;a href=&quot;https://www.economist.com/middle-east-and-africa/2026/09/14/south-africa-is-at-risk-of-becoming-a-mafia-state?utm_campaign=a.io&amp;utm_medium=audio.podcast.np&amp;utm_source=theintelligence&amp;utm_content=discovery.content.anonymous.tr_shownotes_na-na_article&amp;utm_term=sa.listeners&quot; rel=&quot;noopener noreferrer&quot; target=&quot;_blank&quot;&gt;eating away&lt;/a&gt; at the state. Oura seems to have &lt;a href=&quot;https://www.economis', 'https://sphinx.acast.com/p/open/s/d556eb54-6160-4c85-95f4-47d9f5216c49/a/theeconomistallaudio/e/6ab24a5a1f5b87e5353dbc86/media.mp3?tk=eyJ0ayI6ImRlZmF1bHQiLCJhZHMiOnRydWUsInNwb25zIjp0cnVlLCJzdGF0dXMiOiJwdWJsaWMifQ==&amp;sig=vgXyCLfFZERy6ZZSlXUQJ8tv4uSRQtrQTGaDBDlMYqA', 1248, '2026-09-22 09:44:39'::timestamptz, 49000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Centre punch: Germany’s state-election shocker', '&lt;p&gt;Two more state-election results reveal surging support for both the far-right AfD and the populist-left Die Linke parties. Chancellor Friedrich Merz himself described the outcome as &lt;a href=&quot;https://www.economist.com/europe/2026/09/20/friedrich-merz-rues-disaster-as-populists-win-state-elections?utm_campaign=a.io&amp;utm_medium=audio.podcast.np&amp;utm_source=theintelligence&amp;utm_content=discovery.content.anonymous.tr_shownotes_na-na_article&amp;utm_term=sa.listeners&quot; rel=&quot;noopener noreferrer&quot; target=&quot;_blank&quot;&gt;a disaster&lt;/a&gt;; what will it me', 'https://sphinx.acast.com/p/open/s/d556eb54-6160-4c85-95f4-47d9f5216c49/a/theeconomistallaudio/e/6ab0f8597aa361c6128028b9/media.mp3?tk=eyJ0ayI6ImRlZmF1bHQiLCJhZHMiOnRydWUsInNwb25zIjp0cnVlLCJzdGF0dXMiOiJwdWJsaWMifQ==&amp;sig=VTwDH1O3ZFcqbo38sb7bXlfPPbXzEff4DNNRw49R2xs', 1266, '2026-09-21 10:28:04'::timestamptz, 50000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Drone truth: Russia has the upper hand', '&lt;p&gt;After a visit to &lt;a href=&quot;https://www.economist.com/briefing/2026/09/17/russia-has-entered-a-new-phase-of-total-war?utm_campaign=a.io&amp;utm_medium=audio.podcast.np&amp;utm_source=theintelligence&amp;utm_content=discovery.content.anonymous.tr_shownotes_na-na_article&amp;utm_term=sa.listeners&quot; rel=&quot;noopener noreferrer&quot; target=&quot;_blank&quot;&gt;Ukraine&lt;/a&gt; last week, our defence editor reports on a new phase of the war as Kyiv and other civilian targets are bombarded by Russian missiles. He also visits an elite Ukrainian drone unit. Why &lt;a href=&quot', 'https://sphinx.acast.com/p/open/s/d556eb54-6160-4c85-95f4-47d9f5216c49/a/theeconomistallaudio/e/6aad03f98a1508074de8337e/media.mp3?tk=eyJ0ayI6ImRlZmF1bHQiLCJhZHMiOnRydWUsInNwb25zIjp0cnVlLCJzdGF0dXMiOiJwdWJsaWMifQ==&amp;sig=io_z-qc1aIrVdp8hdI3IgGKyTuPZqt1akKda0RA1o2o', 1548, '2026-09-18 09:42:38'::timestamptz, 51000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Rise and shine: Warsh’s Fed rate test', '&lt;p&gt;The &lt;a href=&quot;https://www.economist.com/leaders/2026/09/10/kevin-warsh-should-raise-interest-rates?utm_campaign=a.io&amp;utm_medium=audio.podcast.np&amp;utm_source=theintelligence&amp;utm_content=discovery.content.anonymous.tr_shownotes_na-na_article&amp;utm_term=sa.listeners&quot; rel=&quot;noopener noreferrer&quot; target=&quot;_blank&quot;&gt;Federal Reserve&lt;/a&gt; has raised interest rates for the first time since July 2023. For the central bank’s new chair Kevin Warsh, that decision was a test both of monetary policy and politics. A governor’s election in &lt;a href=&qu', 'https://sphinx.acast.com/p/open/s/d556eb54-6160-4c85-95f4-47d9f5216c49/a/theeconomistallaudio/e/6aabb60b964bc344092c48cd/media.mp3?tk=eyJ0ayI6ImRlZmF1bHQiLCJhZHMiOnRydWUsInNwb25zIjp0cnVlLCJzdGF0dXMiOiJwdWJsaWMifQ==&amp;sig=M-Ixir76HM-n1J1xuHUtcWlFRJtEFCxp_IpwicllQbE', 1314, '2026-09-17 10:21:12'::timestamptz, 52000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'The end of the world is AI? An existential threat', '&lt;p&gt;Is &lt;a href=&quot;https://www.economist.com/international/2026/09/15/making-ai-safer-is-not-impossible-but-agreeing-to-do-so-may-be?utm_campaign=a.io&amp;utm_medium=audio.podcast.np&amp;utm_source=theintelligence&amp;utm_content=discovery.content.anonymous.tr_shownotes_na-na_article&amp;utm_term=sa.listeners&quot; rel=&quot;noopener noreferrer&quot; target=&quot;_blank&quot;&gt;artificial intelligence&lt;/a&gt; becoming uncontrollably powerful? Our correspondent analyses whether a pause to breakneck development is possible or feasible. We have entered the new age of the &lt;a href=&', 'https://sphinx.acast.com/p/open/s/d556eb54-6160-4c85-95f4-47d9f5216c49/a/theeconomistallaudio/e/6aaa68a64cef87591d2b659b/media.mp3?tk=eyJ0ayI6ImRlZmF1bHQiLCJhZHMiOnRydWUsInNwb25zIjp0cnVlLCJzdGF0dXMiOiJwdWJsaWMifQ==&amp;sig=cEHIC1ARzRDLY9u1NRaH4I70f_cE7Kg4MLF8-T9j_4o', 1456, '2026-09-16 10:00:06'::timestamptz, 53000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Islamism in Britain: what is the threat?', '&lt;p&gt;Though a growing share of the British population is anxious about Islam, they have no reason to be. &lt;a href=&quot;https://www.economist.com/britain/2026/09/10/islamism-is-a-threat-to-britain-islam-is-not?utm_campaign=a.io&amp;utm_medium=audio.podcast.np&amp;utm_source=theintelligence&amp;utm_content=discovery.content.anonymous.tr_shownotes_na-na_article&amp;utm_term=sa.listeners&quot; rel=&quot;noopener noreferrer&quot; target=&quot;_blank&quot;&gt;Islamism&lt;/a&gt;, a fringe ideology that believes government and society should be guided by Islamic principles, is the real concern.', 'https://sphinx.acast.com/p/open/s/d556eb54-6160-4c85-95f4-47d9f5216c49/a/theeconomistallaudio/e/6aa9164ffca3d5c77b4b383a/media.mp3?tk=eyJ0ayI6ImRlZmF1bHQiLCJhZHMiOnRydWUsInNwb25zIjp0cnVlLCJzdGF0dXMiOiJwdWJsaWMifQ==&amp;sig=zYjKc8pKQwECxNc1Bt9BnHTxq5sAc5swL_4Fh_0VqT8', 1421, '2026-09-15 09:59:36'::timestamptz, 54000);
END $$;

-- ---------- The Mel Robbins Podcast ----------
DO $$
DECLARE
  v_host_id uuid;
  v_pod_id uuid;
  v_cat uuid;
BEGIN
  SELECT id INTO v_cat FROM categories WHERE name_ar = 'المسيرة المهنية' LIMIT 1;
  INSERT INTO hosts (name_ar, slug, photo_url, cover_url, title_ar, specialty_ar, bio_ar, country, category_id, is_verified, followers_count)
  VALUES ('Mel Robbins', 'the-mel-robbins-podcast', 'https://is1-ssl.mzstatic.com/image/thumb/Podcasts211/v4/ab/66/a5/ab66a5f5-b52b-c70a-227b-0721bd9dc660/mza_13546984924981879479.jpg/600x600bb.jpg', 'https://is1-ssl.mzstatic.com/image/thumb/Podcasts211/v4/ab/66/a5/ab66a5f5-b52b-c70a-227b-0721bd9dc660/mza_13546984924981879479.jpg/600x600bb.jpg', 'مقدم', 'المسيرة المهنية', 'بودكاست حقيقي: The Mel Robbins Podcast', 'أونلاين', v_cat, true, 50000)
  RETURNING id INTO v_host_id;

  INSERT INTO podcasts (title, description, host_id, category_id, type, cover_url, audience_level, plays_count, rating_avg)
  VALUES ('The Mel Robbins Podcast', 'You can change your life and Mel Robbins will show you how. The Mel Robbins Podcast is the #1 podcast on the globe for a reason: Mel’s simple, research-backed advice has changed millions of people’s lives, and in every episode, she’s giving you all her hard-fought secrets, science-backed tools, and deeply personal stories, so you can change yours too. If you’re a new listener, you’re in the right place. Every episode will empower you to create a better life and help you take a step toward the life you want. Want more? Follow along at @melrobbins Subscribe to SiriusXM Podcasts+ to listen to new', v_host_id, v_cat, 'professional', 'https://is1-ssl.mzstatic.com/image/thumb/Podcasts211/v4/ab/66/a5/ab66a5f5-b52b-c70a-227b-0721bd9dc660/mza_13546984924981879479.jpg/600x600bb.jpg', 'beginner', 100000, 4.7)
  RETURNING id INTO v_pod_id;

  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, '#1 Communication Expert: 9 Habits for Clearer Speaking (I Wish I Knew Sooner)', 'If you have ever walked away from a conversation feeling embarrassed, unheard, or disrespected, this episode is for you. Maybe you rambled, used the wrong words, or totally froze when someone put you on the spot.&nbsp; You don’t have to go through that again.&nbsp; Today, Mel sits down with world-renowned communication expert Vinh Giang for a masterclass in how to stop sounding insecure, speak more clearly, and get people to listen when you talk.&nbsp; You can be great at what you do, have incredible ideas, and work harder than everyone else. But if you struggle to communicate, Vinh says peopl', 'https://dts.podtrac.com/redirect.mp3/pdst.fm/e/pdrl.fm/123755/stitcher.simplecastaudio.com/b9de9f5f-6dab-4833-b4c2-05f1d28dd998/episodes/f3d0c158-759c-41e9-8b9e-b72e92d37381/audio/128/default.mp3?aid=rss_feed&amp;awCollectionId=b9de9f5f-6dab-4833-b4c2-05f1d28dd998&amp;awEpisodeId=f3d0c158-759c-41e9-8b9e-b72e92d37381&amp;feed=UCwaTX1J', 3256, '2026-11-19 05:05:00'::timestamptz, 5000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Why Boys and Men Are Quietly Struggling &amp; What They Need To Hear', 'Why do so many men shut down emotionally, struggle to ask for help, or feel like nothing they do is ever enough? This episode will change the way you see the men in your life – and the way they see themselves.&nbsp; Today, Mel sits down with her husband of 30 years, Christopher Robbins, who has spent the last decade leading Soul Degree men’s retreats and helping men navigate some of the most complicated feelings in life. Fresh off a five day father-son retreat, Chris is sharing 5 powerful things he''s learned about men that everyone needs to hear. And the first? Men are at war with themselves. ', 'https://dts.podtrac.com/redirect.mp3/pdst.fm/e/pdrl.fm/123755/stitcher.simplecastaudio.com/b9de9f5f-6dab-4833-b4c2-05f1d28dd998/episodes/0bb20d1b-a46e-465b-b1ce-0dd24402fdc9/audio/128/default.mp3?aid=rss_feed&amp;awCollectionId=b9de9f5f-6dab-4833-b4c2-05f1d28dd998&amp;awEpisodeId=0bb20d1b-a46e-465b-b1ce-0dd24402fdc9&amp;feed=UCwaTX1J', 3725, '2026-11-16 05:05:00'::timestamptz, 6000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'What Your Doctor May Be Missing: The Real Reason for Moodiness, Acne, Weight Gain, and Anxiety', 'This is the health advice every woman, particularly those in their teens, 20s, 30s, and 40s, needs to hear. Today, world-renowned OB-GYN and women’s health advocate Dr. Thaïs Aliabadi, MD, known as Dr. A, is here for a private appointment with you. She has shared before on this podcast about breast cancer. This episode covers entirely different topics: essential, life-changing information on fertility, PMS, PMDD, PMOS, and endometriosis. This conversation was so eye-opening for Mel that right after taping it, she flew herself and her two daughters, both in their 20s, across the country to see ', 'https://dts.podtrac.com/redirect.mp3/pdst.fm/e/pdrl.fm/123755/stitcher.simplecastaudio.com/b9de9f5f-6dab-4833-b4c2-05f1d28dd998/episodes/22313a12-3b3f-405b-a5a2-aa7dcfb519e4/audio/128/default.mp3?aid=rss_feed&amp;awCollectionId=b9de9f5f-6dab-4833-b4c2-05f1d28dd998&amp;awEpisodeId=22313a12-3b3f-405b-a5a2-aa7dcfb519e4&amp;feed=UCwaTX1J', 3025, '2026-11-14 05:05:00'::timestamptz, 7000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'The Silent Signs of Breast Cancer &amp; How to Know Your Cancer Risk With World-Renowned OB-GYN', 'This episode is a MUST listen.&nbsp; It’s one of the most important conversations about women’s health we’ve ever had on The Mel Robbins Podcast.&nbsp; Today, you’re going to learn life-saving information every woman needs to know about cancer prevention, the screenings and tests that could help detect cancer early, and how to advocate for your health at every age. Mel is joined by Dr. Thaïs Aliabadi, MD, a world-renowned OB-GYN, gynecological surgeon, breast cancer survivor, and women''s health advocate. Known as Dr. A, she''s spent decades caring for women, performing advanced gynecological su', 'https://dts.podtrac.com/redirect.mp3/pdst.fm/e/pdrl.fm/123755/stitcher.simplecastaudio.com/b9de9f5f-6dab-4833-b4c2-05f1d28dd998/episodes/10bba662-ab82-43a0-8ca8-fee77bf3b1d9/audio/128/default.mp3?aid=rss_feed&amp;awCollectionId=b9de9f5f-6dab-4833-b4c2-05f1d28dd998&amp;awEpisodeId=10bba662-ab82-43a0-8ca8-fee77bf3b1d9&amp;feed=UCwaTX1J', 3447, '2026-11-12 05:05:00'::timestamptz, 8000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Don’t Waste Your Life: An 89-Year-Old’s Best Life Advice For You', 'You are in for a treat today. You’re getting The Mel Robbins Podcast on the go! Last week, my mother-in-law, Judie, walked into our kitchen in Vermont and announced that she’s planning a big adventure, starting on her 90th birthday. She and her partner, John, have decided to backpack around Europe for a year. I KNOW!!!&nbsp; Yes, a 90-year-old woman and her boyfriend in his late 80s are shaking things up and backpacking around Europe. I was dying to know the story behind this decision. So I rounded everyone up - Judie, my husband Chris, and our two dogs, Yolo and Homie - and we headed outside ', 'https://dts.podtrac.com/redirect.mp3/pdst.fm/e/pdrl.fm/123755/stitcher.simplecastaudio.com/b9de9f5f-6dab-4833-b4c2-05f1d28dd998/episodes/5ffb35ec-8013-4885-8551-c0e1f0bd3c11/audio/128/default.mp3?aid=rss_feed&amp;awCollectionId=b9de9f5f-6dab-4833-b4c2-05f1d28dd998&amp;awEpisodeId=5ffb35ec-8013-4885-8551-c0e1f0bd3c11&amp;feed=UCwaTX1J', 2392, '2026-11-09 05:05:00'::timestamptz, 9000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Stop Being Available: How to Set Better Boundaries and Take Your Power Back', 'Are you the person everyone depends on? Do you remember the appointments, make the plans, solve the problems, keep track of what everyone needs, and step in whenever something falls through the cracks? If that sounds familiar, this conversation is for you. In this deeply relatable and practical conversation, Mel sits down for another episode with world-renowned motivational speaker Dr. Eric Thomas, also known as “ET, The Hip Hop Preacher,” to talk about what happens when you become the person who holds everything together. Dr. Thomas is a pastor, educator, New York Times bestselling author, an', 'https://dts.podtrac.com/redirect.mp3/pdst.fm/e/pdrl.fm/123755/stitcher.simplecastaudio.com/b9de9f5f-6dab-4833-b4c2-05f1d28dd998/episodes/532fe886-893c-42b3-b194-bb38c5701d0c/audio/128/default.mp3?aid=rss_feed&amp;awCollectionId=b9de9f5f-6dab-4833-b4c2-05f1d28dd998&amp;awEpisodeId=532fe886-893c-42b3-b194-bb38c5701d0c&amp;feed=UCwaTX1J', 3147, '2026-11-07 05:05:00'::timestamptz, 10000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Focus on Yourself: Do THIS Before 2026 Ends to Get Back on Track with Eric Thomas', 'If you’ve been feeling like this year got away from you, this episode will help you get back on track. In this powerful and practical conversation, Mel sits down with world-renowned pastor, and motivational speaker, and New York Times Bestselling author Dr. Eric Thomas to talk about how to get yourself back on track when life has knocked you off course. Dr. Thomas knows what it feels like to have your circumstances work against you. He went from being homeless and dropping out of high school to earning his Ph.D. in education from Michigan State University and becoming one of the most influenti', 'https://dts.podtrac.com/redirect.mp3/pdst.fm/e/pdrl.fm/123755/stitcher.simplecastaudio.com/b9de9f5f-6dab-4833-b4c2-05f1d28dd998/episodes/b826b39b-5e32-4195-a50a-24dfbee2f1bb/audio/128/default.mp3?aid=rss_feed&amp;awCollectionId=b9de9f5f-6dab-4833-b4c2-05f1d28dd998&amp;awEpisodeId=b826b39b-5e32-4195-a50a-24dfbee2f1bb&amp;feed=UCwaTX1J', 3440, '2026-11-05 05:05:00'::timestamptz, 11000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'My Daughter Got Brutally Honest About What I Got Wrong as a Mom (My Biggest Regrets)', 'What if you could sit down with your parents and finally tell them what they got wrong? Or ask your kids what they wish you''d done differently? Today, Mel and her daughter Sawyer are having the kind of honest conversation most families never have. And Sawyer isn''t holding back. She asks Mel lots of questions, including: -What do you think you got wrong as my mom? -What do you wish you did differently? -What did raising three kids teach you? Mel talks about her biggest regrets, the mistakes she''s still making, and the ways her own childhood shaped the mother she became. But what makes this conv', 'https://dts.podtrac.com/redirect.mp3/pdst.fm/e/pdrl.fm/123755/stitcher.simplecastaudio.com/b9de9f5f-6dab-4833-b4c2-05f1d28dd998/episodes/2a1db4a8-6973-4393-b20c-0935bfe6822a/audio/128/default.mp3?aid=rss_feed&amp;awCollectionId=b9de9f5f-6dab-4833-b4c2-05f1d28dd998&amp;awEpisodeId=2a1db4a8-6973-4393-b20c-0935bfe6822a&amp;feed=UCwaTX1J', 3071, '2026-11-02 05:05:00'::timestamptz, 12000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, '3 Signs You’re With the Right Person or if You Are Settling (Best Relationship Advice)', 'How do you know if the person you love is “the one”? How do you know when it''s time to walk away? How do you resolve your differences without blowing up your relationship? If you''ve been questioning your relationship, struggling to find love, feeling like you''re losing yourself in your partner''s life, or trying to get over a breakup, this conversation is for you. In this incredibly personal, funny, and honest conversation, Mel sits down with her 27-year-old daughter, Sawyer Robbins, to answer some of the hardest questions about love, dating, and relationships. Sawyer has a list of questions fr', 'https://dts.podtrac.com/redirect.mp3/pdst.fm/e/pdrl.fm/123755/stitcher.simplecastaudio.com/b9de9f5f-6dab-4833-b4c2-05f1d28dd998/episodes/2ed09e2a-7440-4715-8e77-a850c141316c/audio/128/default.mp3?aid=rss_feed&amp;awCollectionId=b9de9f5f-6dab-4833-b4c2-05f1d28dd998&amp;awEpisodeId=2ed09e2a-7440-4715-8e77-a850c141316c&amp;feed=UCwaTX1J', 3339, '2026-10-29 04:05:00'::timestamptz, 13000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'It’s Not Too Late: The 5 Shifts That Will Change the Rest of Your Year with Ed Mylett', 'What if the best part of the year hasn’t happened yet? If you’ve been feeling stuck, behind, and sick of your own bad habits, this conversation is for you. In this powerful and deeply personal episode, Mel sits down with bestselling author, entrepreneur, and one of favorite people Ed Mylett. They talk about what it takes to stop living on autopilot and start building a great life, at any age. Ed believes you are always one decision away from a different life. But here’s where Ed’s advice is completely fresh and different: Ed says building a great life isn’t about doing more, achieving more, or', 'https://dts.podtrac.com/redirect.mp3/pdst.fm/e/pdrl.fm/123755/stitcher.simplecastaudio.com/b9de9f5f-6dab-4833-b4c2-05f1d28dd998/episodes/89fab9ed-b4b4-4199-90f1-8ede0fb57d1c/audio/128/default.mp3?aid=rss_feed&amp;awCollectionId=b9de9f5f-6dab-4833-b4c2-05f1d28dd998&amp;awEpisodeId=89fab9ed-b4b4-4199-90f1-8ede0fb57d1c&amp;feed=UCwaTX1J', 3858, '2026-10-26 04:05:00'::timestamptz, 14000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'How to Let Go of What No Longer Serves You', 'How do you know when it’s time to let go of something in your life? And how do you know if you should keep fighting for it or finally move on? You need this episode because you probably have something in your life right now that’s draining your energy. Maybe it’s a relationship you’ve outgrown. A job that makes you miserable. A goal that no longer feels right. Or a way of thinking about yourself that’s holding you back. You know something needs to change, but you’re having a hard time letting go. Today, Mel will teach you how to recognize what’s weighing you down, trust what your energy and in', 'https://dts.podtrac.com/redirect.mp3/pdst.fm/e/pdrl.fm/123755/stitcher.simplecastaudio.com/b9de9f5f-6dab-4833-b4c2-05f1d28dd998/episodes/9e4b2ad9-7a54-4689-ab5f-23c49cc8416c/audio/128/default.mp3?aid=rss_feed&amp;awCollectionId=b9de9f5f-6dab-4833-b4c2-05f1d28dd998&amp;awEpisodeId=9e4b2ad9-7a54-4689-ab5f-23c49cc8416c&amp;feed=UCwaTX1J', 2948, '2026-10-24 04:05:00'::timestamptz, 15000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'How to Unlock Your Full Potential with #1 Professor Adam Grant', 'In today’s episode, you’re going to learn why you’re more capable than you think, what’s keeping you stuck, and the science-backed tools to unlock your full potential. Here to show you how to get more out of your life, your work, and your relationships is Adam Grant – a #1 New York Times bestselling author, renowned organizational psychologist, and one of Mel’s favorite thinkers, authors, and people of all time!&nbsp; Adam Grant is one of the world’s leading experts on motivation, human potential, and the science of success. He is a professor at the Wharton School of Business and the author of', 'https://dts.podtrac.com/redirect.mp3/pdst.fm/e/pdrl.fm/123755/stitcher.simplecastaudio.com/b9de9f5f-6dab-4833-b4c2-05f1d28dd998/episodes/5602525e-85ab-4685-afbe-5a0f0ac3be81/audio/128/default.mp3?aid=rss_feed&amp;awCollectionId=b9de9f5f-6dab-4833-b4c2-05f1d28dd998&amp;awEpisodeId=5602525e-85ab-4685-afbe-5a0f0ac3be81&amp;feed=UCwaTX1J', 4757, '2026-10-22 04:05:00'::timestamptz, 16000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Mayo Clinic Dermatologist: 5 Daily Habits That Are Aging Your Skin Faster &amp; What to Do Instead', 'You are getting the ultimate guide to skincare and skin health.&nbsp; In today’s episode, a Mayo Clinic dermatologist will reveal the 5 small habits for healthier, younger, and more radiant skin.&nbsp; Whether you''re dealing with dry skin, wrinkles, dark spots, acne, thinning hair, or your skin suddenly seems to be aging overnight, this episode is for you. Dr. Saranya Wyles, MD PhD, one of the leading dermatologists and physician-scientists at Mayo Clinic, is here with the science, the 5 specific things you can do to improve your skin health, and the truth about what works… and what doesn''t. D', 'https://dts.podtrac.com/redirect.mp3/pdst.fm/e/pdrl.fm/123755/stitcher.simplecastaudio.com/b9de9f5f-6dab-4833-b4c2-05f1d28dd998/episodes/43e784e4-a27f-4b71-83eb-de2204ab85b5/audio/128/default.mp3?aid=rss_feed&amp;awCollectionId=b9de9f5f-6dab-4833-b4c2-05f1d28dd998&amp;awEpisodeId=43e784e4-a27f-4b71-83eb-de2204ab85b5&amp;feed=UCwaTX1J', 5395, '2026-10-19 04:05:00'::timestamptz, 17000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'This One Skill Makes Every Relationship Better', 'If you want stronger relationships with the people in your life, there’s one skill you can get better at right now: empathy.&nbsp; Empathy isn’t just something you feel. It’s something you practice – in the small, everyday moments when someone needs to feel understood, supported, remembered, or cared for.&nbsp; In this episode, Mel teaches you 4 simple, research-backed ways to practice empathy and build more trust, connection, and closeness with your partner, family, friends, coworkers, and even people you’ve just met. You’ll learn how to stop assuming you know what someone is feeling and trul', 'https://dts.podtrac.com/redirect.mp3/pdst.fm/e/pdrl.fm/123755/stitcher.simplecastaudio.com/b9de9f5f-6dab-4833-b4c2-05f1d28dd998/episodes/255f22d1-aafe-43a6-9350-dc463e1a0258/audio/128/default.mp3?aid=rss_feed&amp;awCollectionId=b9de9f5f-6dab-4833-b4c2-05f1d28dd998&amp;awEpisodeId=255f22d1-aafe-43a6-9350-dc463e1a0258&amp;feed=UCwaTX1J', 2869, '2026-10-17 04:05:00'::timestamptz, 18000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Reinvent Yourself At Any Age: Ina Garten Shares the Secret to Transforming Your Life', 'If you’ve ever wondered whether it’s too late to change direction, start over, trust yourself, or create a life that feels more like you, you need to hear this conversation. Today, Mel is joined by the one and only Ina Garten. You know her as the Barefoot Contessa: beloved cookbook author, television host, entrepreneur, and one of the most trusted voices in food and entertaining. But the story of how Ina created this life is the part you need to hear. Because Ina did not start out with some master plan to build an iconic career. She changed direction. She took risks. She trusted her instincts.', 'https://dts.podtrac.com/redirect.mp3/pdst.fm/e/pdrl.fm/123755/stitcher.simplecastaudio.com/b9de9f5f-6dab-4833-b4c2-05f1d28dd998/episodes/448074c3-8d48-4045-8c04-46b8103088c5/audio/128/default.mp3?aid=rss_feed&amp;awCollectionId=b9de9f5f-6dab-4833-b4c2-05f1d28dd998&amp;awEpisodeId=448074c3-8d48-4045-8c04-46b8103088c5&amp;feed=UCwaTX1J', 3449, '2026-10-15 04:05:00'::timestamptz, 19000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, '#1 Neuroscientist: After Listening to This, Your Brain Will Not Be the Same', 'Today, you are getting a step-by-step guide on how to change your brain. Joining Mel is neuroscientist Dr. Lara Boyd, a professor at the University of British Columbia who directs the Brain Behaviour Lab there.&nbsp; This #1 neuroscientist will teach you how to rewire your brain at any age.&nbsp; There''s a personal reason she''s devoted her life to this work. Before becoming a neuroscientist, Dr. Boyd was a physical therapist. She spent three months unsuccessfully trying to help a man with a brain injury learn to walk again.&nbsp; Frustrated by how little she understood what was happening insid', 'https://dts.podtrac.com/redirect.mp3/pdst.fm/e/pdrl.fm/123755/stitcher.simplecastaudio.com/b9de9f5f-6dab-4833-b4c2-05f1d28dd998/episodes/455289de-5105-4bf8-a0e7-0a0cf7ef0bfa/audio/128/default.mp3?aid=rss_feed&amp;awCollectionId=b9de9f5f-6dab-4833-b4c2-05f1d28dd998&amp;awEpisodeId=455289de-5105-4bf8-a0e7-0a0cf7ef0bfa&amp;feed=UCwaTX1J', 4498, '2026-10-12 04:05:00'::timestamptz, 20000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'How to Stop Being Overlooked &amp; Start Getting What You Want With Top Business School Professor', 'What are you not doing because you’re afraid nobody will notice? In this episode, you’re going to learn one of the most important career skills nobody teaches you: how to make sure your work, ideas, and contributions get seen. Today, Mel sits down with Professor Marina Cooley, an award-winning professor at Emory University’s Goizueta Business School who teaches marketing and the attention economy: how to break through the noise, make your ideas memorable, and get people to pay attention. Because doing great work is not enough if nobody knows you’re doing it. If you’ve ever felt like you’re wor', 'https://dts.podtrac.com/redirect.mp3/pdst.fm/e/pdrl.fm/123755/stitcher.simplecastaudio.com/b9de9f5f-6dab-4833-b4c2-05f1d28dd998/episodes/16a5ac96-767d-4272-b797-94f1445b742b/audio/128/default.mp3?aid=rss_feed&amp;awCollectionId=b9de9f5f-6dab-4833-b4c2-05f1d28dd998&amp;awEpisodeId=16a5ac96-767d-4272-b797-94f1445b742b&amp;feed=UCwaTX1J', 3952, '2026-10-10 04:05:00'::timestamptz, 21000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'The Ultimate Guide to Male Hormones &amp; Men’s Health', 'This is the ultimate guide to male hormones and men’s health. If a man you love has seemed a bit off lately, this episode will help you understand why. It’s for both men - and the people who love them. This conversation, the first-ever men’s health episode of The Mel Robbins Podcast, was inspired by Mel wanting to learn more about her husband Chris and what she can do to help him with his hormones.&nbsp; Specifically, it all began with the question: should he be taking testosterone? That led Mel to the world-renowned Stanford urologist Dr. Michael Eisenberg, who joins her today to talk all thi', 'https://dts.podtrac.com/redirect.mp3/pdst.fm/e/pdrl.fm/123755/stitcher.simplecastaudio.com/b9de9f5f-6dab-4833-b4c2-05f1d28dd998/episodes/b058b8e1-afc2-43ad-a169-2d7783f7c52a/audio/128/default.mp3?aid=rss_feed&amp;awCollectionId=b9de9f5f-6dab-4833-b4c2-05f1d28dd998&amp;awEpisodeId=b058b8e1-afc2-43ad-a169-2d7783f7c52a&amp;feed=UCwaTX1J', 4250, '2026-10-08 04:05:00'::timestamptz, 22000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'The Ultimate Life Advice: How to Get Motivated, Build Confidence &amp; Create Better Relationships', 'Do you have a question about your life that you wish someone would just give you a straight answer to? In this episode, Mel is answering your biggest questions about relationships, career, health, confidence, change, and how to trust yourself when life feels uncertain. For the first time ever on The Mel Robbins Podcast, the entire episode is built around questions submitted by listeners around the world.&nbsp; Today, Mel gives you direct, practical advice to help you stop overthinking, get unstuck, and take the next step. You’ll learn how to deal with the guilt that comes with choosing yoursel', 'https://dts.podtrac.com/redirect.mp3/pdst.fm/e/pdrl.fm/123755/stitcher.simplecastaudio.com/b9de9f5f-6dab-4833-b4c2-05f1d28dd998/episodes/d3255b86-d4f3-42fe-91ed-0b01eff8d57d/audio/128/default.mp3?aid=rss_feed&amp;awCollectionId=b9de9f5f-6dab-4833-b4c2-05f1d28dd998&amp;awEpisodeId=d3255b86-d4f3-42fe-91ed-0b01eff8d57d&amp;feed=UCwaTX1J', 3982, '2026-10-05 04:05:00'::timestamptz, 23000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'How to Reinvent Yourself and Start a New Chapter', 'What if the life you’re living in now isn''t the life you’re meant to stay in? What if you could start writing a new chapter today? In this unforgettable conversation, Mel sits down with one of her favorite authors, John Grisham, whose books have sold nearly half a billion copies worldwide. But this isn''t a typical interview about having a legendary career. This is a deeply personal conversation about reinvention, rejection, purpose, and the “golden moments” that change the entire direction of your life. 35 years ago, Mel was starting her first year of law school when she picked up John Grisham', 'https://dts.podtrac.com/redirect.mp3/pdst.fm/e/pdrl.fm/123755/stitcher.simplecastaudio.com/b9de9f5f-6dab-4833-b4c2-05f1d28dd998/episodes/de963090-e001-47b9-ab98-e7dda7bf5027/audio/128/default.mp3?aid=rss_feed&amp;awCollectionId=b9de9f5f-6dab-4833-b4c2-05f1d28dd998&amp;awEpisodeId=de963090-e001-47b9-ab98-e7dda7bf5027&amp;feed=UCwaTX1J', 4200, '2026-10-01 04:05:00'::timestamptz, 24000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'If You’re Struggling With Money, Listen to This', 'In this episode, you’ll learn some of the best financial advice you’ll ever hear - no matter what your financial situation is right now. If getting ahead only seems to be getting harder, and you’re tired of living paycheck to paycheck, you need to hear this: Harder doesn’t have to mean hopeless. Today, Mel sits down with Vivian Tu – bestselling author, and the personal finance educator millions know as Your Rich BFF –&nbsp; for a conversation about what to do when you’re over feeling broke, behind, or overwhelmed by money. Vivian has been there, and she knows how hard it is to get ahead right ', 'https://dts.podtrac.com/redirect.mp3/pdst.fm/e/pdrl.fm/123755/stitcher.simplecastaudio.com/b9de9f5f-6dab-4833-b4c2-05f1d28dd998/episodes/542c0b99-4904-447f-897c-a40590daa7a3/audio/128/default.mp3?aid=rss_feed&amp;awCollectionId=b9de9f5f-6dab-4833-b4c2-05f1d28dd998&amp;awEpisodeId=542c0b99-4904-447f-897c-a40590daa7a3&amp;feed=UCwaTX1J', 4112, '2026-09-28 04:05:00'::timestamptz, 25000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Body Language Expert: 6 Psychological Tricks to Turn Awkwardness into Confidence', 'Do you want to know how to talk to anyone with ease and confidence? In this episode, you will learn science-backed psychological tricks to be more successful, charismatic, and influential today. Today, Mel is bringing back one of the most tactical and empowering conversations ever on The Mel Robbins Podcast, with a brand-new introduction and new insights for right now. Vanessa Van Edwards is a behavioral researcher, bestselling author, and the founder of Science of People, a behavior lab that studies high achievers and the science of confidence, charisma, communication, and body language. She ', 'https://dts.podtrac.com/redirect.mp3/pdst.fm/e/pdrl.fm/123755/stitcher.simplecastaudio.com/b9de9f5f-6dab-4833-b4c2-05f1d28dd998/episodes/bf32d6d3-104f-415f-a146-5856feb5d7b9/audio/128/default.mp3?aid=rss_feed&amp;awCollectionId=b9de9f5f-6dab-4833-b4c2-05f1d28dd998&amp;awEpisodeId=bf32d6d3-104f-415f-a146-5856feb5d7b9&amp;feed=UCwaTX1J', 4952, '2026-09-26 04:05:00'::timestamptz, 26000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'The Most Important Divorce Advice You Will Ever Hear (From #1 Divorce Lawyer)', 'You wouldn''t believe the amount of times Mel has asked to do an episode on divorce And finally….here it is: The ULTIMATE guide on how to handle divorce - for you and the people you love. Whether you’ve been through a divorce, are thinking about one, are going through one now, have a loved one you need to support, or are the child of divorced parents, this episode is a resource. World renowned divorce lawyer James Sexton is back to break down divorce from every imaginable angle, and give takeaways that you can implement today regardless of where you are in what he calls divorce’s “six stages”. ', 'https://dts.podtrac.com/redirect.mp3/pdst.fm/e/pdrl.fm/123755/stitcher.simplecastaudio.com/b9de9f5f-6dab-4833-b4c2-05f1d28dd998/episodes/6af533b5-41f5-4086-9f3b-addc7ccbe818/audio/128/default.mp3?aid=rss_feed&amp;awCollectionId=b9de9f5f-6dab-4833-b4c2-05f1d28dd998&amp;awEpisodeId=6af533b5-41f5-4086-9f3b-addc7ccbe818&amp;feed=UCwaTX1J', 5211, '2026-09-24 04:05:00'::timestamptz, 27000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Let Them: How to Handle Difficult People &amp; Take Back Your Peace and Power', 'Today, Mel is digging into The Let Them Theory in a brand-new way – and answering the #1 question she’s been asked since the book became an international sensation with 10+ million copies sold:&nbsp; How do you use The Let Them Theory with the people you love who also frustrate you, worry you, disappoint you, or are just plain difficult? It’s one thing to say “Let Them” when someone cuts you off in traffic or an annoying stranger gets under your skin at the store. But what do you do when it’s someone you care about – your parent, your partner, your child, or your closest friend?&nbsp;&nbsp; Th', 'https://dts.podtrac.com/redirect.mp3/pdst.fm/e/pdrl.fm/123755/stitcher.simplecastaudio.com/b9de9f5f-6dab-4833-b4c2-05f1d28dd998/episodes/10a60f28-db9b-4feb-a8bf-e5ae11fdbd29/audio/128/default.mp3?aid=rss_feed&amp;awCollectionId=b9de9f5f-6dab-4833-b4c2-05f1d28dd998&amp;awEpisodeId=10a60f28-db9b-4feb-a8bf-e5ae11fdbd29&amp;feed=UCwaTX1J', 2837, '2026-09-21 04:05:00'::timestamptz, 28000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Oprah Winfrey: How to Find Your Unique Purpose, Authentic Power, and Calling In Life', 'This episode is a master class on how to live an incredible life. In one of the most powerful conversations ever recorded on The Mel Robbins Podcast, Mel sits down with someone she has looked up to for more than four decades: Oprah Winfrey. Mel first started watching Oprah on local television, before The Oprah Winfrey Show was nationally syndicated. Through every chapter of her own life, Mel has returned to Oprah’s work for perspective, encouragement, and direction. This is more than an interview for Mel. It is deeply personal. Now you get to hear the questions she has wanted to ask Oprah for ', 'https://dts.podtrac.com/redirect.mp3/pdst.fm/e/pdrl.fm/123755/stitcher.simplecastaudio.com/b9de9f5f-6dab-4833-b4c2-05f1d28dd998/episodes/65a69d64-ac0c-4df0-bc84-f612c8863421/audio/128/default.mp3?aid=rss_feed&amp;awCollectionId=b9de9f5f-6dab-4833-b4c2-05f1d28dd998&amp;awEpisodeId=65a69d64-ac0c-4df0-bc84-f612c8863421&amp;feed=UCwaTX1J', 4746, '2026-09-17 04:05:00'::timestamptz, 29000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
