  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, '30 Years of Marriage: 3 Things About Relationships I Wish Someone Told Me Sooner', 'Today is Mel’s 30th wedding anniversary. And she couldn''t think of a better way to celebrate than to have a sit down conversation with her husband Chris about the lessons they''ve learned along the way. This episode isn’t about the highlights – it’s talking about the hard lessons that have shaped their marriage these last 30 years. Mel and Chris unpack the years where they felt more like roommates than a married couple and they share stories from when stress got the best of them. They get into how resentment and bitterness created a distance that kept growing, and how they found their way back ', 'https://dts.podtrac.com/redirect.mp3/pdst.fm/e/pdrl.fm/123755/stitcher.simplecastaudio.com/b9de9f5f-6dab-4833-b4c2-05f1d28dd998/episodes/f00f08f7-c3dd-47cb-aa86-c5aa0245004c/audio/128/default.mp3?aid=rss_feed&amp;awCollectionId=b9de9f5f-6dab-4833-b4c2-05f1d28dd998&amp;awEpisodeId=f00f08f7-c3dd-47cb-aa86-c5aa0245004c&amp;feed=UCwaTX1J', 3865, '2026-08-24 04:05:00'::timestamptz, 36000);
