  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'The ADHD Doctor: How to Focus, Stop Procrastinating, Manage Your Emotions, &amp; Feel in Control', 'If you have ever been told that you are too emotional, sensitive, anxious, hormonal, disorganized, or simply not trying hard enough, this episode is for you. There’s a chance, according to Mel’s expert guest today, that like Mel, that the root cause of what you’re struggling with is actually ADHD. Today, Dr. Sasha Hamdani, MD, a board-certified psychiatrist and leading expert on ADHD, gives you the full and comprehensive explanation you deserve. She shares that ADHD is not just about attention. It can affect your emotions, motivation, energy, sleep, appetite, relationships, and ability to hand', 'https://dts.podtrac.com/redirect.mp3/pdst.fm/e/pdrl.fm/123755/stitcher.simplecastaudio.com/b9de9f5f-6dab-4833-b4c2-05f1d28dd998/episodes/56450273-9257-443c-b418-4c5680f122b3/audio/128/default.mp3?aid=rss_feed&amp;awCollectionId=b9de9f5f-6dab-4833-b4c2-05f1d28dd998&amp;awEpisodeId=56450273-9257-443c-b418-4c5680f122b3&amp;feed=UCwaTX1J', 4417, '2026-08-20 04:05:00'::timestamptz, 38000);
