  VALUES (v_pod_id, 'If You Only Listen to One Podcast This Week, Make It This One', 'This might be one of the greatest conversations Mel has ever had on this podcast. Today, you’re getting an absolute masterclass in motivation from one of the greatest athletes walking this earth: Shelly-Ann Fraser-Pryce. If you’ve ever felt self-doubt, pressure, or like your best days are behind you, you’re in the right place. In this conversation, Shelly-Ann does not hold back. Shelly-Ann is the most decorated 100-meter sprinter of all time, male or female. She has won Olympic gold 3 times. She has won 10 gold medals at the World Championships, with 2 of them coming after she gave birth to he', 'https://dts.podtrac.com/redirect.mp3/pdst.fm/e/pdrl.fm/123755/stitcher.simplecastaudio.com/b9de9f5f-6dab-4833-b4c2-05f1d28dd998/episodes/fdd749cd-9af9-46b3-80b3-0b660729a07c/audio/128/default.mp3?aid=rss_feed&amp;awCollectionId=b9de9f5f-6dab-4833-b4c2-05f1d28dd998&amp;awEpisodeId=fdd749cd-9af9-46b3-80b3-0b660729a07c&amp;feed=UCwaTX1J', 5661, '2026-08-03 04:05:00'::timestamptz, 44000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'MIT Longevity Expert: Do These 3 Things Now to Stay Young, Live Longer, &amp; Keep Your Freedom', 'What no one tells you about aging is that it starts long before you feel old. In fact, the choices you’re making in this moment are shaping how strong, independent, connected, and fulfilled you’ll feel decades from now. In this hopeful conversation, Mel sits down with MIT longevity expert Dr. Joseph Coughlin, founding director of the MIT AgeLab, for a wake-up call that will change how you plan the rest of your life. The good news? Dr. Coughlin says you’re probably going to live longer than you think. But longevity is not just about adding more years to your life. It is about deciding how you w', 'https://dts.podtrac.com/redirect.mp3/pdst.fm/e/pdrl.fm/123755/stitcher.simplecastaudio.com/b9de9f5f-6dab-4833-b4c2-05f1d28dd998/episodes/208ad219-b87a-4555-a810-3ec4c6c6b2fa/audio/128/default.mp3?aid=rss_feed&amp;awCollectionId=b9de9f5f-6dab-4833-b4c2-05f1d28dd998&amp;awEpisodeId=208ad219-b87a-4555-a810-3ec4c6c6b2fa&amp;feed=UCwaTX1J', 4946, '2026-07-30 04:05:00'::timestamptz, 45000);
