  VALUES (v_pod_id, '🎙️IMPORTANT EPISODE: Transform Your English Fluency in 90 Days, Podcast Listeners Get 50% OFF the 90 Day English Challenge | Real English Conversations Podcast for Global Professionals', 'In this special solo episode of the Real English Conversations Podcast, the show that helps global professionals to speak clearly and confidently at work, Curtis shares a rare, limited-time opportunity for listeners who are ready to finally transform their English communication skills. For the first time ever, podcast listeners can get 50% OFF any package of the 90-Day Next Level English Challenge , using the exclusive coupon code: 👉 90DAY50 This is the biggest discount Curtis has ever offered, designed specifically for listeners who want to take their English — and their confidence — to the ', 'https://dts.podtrac.com/redirect.mp3/pscrb.fm/rss/p/traffic.libsyn.com/secure/f2d756de-8697-40ae-8229-f32dc253974e/riverside_curtis__take_07___feb_14_2026_001_rec_youtube_videos_.mp3?dest-id=3695967', 375, '2026-02-14 22:58:00'::timestamptz, 38000);
