  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, '🎙️Confidence &amp; Firm Communication Coaching with Urnell Greaves | Real English Conversations Podcast for Global Professionals', 'In this episode of the Real English Conversations Podcast — the show that helps global professionals to speak clearly and confidently at work — host Curtis Davies talks with Urnell Greaves , the founder of FIRM Communication Coaching , a communication expert who helps professionals build real confidence, elevate their delivery, and communicate powerfully in high-stakes situations. Urnell has supported professionals to overcome fear, strengthen their presence, and speak with clarity and authority. He''s now formalizing his proven coaching process into a programme that will be available soon. Tod', 'https://dts.podtrac.com/redirect.mp3/pscrb.fm/rss/p/traffic.libsyn.com/secure/f2d756de-8697-40ae-8229-f32dc253974e/riverside_curtis__urnell_podcas...___jan_06_2026_001_rec_youtube_videos_.mp3?dest-id=3695967', 1243, '2026-01-14 11:30:00'::timestamptz, 42000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
