  VALUES (v_pod_id, '🎙️Business English Writing &amp; Storytelling with Award-Winning Author Aaron Ryan | Real English Conversations Podcast for Global Professionals', 'In this episode of the Real English Conversations Podcast, host Curtis Davies sits down with Aaron Ryan , an award-winning and bestselling author of nearly 40 books , including the fan-favorite Dissonance alien invasion saga, the Christian dystopian series The End , multiple sci-fi thrillers, children''s books, and business books — including his guide on self-publishing. Aaron''s creative journey began in second grade with a story called The Electric Boy . Since then, he has spent his life creating — not only as an author but also as a musician, producer, videographer, stage performer, voiceover', 'https://dts.podtrac.com/redirect.mp3/pscrb.fm/rss/p/traffic.libsyn.com/secure/f2d756de-8697-40ae-8229-f32dc253974e/riverside_curtis__aaron_ryan_po...___dec_23_2025_001_rec_new_episode_rec.mp3?dest-id=3695967', 1809, '2025-12-24 11:30:00'::timestamptz, 45000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, '🎙️Business English Communication for Podcasting &amp; Broadcasting with Todd Hancock | Real English Conversations Podcast for Global Professionals', 'In this episode of the Real English Conversations Podcast, host Curtis Davies sits down with Todd Hancock , one of Vancouver''s Canada''s most recognized radio personalities, a former longtime afternoon host on CFOX 99.3 The Fox (2002–2014), and creator of the hugely successful Toddcast Podcast , which continues to grow across Spotify, Apple Podcasts, YouTube, and beyond. Todd began his radio career in 1996 and spent nearly two decades in one of Canada''s most competitive markets, where he interviewed major artists, navigated unpredictable live broadcasts, and developed the confidence, speed, and', 'https://dts.podtrac.com/redirect.mp3/pscrb.fm/rss/p/traffic.libsyn.com/secure/f2d756de-8697-40ae-8229-f32dc253974e/riverside_curtis__todd_hancock_...___dec_02_2025_001_rec_new_episode_rec_1.mp3?dest-id=3695967', 1554, '2025-12-10 11:30:00'::timestamptz, 46000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, '🎙️The Breath Connection for English Communication with Sam Murray | Real English Conversations Podcast for Global Professionals', 'In this episode of the Real English Conversations Podcast, host Curtis Davies speaks with Sam Murray , founder of The Breath Connection , a former British Royal Marine Commando , and an expert in breath retraining, nervous system regulation, trauma recovery, and stress resilience. After years of struggling with alcohol & drug addiction, chronic fatigue, anxiety, panic symptoms, poor sleep, and energy crashes, Sam discovered that dysfunctional breathing was at the core of his entire health cycle. By retraining his breath, he transformed his body, his mind, and his life — and now he teaches othe', 'https://dts.podtrac.com/redirect.mp3/pscrb.fm/rss/p/traffic.libsyn.com/secure/f2d756de-8697-40ae-8229-f32dc253974e/riverside_sam_murray__curtis_da...___nov_26_2025_001_rec_new_episode_rec.mp3?dest-id=3695967', 2316, '2025-12-03 11:30:00'::timestamptz, 47000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, '🎙️Canadian English Radio, Rock Music &amp; 35 Years In Broadcasting with Darren "Danger" Grieve | Real English Conversations Podcast for Global Professionals', 'In this episode of the Real English Conversations Podcast, host Curtis Davies sits down with Darren "Danger" Grieve , a 35-year, multi-award-winning broadcasting professional and one of Vancouver''s most recognizable radio personalities. Darren built a long and successful career across some of Canada''s biggest stations — Sonic Radio 104.9 FM, 96.9 Jack FM, City News 1130, 99.3 The Fox & XFM among others— He became a name known for his voice, Music knoweldge, his on-air presence, and his unforgettable interviews with some of the biggest names in Rock music and entertainment. Winner of Best Eveni', 'https://dts.podtrac.com/redirect.mp3/pscrb.fm/rss/p/traffic.libsyn.com/secure/f2d756de-8697-40ae-8229-f32dc253974e/riverside_riverside_danger__cur...___nov_26_2025_003_rec_new_episode_rec.mp3?dest-id=3695967', 2705, '2025-11-26 11:30:00'::timestamptz, 48000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, '🎙️Real Business English Communication Tips with The Sales Doctor Bob Phibbs | Real English Conversations Podcast for Global Professionals', 'In this powerful episode of the Real English Conversations Podcast, host Curtis Davies sits down with Bob Phibbs — The Retail Doctor® , one of the world''s most recognized retail strategists, communication experts, and global keynote speakers. Bob has trained more than 250,000 sales professionals worldwide , helped global brands like LEGO, Brother, and Seiko , and is the creator of SalesRX , the leading online sales training platform. His work has been featured in The New York Times, Wall Street Journal, PBS, ABC, FOX , and he hosts Tell Me Something Good About Retail , the top podcast for reta', 'https://dts.podtrac.com/redirect.mp3/pscrb.fm/rss/p/traffic.libsyn.com/secure/f2d756de-8697-40ae-8229-f32dc253974e/riverside_riverside_bob_phibbs_...___nov_16_2025_001_rec_new_episode_rec.mp3?dest-id=3695967', 2269, '2025-11-19 11:30:00'::timestamptz, 49000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, '🎙️The Business English Reset Button with Nick Shelton | Real English Conversations Podcast for Global Professionals', 'In this episode of the Real English Conversations Podcast , host Curtis Davies talks with Nick Shelton, bestselling author, TEDx international speaker, and creator of The Reset Button , a six-phase reinvention framework for people navigating life transitions and rediscovering purpose. Nick''s journey is one of transformation, courage, and quiet strength. After serving in the U.S. Air Force and building a successful career in the oil and gas industry, he retired at 49, only to discover that freedom without purpose can feel like a slow collapse. That realization sparked a personal reset that led ', 'https://dts.podtrac.com/redirect.mp3/pscrb.fm/rss/p/traffic.libsyn.com/secure/f2d756de-8697-40ae-8229-f32dc253974e/riverside_curtis_davie__nick_sh...___nov_02_2025_001_rec_new_episode_rec.mp3?dest-id=3695967', 1965, '2025-11-05 11:30:00'::timestamptz, 50000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, '🎙️Confident, Authentic &amp; Clear Business English Communication with Arias WebsterBerry | Real English Conversations Podcast for Global Professionals', 'In this episode of the Real English Conversations Podcast , host Curtis Davies sits down with Arias WebsterBerry, founder of WebsterBerry Marketing , Launch Ignition AI , and author, coach, and speaker who has helped entrepreneurs and teams generate over $112 million in revenue by mastering one skill: clear, human-centered communication . Arias teaches professionals and business leaders how to craft powerful stories, convey their message effectively, and utilize AI without compromising authenticity . His frameworks have helped international teams turn confusion into clarity and fear into confi', 'https://dts.podtrac.com/redirect.mp3/pscrb.fm/rss/p/traffic.libsyn.com/secure/f2d756de-8697-40ae-8229-f32dc253974e/riverside_arias_websterberry__c...___oct_28_2025_001_rec_new_episode_rec.mp3?dest-id=3695967', 1489, '2025-10-29 14:55:00'::timestamptz, 51000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, '🎙️Detrimental Kindness for Business English with Jason Johnson | Real English Conversations Podcast for Global Professionals', 'In this week''s episode of the Real English Conversations Podcast , host Curtis Davies sits down with Jason Johnson , Emotional Freedom & Transformation Coach and author of Detrimental Kindness: How Not to Lose Yourself While Helping Others . Jason helps people break free from over-giving, people-pleasing, and self-abandonment disguised as kindness . His work is about reclaiming boundaries, rediscovering your voice, and learning to live with confidence and emotional truth, not guilt or fear. Through his powerful message and lived experience, Jason shares how to stop betraying yourself in the na', 'https://dts.podtrac.com/redirect.mp3/pscrb.fm/rss/p/traffic.libsyn.com/secure/f2d756de-8697-40ae-8229-f32dc253974e/riverside_jason_johnson__curtis...___oct_16_2025_001_rec_new_episode_rec.mp3?dest-id=3695967', 1635, '2025-10-22 10:30:00'::timestamptz, 52000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, '🎙️The Say Yes Experience for Business English with Jessica Rector | Real English Conversations Podcast for Global Professionals', 'In this week''s episode of the Real English Conversations Podcast , host Curtis Davies sits down with Jessica Rector , MBA, keynote speaker, author, and co-founder of The Say Yes Experience, to explore how self-awareness, boundaries, and authentic communication can transform your personal and professional life. Jessica has empowered thousands of leaders and teams to reconnect with their confidence, purpose, and communication power. Through her dynamic speaking and coaching, she helps people lead with intention, protect their energy, and create positive momentum at work and beyond. ✨ In this epi', 'https://dts.podtrac.com/redirect.mp3/pscrb.fm/rss/p/traffic.libsyn.com/secure/f2d756de-8697-40ae-8229-f32dc253974e/riverside_jessica_rector__curti...___oct_12_2025_001_rec_new_episode_rec.mp3?dest-id=3695967', 2126, '2025-10-15 10:30:00'::timestamptz, 53000);
