  VALUES (v_pod_id, '🎙️The Real English Conversations Podcast For Business English 2026 | Real English Conversations Podcast For Global Professionals', 'In this special solo episode, host Curtis Davies, the founder of The Real English Conversations Podcast, opens up about the next chapter for the show and how you can be part of it. For years, this podcast has helped global professionals find their voice in English — not through grammar drills, but through real communication, mindset, and confidence. Now, Curtis is taking that mission one step further by launching the Real English Conversations Patreon community. If this podcast has ever helped you — inspired you to speak up, improved your fluency, or made you feel more confident in your profes', 'https://dts.podtrac.com/redirect.mp3/pscrb.fm/rss/p/traffic.libsyn.com/secure/f2d756de-8697-40ae-8229-f32dc253974e/riverside_elevenlabs_2025_10_10t...___oct_10_2025_001_rec_new_episode_rec.mp3?dest-id=3695967', 358, '2025-10-10 04:39:00'::timestamptz, 54000);
