DO $$
DECLARE
  v_host_id uuid;
  v_pod_id uuid;
  v_cat uuid;
BEGIN
  SELECT id INTO v_cat FROM categories WHERE name_ar = 'المال والاستثمار' LIMIT 1;
  INSERT INTO hosts (name_ar, slug, photo_url, cover_url, title_ar, specialty_ar, bio_ar, country, category_id, is_verified, followers_count)
  VALUES ('The Investor''s Podcast Network', 'the-investor-s-podcast-we-study-billionaires-the-investor-s-podcast-network', 'https://is1-ssl.mzstatic.com/image/thumb/Podcasts211/v4/f7/8b/ab/f78bab41-ca54-ff6c-b351-8d60f13500bb/mza_7509818263305350160.jpg/600x600bb.jpg', 'https://is1-ssl.mzstatic.com/image/thumb/Podcasts211/v4/f7/8b/ab/f78bab41-ca54-ff6c-b351-8d60f13500bb/mza_7509818263305350160.jpg/600x600bb.jpg', 'مقدم', 'المال والاستثمار', 'بودكاست حقيقي: The Investor''s Podcast (We Study Billionaires) - The Investor’s Podcast Network', 'أونلاين', v_cat, true, 50000)
  RETURNING id INTO v_host_id;

  INSERT INTO podcasts (title, description, host_id, category_id, type, cover_url, audience_level, plays_count, rating_avg)
  VALUES ('The Investor''s Podcast (We Study Billionaires) - The Investor’s Podcast Network', 'Hosted by Stig Brodersen, William Green, Shawn O''Malley, Daniel Mahncke, and Kyle Grieve, The Investor’s Podcast has proudly reached nearly 200 million downloads, as the world''s largest stock-investing focused podcast. On the show, we study a range of businesses and their investment prospects, from Spotify to Amazon, serial acquirers like Constellation Software, deep value plays, and more, using lessons from some of the world''s most famous investors, like Warren Buffett, Charlie Munger, and Howard Marks.&amp;nbsp; Leverage the lessons we learned from studying, and talking to, the world''s best ', v_host_id, v_cat, 'professional', 'https://is1-ssl.mzstatic.com/image/thumb/Podcasts211/v4/f7/8b/ab/f78bab41-ca54-ff6c-b351-8d60f13500bb/mza_7509818263305350160.jpg/600x600bb.jpg', 'beginner', 100000, 4.7)
  RETURNING id INTO v_pod_id;

  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'TIP862: Apple (AAPL): Is Apple Priced for a Massive Drawdown? w/ Daniel Mahncke &amp; Shawn O''Malley', 'Daniel Mahncke and Shawn O’Malley take on Apple (NASDAQ: AAPL). In 2025, Apple was widely seen as the company that missed AI. Since then, it has become the best-performing Mag7 stock and reclaimed the title of the most valuable company in the world. Apple just closed a record fiscal year, with revenue up 15% to $479 billion on the strongest iPhone cycle in years. It spends about $13 billion a year on capex, while Amazon, Microsoft, Alphabet and Meta are spending around $600 billion between them this year. The stock now trades at close to 40 times earnings, against roughly 12 times a decade ago', 'https://www.podtrac.com/pts/redirect.mp3/pdst.fm/e/pscrb.fm/rss/p/traffic.megaphone.fm/PPLLC5853946094.mp3', 4638, '2026-11-19 01:00:00'::timestamptz, 5000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'TIP861: Reddit (RDDT): Record Cash Flow, Collapsing Share Price w/ Kyle Grieve &amp; Shawn O''Malley', 'In today’s episode, Kyle Grieve and Shawn O’Malley revisit Reddit, a stock Shawn first pitched about a year and a half ago that has now given back nearly all of its gains after a one-day drop of roughly 25%. They’ll explain how Reddit makes money, why logged-in American users are worth far more than drive-by visitors from Google, and how Google’s AI answers turned Reddit’s biggest source of traffic into its biggest risk. Along the way, they look at Reddit’s network effects, its returns on capital, stock-based compensation and buybacks, Steve Huffman’s record as CEO, the move to a logged-in-onl', 'https://www.podtrac.com/pts/redirect.mp3/pdst.fm/e/pscrb.fm/rss/p/traffic.megaphone.fm/PPLLC3301804361.mp3', 4019, '2026-11-15 01:00:00'::timestamptz, 6000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'TIP860: Canadian Pacific Kansas City Limited (CP.TO): Irreplaceable Moat, Unproven Compounding w/ Kyle Grieve &amp; Shawn O''Malley', 'In today’s episode, Kyle Grieve and Shawn O’Malley discuss Canadian Pacific Kansas City, the only railroad that connects Canada, the United States, and Mexico on a single network. They trace how the company helped shape Canada, how an activist investor and a legendary railroader turned it into one of North America’s best-run railroads, and why a transformational merger has made its recent results much harder to judge. Along the way, they look at the barriers to replicating a railroad, management’s compensation program, the risks facing the business, and the company’s current intrinsic value. I', 'https://www.podtrac.com/pts/redirect.mp3/pdst.fm/e/pscrb.fm/rss/p/traffic.megaphone.fm/PPLLC6108688084.mp3', 4725, '2026-11-12 01:00:00'::timestamptz, 7000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'TIP859: Mercado Libre ($MELI): We Doubled Down on Meli w/ Daniel Mahncke &amp; Shawn O''Malley', 'Daniel Mahncke and Shawn O’Malley return to Mercado Libre (NASDAQ: MELI), a holding in The Intrinsic Value Portfolio. The “Amazon of Latin America” just reported its 31st consecutive quarter of revenue growth above 30%, a streak no company of its size has ever matched, with revenue up 45% to $10.75 billion. In the same quarter, its operating margin fell to 6.3%, the lowest in years, and the stock trades below where it was originally pitched. Daniel and Shawn cover the evolution of Mercado Pago, which processed $109 billion in payments last quarter, more than four times what the marketplace sol', 'https://www.podtrac.com/pts/redirect.mp3/pdst.fm/e/pscrb.fm/rss/p/traffic.megaphone.fm/PPLLC7783428823.mp3', 3849, '2026-11-08 01:06:00'::timestamptz, 8000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'TIP858: McDonald''s ($MCD): Generational Compounder in Historical Drawdown w/ Daniel Mahncke &amp; Shawn O''Malley', 'Daniel Mahncke and Shawn O’Malley cover their first restaurant stock. Although one could argue it isn’t really a restaurant business at all. McDonald’s (NYSE: MCD) is the landlord behind $139 billion of yearly sales across roughly 46,000 restaurants. About 95% of those restaurants are run by franchisees, who paid McDonald’s around $10.4 billion in rent and $6 billion in royalties last year. That means about 91% of McDonald’s restaurant-level profit comes from collecting rent and royalties, not from selling burgers.&amp;nbsp; Daniel and Shawn explain how Ray Kroc took over McDonald’s and came u', 'https://www.podtrac.com/pts/redirect.mp3/pdst.fm/e/pscrb.fm/rss/p/traffic.megaphone.fm/PPLLC8444798174.mp3', 4950, '2026-11-05 01:00:00'::timestamptz, 9000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'TIP857: S&amp;P Global, Novo, Deckers Brands w/ Stig Brodersen, Tobias Carlisle, &amp; Hari Ramachandra', 'In today’s episode, Stig Brodersen is joined by Tobias Carlisle and Hari Ramachandra for a new round of stock pitches. Hari makes the case for Novo, until recently the most valuable company in Europe, now priced as if its obesity franchise is a melting ice cube. Stig pitches S&amp;P Global, the company behind the S&amp;P 500 and one of the world’s great ratings businesses, and explains why it became his first new position in more than a year. Tobias breaks down Deckers Brands, the owner of HOKA and UGG, trading at 11 times earnings and buying back stock aggressively. IN THIS EPISODE YOU’LL LEA', 'https://www.podtrac.com/pts/redirect.mp3/pdst.fm/e/pscrb.fm/rss/p/traffic.megaphone.fm/PPLLC9584730002.mp3', 5258, '2026-11-01 00:00:00'::timestamptz, 10000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'TIP856: Airbnb (ABNB): The Business Outgrew Its Peak, The Stock Hasn''t w/ Kyle Grieve &amp; Shawn O''Malley', 'In today’s episode, Kyle Grieve and Shawn O’Malley discuss whether Airbnb’s recent slowdown was a warning sign or just building the groundwork for its next growth phase. They explore how a company that owns no homes built one of travel’s strongest brands, and why AI agents could threaten or strengthen it. You’ll also learn how Brian Chesky’s founder-led approach and new growth levers are shaping the business’s future. IN THIS EPISODE YOU’LL LEARN: (00:00:00) Intro (00:11:30) Why Airbnb barely noticed when it shut off advertising (00:17:08) What really caused Airbnb’s growth and cash flow slowd', 'https://www.podtrac.com/pts/redirect.mp3/pdst.fm/e/pscrb.fm/rss/p/traffic.megaphone.fm/PPLLC4938822257.mp3', 5165, '2026-10-29 00:00:00'::timestamptz, 11000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'TIP855: Shopify (SHOP): The Big Winner of Agentic Commerce? w/ Shawn O''Malley &amp; Daniel Mahncke', 'Shawn O’Malley and Daniel Mahncke revisit Shopify (NASDAQ: SHOP) fifteen months after Shawn pitched it, called it one of the best businesses they’d ever studied, and recommended passing on the stock at around $80 per share. Since then, the stock has nearly doubled, gross merchandise volume has grown more than 30% for five straight quarters, 2025 revenue rose 30% to over $11.5 billion, and Shopify paid off its convertible notes and launched its first-ever buyback program, now totaling $5 billion. Shawn and Daniel grade their original analysis: what they got right about the business, what they g', 'https://www.podtrac.com/pts/redirect.mp3/pdst.fm/e/pscrb.fm/rss/p/traffic.megaphone.fm/PPLLC2359056543.mp3', 4727, '2026-10-25 00:00:00'::timestamptz, 12000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'TIP854: GE Aerospace: Chris Hohn’s Biggest Bet w/ Daniel Mahncke &amp; Shawn O''Malley', 'Daniel Mahncke and Shawn O’Malley follow up last year’s TransDigm pitch with the biggest monopoly in aviation: GE Aerospace (NYSE: GE), the engine maker behind nearly three out of every four commercial flights in the world. With roughly 50,000 commercial and 30,000 military engines in service, GE has the largest installed engine base worldwide. That’s the reason Chris Hohn bets about 30% of his $50+ billion portfolio on it. Daniel and Shawn dig into the mechanism behind how GE sells its engines at roughly zero margin because every engine comes back as three and a half times its sale price in s', 'https://www.podtrac.com/pts/redirect.mp3/pdst.fm/e/pscrb.fm/rss/p/traffic.megaphone.fm/PPLLC7350732955.mp3', 4337, '2026-10-22 00:00:00'::timestamptz, 13000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'RWH074: True Wealth w/ Matt Ludmer', 'In this episode, William Green speaks with Matt Ludmer, the founder &amp; CEO of Aligned Wealth Management. Matt is a financial adviser to wealthy individuals &amp; families, including clients who have entrusted him with tens or even hundreds of millions of dollars. After decades working on Wall Street, he came to realize he’d misunderstood the meaning of wealth. That revelation led him to write a new book, “The Right Mountain: Practical Wisdom for Achieving True Wealth.” Here, he explores how to build a fulfilling life that includes—&amp; transcends—financial success. IN THIS EPISODE YOU’LL L', 'https://www.podtrac.com/pts/redirect.mp3/pdst.fm/e/pscrb.fm/rss/p/traffic.megaphone.fm/PPLLC8782502974.mp3', 9196, '2026-10-18 00:00:00'::timestamptz, 14000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'TIP853: Aritzia (ATZ.TO): The Women''s Apparel Brand Conquering the US, plus Nike, Lulu, and More w/ Kyle Grieve &amp; Shawn O''Malley', 'In today''s episode, Kyle Grieve and Shawn O’Malley discuss Aritzia, the everyday luxury fashion brand that has become one of retail''s most impressive compounders. They explore how a small boutique in the corner of a department store grew into a brand with exceptional store-based economics, a spotless balance sheet, and a huge untapped opportunity across America. With the stock falling even as the business posts some of its best growth ever, they debate whether this is a rare chance to own a durable compounder or a hot brand nearing its peak. IN THIS EPISODE YOU’LL LEARN: (00:00:00) Intro (00:0', 'https://www.podtrac.com/pts/redirect.mp3/pdst.fm/e/pscrb.fm/rss/p/traffic.megaphone.fm/PPLLC8948298638.mp3', 5008, '2026-10-15 00:00:00'::timestamptz, 15000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'RWH073: Unstoppable w/ Sir Michael Moritz', 'In this episode, William Green speaks with multibillionaire Sir Michael Moritz, arguably the most successful venture capitalist ever. He spent nearly four decades at Sequoia Capital, which invested in early-stage companies like Nvidia, Google, YouTube, PayPal, Airbnb, LinkedIn &amp; Stripe. Here, he talks about his unconventional path to success, the role of temperament in investing, &amp; what he learned from observing Steve Jobs, Bill Gates, Jensen Huang &amp; Elon Musk. IN THIS EPISODE YOU’LL LEARN: (00:00:00) Intro (00:04:50) Why Michael Moritz has always felt like an outsider. (00:14:05) ', 'https://www.podtrac.com/pts/redirect.mp3/pdst.fm/e/pscrb.fm/rss/p/traffic.megaphone.fm/PPLLC9272992158.mp3', 5296, '2026-10-11 00:00:00'::timestamptz, 16000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'TIP852: Hermès and LVMH Stock: Time to Buy Luxury? w/ Daniel Mahncke &amp; Shawn O''Malley', 'Daniel Mahncke and Shawn O’Malley revisit the two luxury houses they passed on last time — Hermès (EPA: RMS), the 189-year-old maker of the Birkin bag, and LVMH (EPA: MC), the 75-brand conglomerate behind Louis Vuitton, Dior, Tiffany, and Hennessy. Both stocks now sit near their lows: Hermès is down more than 50% from its February 2025 peak and trades at 32 times earnings for the first time in a decade, while LVMH has fallen to a five-year low after two straight years of declining sales — something that didn’t even happen in 2009. The luxury industry has lost roughly 70 million customers since', 'https://www.podtrac.com/pts/redirect.mp3/pdst.fm/e/pscrb.fm/rss/p/traffic.megaphone.fm/PPLLC1967876268.mp3', 4548, '2026-10-08 00:00:00'::timestamptz, 17000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'TIP851: HEICO Vs. TransDigm: Whose Aerospace Monopoly Is Better? w/ Kyle Grieve &amp; Shawn O''Malley', 'In today’s episode, Kyle Grieve and Shawn O’Malley discuss HEICO and TransDigm, two dominant players in the aerospace components industry known for their pricing power and resiliency. They’ll compare how each company grows through acquisitions and organic expansion, how they approach debt and capital allocation, and what gives each business its durable competitive advantages. The discussion also covers the risks facing both companies, including regulatory scrutiny and reliance on continued aerospace demand, as well as potential sources of future growth. IN THIS EPISODE YOU’LL LEARN: (00:00:00)', 'https://www.podtrac.com/pts/redirect.mp3/pdst.fm/e/pscrb.fm/rss/p/traffic.megaphone.fm/PPLLC4575291873.mp3', 4650, '2026-10-04 00:00:00'::timestamptz, 18000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'TIP850: Walmart (WMT): From Discount Retailer to eCommerce Powerhouse w/ Kyle Grieve &amp; Shawn O''Malley', 'In today’s episode, Kyle Grieve and Shawn O’Malley discuss Walmart and how it grew from Sam Walton’s small-town five-and-dime into a retail giant. Today, it also makes money from e-commerce, a marketplace, advertising and memberships. They cover the scale advantages behind Walmart’s everyday low prices, how its suppliers end up financing its inventory, and why its power over those suppliers continues to draw antitrust scrutiny. They also look at Walmart’s capital allocation, management, growth levers and the biggest risks facing the business. IN THIS EPISODE YOU’LL LEARN: (00:00:00) Intro (00:', 'https://www.podtrac.com/pts/redirect.mp3/pdst.fm/e/pscrb.fm/rss/p/traffic.megaphone.fm/PPLLC8078977187.mp3', 4587, '2026-10-01 00:00:00'::timestamptz, 19000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'TIP849: Average Returns Can Still Make You Wealthy w/ David Fagan', 'In this episode, Stig Brodersen speaks with David Fagan about Total Wealth Performance and why someone with average investment returns can still build a meaningful net worth. They discuss why saving is the first step in wealth creation, why financial independence is a matter of intention rather than luck, and how idle cash quietly becomes one of the most expensive decisions investors ever make. IN THIS EPISODE YOU’LL LEARN: (00:00:00) Intro (00:04:20) Why David has been a saver ever since he blew his entire net worth on a Hot Wheels racetrack at age eight (00:12:34) Why money decisions that lo', 'https://www.podtrac.com/pts/redirect.mp3/pdst.fm/e/pscrb.fm/rss/p/traffic.megaphone.fm/PPLLC1122315138.mp3', 4287, '2026-09-27 00:00:00'::timestamptz, 20000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'TIP848: Meta (META): What the Market Misses? w/ Daniel Mahncke &amp; Shawn O''Malley', 'Daniel Mahncke and Shawn O’Malley revisit Meta Platforms (NASDAQ: META), the advertising machine behind Facebook, Instagram, and WhatsApp that reaches 3.6 billion people every day — over 40% of the world’s population — and just grew ad revenue 27% to a nearly $240 billion annual run rate. Yet the stock trades more than 20% below its highs, because the money is going out even faster than it’s coming in: operating margins fell from 43% to 31% in a single year, quarterly free cash flow collapsed from $8.5 billion to $784 million, and capex guidance now sits at $130–145 billion this year — with an', 'https://www.podtrac.com/pts/redirect.mp3/pdst.fm/e/pscrb.fm/rss/p/traffic.megaphone.fm/PPLLC8255479800.mp3', 5186, '2026-09-24 00:00:00'::timestamptz, 21000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'RWH072: The Making of A Money Master w/ Rob Vinall', 'In this episode, William Green speaks with Rob Vinall, an English hedge fund manager with a terrific track record. Since launching his Business Owner Fund in 2008, he’s racked up stellar annualized returns of 15.5%. Rob almost never gives interviews but speaks in depth here about the principles &amp; practices that have driven his success in the 20 years since he founded his firm, RV Capital—not least, his habit of betting on CEOs who view their business as their life’s work. IN THIS EPISODE YOU’LL LEARN: (00:00:00) Intro (00:03:54) How Rob Vinall vaulted himself out of humble circumstances (0', 'https://www.podtrac.com/pts/redirect.mp3/pdst.fm/e/pscrb.fm/rss/p/traffic.megaphone.fm/PPLLC4291199861.mp3', 6492, '2026-09-20 00:00:00'::timestamptz, 22000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'TIP847: Alphabet (GOOGL): The Megacap That Still Might Be Underrated w/ Kyle Grieve &amp; Shawn O’Malley', 'In today’s episode, Kyle Grieve and Shawn O’Malley revisit Alphabet nearly two years after Shawn’s original pitch, tracing how the company transformed from a cash-rich, buyback-driven business into an aggressive spender on AI infrastructure. They walk through what changed across Search, YouTube, Cloud, and Waymo, and unpack why the market’s fears around AI disrupting Google were largely unfounded. Along the way, they dig into how Alphabet is funding its buildout, what that means for shareholders, and which questions will determine whether this evolved version of the business is actually better', 'https://www.podtrac.com/pts/redirect.mp3/pdst.fm/e/pscrb.fm/rss/p/traffic.megaphone.fm/PPLLC5795979126.mp3', 4768, '2026-09-17 00:00:00'::timestamptz, 23000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'TIP846: Stock Picker: How to Live Off Your Portfolio w/ Ian Cassel', 'In this episode, Stig Brodersen welcomes back Ian Cassel, founder of MicroCapClub and CIO of Intelligent Fanatics Capital Management, to discuss his new book, Stock Picker. They dig into why most microcaps must be sold within 36 months, why Ian never holds a large cash position, and how he arrived at the $2 million that let him live off his portfolio. IN THIS EPISODE YOU’LL LEARN: (00:00:00) Intro (00:12:24) Why Ian''s first big win at 16 shaped his risk tolerance for life. (00:24:48) How Ian arrived at the $2 million he needed to become a full-time private investor, and why the number was abou', 'https://www.podtrac.com/pts/redirect.mp3/pdst.fm/e/pscrb.fm/rss/p/traffic.megaphone.fm/PPLLC6933946523.mp3', 4508, '2026-09-13 00:00:00'::timestamptz, 24000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'TIP845: Copart Stock (CPRT): Is Copart Now a Buy? w/ Daniel Mahncke &amp; Shawn O''Malley', 'Daniel Mahncke and Shawn O’Malley revisit Copart (NASDAQ: CPRT), the online salvage auction giant that turns totaled cars into a global marketplace, connecting insurers with more than a million buyers across 190 countries. Copart owns over 250 salvage yards outright — land that’s increasingly difficult to permit today — and compounded earnings per share at over 20% a year for a decade. But the stock is down more than 40% from its highs, U.S. insurance volumes have fallen for four straight quarters, and its main competitor, IAA, has now outgrown Copart for six straight quarters. Daniel and Shaw', 'https://www.podtrac.com/pts/redirect.mp3/pdst.fm/e/pscrb.fm/rss/p/traffic.megaphone.fm/PPLLC4029790556.mp3', 4153, '2026-09-10 00:00:00'::timestamptz, 25000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'TIP844: Uber (UBER): The Autonomy Referendum — Is Mr. Market Completely Wrong? w/ Daniel Mahncke &amp; Shawn O’Malley', 'Shawn O’Malley and Daniel Mahncke revisit Uber (NYSE: UBER), one of the largest holdings in The Intrinsic Value Portfolio, fifteen months after they first pitched it. In that time, Uber’s operating profits have roughly doubled, free cash flow has climbed to about $10 billion a year, gross bookings are compounding around 20% annually, and the board authorized a new $20 billion buyback. And yet the stock is flat, with its multiple of operating profits cut from 55 times down to roughly 22 times. Shawn and Daniel discuss why the market is pricing Uber as though autonomy ends the story — Waymo rais', 'https://www.podtrac.com/pts/redirect.mp3/pdst.fm/e/pscrb.fm/rss/p/traffic.megaphone.fm/PPLLC5483990906.mp3', 4011, '2026-09-06 00:00:00'::timestamptz, 26000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'TIP843: AppLovin (APP): The 30-Bagger Down More Than Half w/ Kyle Grieve &amp; Shawn O''Malley', 'In today’s episode, Kyle Grieve and Shawn O’Malley break down AppLovin, the mobile advertising platform that went from a failed app recommendation tool to one of the most profitable businesses in ad tech. They walk through how the company makes money on both sides of the ad exchange, why its data advantage has been so hard for competitors to copy, and what caused the market to turn on the stock so violently after a relatively strong quarter. Along the way, they dig into the founder’s track record, the buyback program that made early shareholders rich, and whether the growth story still has roo', 'https://www.podtrac.com/pts/redirect.mp3/pdst.fm/e/pscrb.fm/rss/p/traffic.megaphone.fm/PPLLC3269112983.mp3', 5414, '2026-09-03 00:00:00'::timestamptz, 27000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'TIP842: Comfort Systems USA (FIX): The Five-Bagger We Passed On w/ Kyle Grieve &amp; Shawn O''Malley', 'In today''s episode, Kyle Grieve and Shawn O’Malley revisit Comfort Systems USA, a business Shawn originally passed on at $320 that has since appreciated fivefold due to explosive data center spending. The company shattered original projections, with accelerating organic growth, expanding margins, and exceptional capital efficiency. Despite acknowledging the business quality, the hosts discussed whether the original decision reflected a flawed investment process or was the natural outcome of applying a strict investment framework. IN THIS EPISODE YOU’LL LEARN: (00:00:00) Intro (00:09:16) How AI', 'https://www.podtrac.com/pts/redirect.mp3/pdst.fm/e/pscrb.fm/rss/p/traffic.megaphone.fm/PPLLC8691360905.mp3', 4748, '2026-08-30 00:00:00'::timestamptz, 28000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'TIP841: Palantir – Palantir is Cheaper than I Thought! w/ Daniel Mahncke &amp; Shawn O’Malley', 'Daniel Mahncke and Shawn O’Malley take a deep dive into Palantir (NASDAQ: PLTR), the data and AI platform behind everything from battlefield targeting systems to Airbus’s A350 production line, with customers including the U.S. Army, the NHS, Ferrari, and Airbus. Palantir is growing revenue at over 90%, with net dollar retention at 157% and adjusted operating margins above 60% — a Rule of 40 score of 155%, roughly double what the best software companies in the world achieve. It also trades at around 60 times sales, which is why The Economist called it possibly the most overvalued firm of all ti', 'https://www.podtrac.com/pts/redirect.mp3/pdst.fm/e/pscrb.fm/rss/p/traffic.megaphone.fm/PPLLC8215943310.mp3', 4471, '2026-08-27 00:00:00'::timestamptz, 29000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'TIP840: CATL: Powering EVs, Power Grids, and AI w/ Stig Brodersen, Manish Karira &amp; Ralph Summerford', 'In today’s episode, Stig Brodersen is joined by Manish Karira and Ralph Summerford for a bull and bear debate on CATL, the world’s largest battery maker. Manish presents the bull case, arguing that a company most listeners have never heard of is becoming the backbone of the global energy infrastructure, powering EVs, stabilizing power grids, and feeding AI data centers. Ralph, a forensic accountant, presents the bear case, digging into price deflation, geopolitical risk, and whether CATL’s US licensing model is capital-light growth or a defensive retreat. IN THIS EPISODE YOU’LL LEARN: (00:00:0', 'https://www.podtrac.com/pts/redirect.mp3/pdst.fm/e/pscrb.fm/rss/p/traffic.megaphone.fm/PPLLC2186210816.mp3', 4760, '2026-08-23 00:00:00'::timestamptz, 30000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'TIP839: Domino''s Pizza (DPZ): Is the Royalty Engine Still Running? w/ Kyle Grieve &amp; Shawn O’Malley', 'In today''s episode, Kyle Grieve and Shawn O’Malley analyze Domino''s Pizza, the world’s biggest pizza franchisor built on a royalty-driven, asset-light business model. They walk through Domino''s shift toward franchising and away from Company-owned stores, and what that means for the company''s future revenue mix and cash generation. Along the way, they dig into whether Domino''s royalty engine can keep running at the pace investors have come to expect. IN THIS EPISODE YOU’LL LEARN: (00:00:00) Intro (00:02:55) Reviewing the Domino''s royalty engine thesis (00:15:26) Why Domino''s has moved away from', 'https://www.podtrac.com/pts/redirect.mp3/pdst.fm/e/pscrb.fm/rss/p/traffic.megaphone.fm/PPLLC3077597190.mp3', 4535, '2026-08-20 00:00:00'::timestamptz, 31000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'TIP838: Google, Reddit, Amazon – Are Our Biggest Winners Still a Buy? w/ Daniel Mahncke &amp; Shawn O’Malley', 'After looking at companies that tanked in recent months in the last episode, Daniel Mahncke and Shawn O’Malley now take a look at the best-performing stocks of the pitches of the last two years. Google, Amazon, and Reddit are companies that generated great returns for the Intrinsic Value Portfolio, but there were also companies on the watchlist that turned into multibaggers in the past year. Daniel and Shawn discuss the patterns of the stocks that gained most in value, what one can learn from that, and how they think about selling and holding positions that went up past their fair value estima', 'https://www.podtrac.com/pts/redirect.mp3/pdst.fm/e/pscrb.fm/rss/p/traffic.megaphone.fm/PPLLC4099722059.mp3', 5227, '2026-08-16 00:00:00'::timestamptz, 32000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'TIP837: Adobe, Lululemon, PayPal – Are our Biggest Losers a Buy Now? w/ Daniel Mahncke &amp; Shawn O’Malley', 'Daniel Mahncke and Shawn O’Malley take a trip down memory lane and look back at the pitches of the last year and a half – especially the ones that didn’t work out as hoped. Many companies that were seen as best-in-class businesses not too long ago experienced massive drawdowns in the last year. Some of them were covered on this show, and others even made it into the portfolio.&amp;nbsp; Daniel and Shawn discuss the patterns of the stocks that lost most in value, what one can learn from that, and how the market shift towards AI changed how they invest. The companies discussed today are Adobe, L', 'https://www.podtrac.com/pts/redirect.mp3/pdst.fm/e/pscrb.fm/rss/p/traffic.megaphone.fm/PPLLC9399738707.mp3', 4702, '2026-08-13 00:00:00'::timestamptz, 33000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'RWH071: Risk, Ruin, Reinvention &amp; Resilience w/ Victor Haghani', 'In this episode, William Green speaks with Victor Haghani, founder &amp; CIO of Elm Wealth &amp; author of The Missing Billionaires: A Guide to Making Better Financial Decisions. Victor’s journey is among the most remarkable &amp; instructive in modern investment history. As one of the founders of Long-Term Capital Management, he experienced dazzling success &amp; devastating failure. Today, he oversees billions of dollars using a low-cost, diversified, index-driven strategy that reflects hard-won lessons about resilience, humility, simplicity &amp; risk management. IN THIS EPISODE YOU’LL LEAR', 'https://www.podtrac.com/pts/redirect.mp3/pdst.fm/e/pscrb.fm/rss/p/traffic.megaphone.fm/PPLLC1971340507.mp3', 7187, '2026-08-09 00:00:00'::timestamptz, 34000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'TIP836: Exor NV (EXO): The Massive Discount Continues To Widen w/ Kyle Grieve &amp; Shawn O’Malley', 'In today’s episode, Kyle Grieve and Shawn O’Malley analyze Exor, the Dutch holding company controlled by Italy’s Agnelli family and best known for its long-standing stake in Ferrari. They walk through Exor’s ownership of Ferrari, and what they like about Lingotto, Exor’s investing management company. Along the way, they dig into what could cause the current valuation gap to close or widen. IN THIS EPISODE YOU’LL LEARN: (00:00:00) Intro (00:03:08) Revisiting the Exor and Ferrari thesis (00:05:06) How Exor’s stock reacted since the original purchase (00:09:16) Why Ferrari’s stock has fallen desp', 'https://www.podtrac.com/pts/redirect.mp3/pdst.fm/e/pscrb.fm/rss/p/traffic.megaphone.fm/PPLLC6032286197.mp3', 5011, '2026-08-06 00:00:00'::timestamptz, 35000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'TIP835: Intuit (INTU): The S&amp;P 500''s Biggest Loser w/ Shawn O’Malley &amp; Kyle Grieve', 'Shawn O''Malley and Kyle Grieve explore Intuit (ticker: INTU). In this episode, you''ll learn what narratives have underpinned the company’s more than 60% selloff, as Intuit claims the undesirable title of “worst performer in the S&amp;P 500” this year. But is this a bargain price for a high-quality SaaS business, or a value trap? That’s the key question that Shawn &amp; Kyle discuss, plus so much more! IN THIS EPISODE YOU’LL LEARN: (00:00:00) Intro (00:03:48) How Intuit’s accounting software became so popular (00:12:49) What makes QuickBooks such a great business (00:20:54) Why Intuit is the wo', 'https://www.podtrac.com/pts/redirect.mp3/pdst.fm/e/pscrb.fm/rss/p/traffic.megaphone.fm/PPLLC8546307946.mp3', 4714, '2026-08-02 00:00:00'::timestamptz, 36000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'TIP834: DLocal (DLO): Multibagger Potential with Decade-Long Runway w/ Daniel Mahncke &amp; Shawn O’Malley', 'Daniel Mahncke and Shawn O’Malley take a deep dive into DLocal (NASDAQ: DLO), the first Uruguayan unicorn and the emerging markets payment provider for companies like Amazon, Uber, Spotify, Netflix, and many more. DLocal is trading at attractive multiples while growing payment volumes at over 70% and printing cash due to high operating leverage and a high-margin business model. That cash is given back to shareholders in the form of dividends and buybacks. Daniel and Shawn discuss whether the high customer concentration and the declining take rate justify the cheap valuation or whether the mark', 'https://www.podtrac.com/pts/redirect.mp3/pdst.fm/e/pscrb.fm/rss/p/traffic.megaphone.fm/PPLLC1427724401.mp3', 4935, '2026-07-30 00:00:00'::timestamptz, 37000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'RWH070: Hunting For Hidden Treasures w/ Christopher Begg', 'In this episode, William Green chats with Christopher Begg, a renowned hedge fund manager who is the CEO &amp; CIO of East Coast Asset Management. Chris is also an adjunct professor at Columbia Business School, where he teaches the prestigious Security Analysis course that Ben Graham taught to Warren Buffett in 1951. Here, Chris shares rich insights about Tesla, Alphabet, SpaceX, Constellation Software, &amp; the art of discovering great investments hidden in plain sight. IN THIS EPISODE YOU’LL LEARN: (00:00:00) Intro (00:03:30) How writing helps Chris Begg to “compress complexity into essence', 'https://www.podtrac.com/pts/redirect.mp3/pdst.fm/e/pscrb.fm/rss/p/traffic.megaphone.fm/PPLLC8825949163.mp3', 7294, '2026-07-26 00:00:00'::timestamptz, 38000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'TIP833: Perimeter Solutions (PRM): A Niche Monopoly, One Acquisition at a Time w/ Kyle Grieve &amp; Shawn O’Malley', 'In today’s episode, Kyle Grieve and Shawn O’Malley analyze Perimeter Solutions, a niche industrial conglomerate built by Transdigm’s legendary founder Nick Howley using the same playbook that turned Transdigm into a multi-decade compounder. They break down how the company operates two very different segments, from wildfire retardants and airbase logistics to specialty chemicals and precision medical manufacturing equipment, each built around sticky, mission-critical customer relationships. They’ll also cover the company’s acquisition strategy, its unusual founder’s advisory fee, and the debt a', 'https://www.podtrac.com/pts/redirect.mp3/pdst.fm/e/pscrb.fm/rss/p/traffic.megaphone.fm/PPLLC7172045328.mp3', 4530, '2026-07-23 00:00:00'::timestamptz, 39000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'TIP832: Fairfax Financial (FFO.TO): The Berkshire Of The North w/ Kyle Grieve &amp; Shawn O''Malley', 'In today''s episode, Kyle Grieve and Shawn O’Malley analyze Fairfax Financial, the insurance conglomerate that Prem Watsa built from a near-bankrupt trucking insurer into a compounding machine often compared to Berkshire Hathaway. They break down Fairfax''s insurance and non-insurance segments, its use of float, and the capital allocation moves, from acquisitions to buybacks, that have driven decades of growth. The conversation also covers Fairfax''s competitive advantages, key risks such as catastrophe exposure and succession, and whether the business remains an attractive opportunity today. IN ', 'https://www.podtrac.com/pts/redirect.mp3/pdst.fm/e/pscrb.fm/rss/p/traffic.megaphone.fm/PPLLC7616517328.mp3', 3967, '2026-07-19 00:00:00'::timestamptz, 40000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'TIP831: Pinduoduo (PDD): Is PDD the Best Buy in China? w/ Daniel Mahncke and Shawn O''Malley', 'Daniel Mahncke and Shawn O''Malley take a deep dive into Pinduoduo (NASDAQ: PDD), the Chinese retail giant that has overtaken local competitors like Alibaba and JD.com and expanded internationally with Temu, which has become the most-downloaded e-commerce app in the world. They discuss how to think about the lack of disclosures and what the margin decline and growth deceleration mean for the business going forward. But also whether this presents an exceptional buying opportunity at a single-digit earnings multiple and about 60% of the company’s market capitalization in cash. IN THIS EPISODE YOU', 'https://www.podtrac.com/pts/redirect.mp3/pdst.fm/e/pscrb.fm/rss/p/traffic.megaphone.fm/PPLLC9024967447.mp3', 5225, '2026-07-16 00:00:00'::timestamptz, 41000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'TIP830: SpaceX (SPCX): Is It Really Worth $2 Trillion Dollars? w/ Kyle Grieve &amp; Shawn O''Malley', 'In today''s episode, Kyle Grieve and Shawn O’Malley analyze SpaceX''s blockbuster 2026 IPO, dissecting the company''s three segments: Space, Connectivity, and AI. They’ll also look at its history, moats, capital allocation, debt, and incentive structure. They’ll stress-test SpaceX''s aggressive $28.5 trillion total addressable market claim and walk through the key risks facing the business, from key-man dependence to regulatory exposure.&amp;nbsp; IN THIS EPISODE YOU’LL LEARN: (00:00:00) Intro(00:06:56) How Elon Musk''s early rocket failures almost sank SpaceX(00:08:36) How Space, Connectivity, and', 'https://www.podtrac.com/pts/redirect.mp3/pdst.fm/e/pscrb.fm/rss/p/traffic.megaphone.fm/PPLLC8692168972.mp3', 4401, '2026-07-12 00:00:00'::timestamptz, 42000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'TIP829: Kaspi Stock ($KSPI): The Cheapest E-Commerce Monopoly in the World w/ Daniel Mahncke and Shawn O''Malley', 'Daniel Mahncke and Shawn O''Malley take a deep dive into Kaspi.kz (NASDAQ: KSPI), the Kazakhstani super-app that combines payments, e-commerce, and fintech into a single platform that most of the country uses every day. They unpack why its dominance at home has been so hard for competitors to challenge, and how a company this profitable ends up trading at only around seven times earnings. IN THIS EPISODE YOU’LL LEARN: (00:00:00) Intro (00:01:49) How Kaspi became Kazakhstan''s No.1 superapp (00:16:56) What business units Kaspi operates (00:35:38) What role the fintech business plays (00:37:54) Ho', 'https://www.podtrac.com/pts/redirect.mp3/pdst.fm/e/pscrb.fm/rss/p/traffic.megaphone.fm/PPLLC9358121443.mp3', 5307, '2026-07-09 00:00:00'::timestamptz, 43000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'TIP828: Restoration Hardware (RH): Building a Luxury Empire From Scratch w/ Shawn O''Malley and Daniel Mahncke', 'Shawn O''Malley and Daniel Mahncke explore Restoration Hardware (ticker: RH). In this episode, you''ll learn how RH was able to reinvent itself as a high-end furniture retailer, using opulent galleries, high-end dining, private yachts, and a membership model based on Amazon Prime and Costco. RH is an incredibly bold and unique business, not afraid to use unconventional viral marketing efforts to drive customers into stores, as they aim to set styles for the ultra-rich. Shawn and Daniel dig into the business, risks for shareholders, and estimate RH’s intrinsic value, plus so much more! IN THIS EP', 'https://www.podtrac.com/pts/redirect.mp3/pdst.fm/e/pscrb.fm/rss/p/traffic.megaphone.fm/PPLLC7917044400.mp3', 4095, '2026-07-05 00:00:00'::timestamptz, 44000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'TIP827: Auto1 Stock (AG1): Is This the Amazon for Cars? w/ Daniel Mahncke &amp; Shawn O’Malley', 'Daniel Mahncke and Shawn O''Malley take a deep dive into Auto1 Group (ETR: AG1), the Berlin-based used-car platform. They examine whether Auto1''s instant-guaranteed-pricing model is a genuine consumer moat or a balance-sheet liability in disguise, what the economics actually look like in 2026 once you separate the merchant flywheel from the retail build-out, and the more uncomfortable side of the bull case. IN THIS EPISODE YOU’LL LEARN: (00:00:00) Intro (00:03:23) Why the traditional used-car market doesn’t work well (00:10:24) About the size of the used-car market (00:13:11) How Auto1’s busine', 'https://www.podtrac.com/pts/redirect.mp3/pdst.fm/e/pscrb.fm/rss/p/traffic.megaphone.fm/PPLLC9507416826.mp3', 4012, '2026-07-02 00:00:00'::timestamptz, 45000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'RWH069: The Psychology of Investing w/ Emily Haisley', 'In today’s episode, William Green speaks with Emily Haisley, who heads the Behavioral Finance team at BlackRock, the world’s largest asset manager, with $14 trillion under management. Here, she explores the critical intersection of investing &amp; psychology, explaining how she helps elite fund managers identify &amp; counteract their behavioral biases, regulate their emotions, optimize their physiological state, avoid systematic mistakes, &amp; take risks that align with their edge. This conversation offers powerful insights on how to win the inner game of investing. IN THIS EPISODE YOU’LL LE', 'https://www.podtrac.com/pts/redirect.mp3/pdst.fm/e/pscrb.fm/rss/p/traffic.megaphone.fm/PPLLC4474816891.mp3', 6963, '2026-06-28 00:00:00'::timestamptz, 46000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'TIP826: American Tower (AMT): The Wide Moat Business Your Phone Can''t Live Without w/ Kyle Grieve &amp; Shawn O''Malley', 'Kyle Grieve and Shawn O’Malley analyze American Tower, the global cell tower business that powers the wireless networks we rely on every day. They unpack how leasing tower space to carriers creates durable recurring revenue, why its stacked competitive advantages form one of the widest moats in the market, and how a steadily growing debt load complicates the picture. IN THIS EPISODE YOU’LL LEARN: (00:00:00) Intro (00:01:51) How American Tower powers the wireless networks we use (00:06:21) How AMT creates recurring revenue (00:08:09) Why adding additional tenants dramatically boosts profits per', 'https://www.podtrac.com/pts/redirect.mp3/pdst.fm/e/pscrb.fm/rss/p/traffic.megaphone.fm/PPLLC9559664629.mp3', 4360, '2026-06-25 00:00:00'::timestamptz, 47000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'TIP825: Meta, Adobe, Booking Holdings w/ Stig Brodersen, Tobias Carlisle &amp; Hari Ramachandra', 'In today’s episode, Stig Brodersen is joined by Tobias Carlisle and Hari Ramachandra for a new round of stock pitches. Hari makes the case for Meta as a leading AI-powered advertising platform. Tobias breaks down Booking Holdings and whether its travel moat can withstand the rise of AI assistants. Stig analyzes Adobe, exploring the durability of its creative software ecosystem amid rapid technological change. IN THIS EPISODE YOU’LL LEARN: (00:00:00) Intro(00:02:31) Why Hari is bullish on Meta (Ticker: META), highlighting its advertising dominance, network effects, and long-term monetization po', 'https://www.podtrac.com/pts/redirect.mp3/pdst.fm/e/pscrb.fm/rss/p/traffic.megaphone.fm/PPLLC3448186157.mp3', 3651, '2026-06-21 00:00:00'::timestamptz, 48000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'TIP824: Copa Holdings (CPA): Is Buffett Right About Airline Stocks? w/ Daniel Mahncke &amp; Shawn O’Malley', 'Daniel Mahncke and Shawn O''Malley take a deep dive into Copa Holdings — the Panama-based hub-and-spoke airline whose investment case now turns on two of the most debated questions in the stock today: whether Copa is a structural exception to the airline curse — protected by a geography no rival can copy and a cost base only a handful of carriers in the world can match — or whether even the best airline in the Americas eventually gets pulled into the same gravity that has destroyed value for nearly every other carrier. IN THIS EPISODE YOU’LL LEARN: (00:00:00) Intro (00:01:35) Why airlines are s', 'https://www.podtrac.com/pts/redirect.mp3/pdst.fm/e/pscrb.fm/rss/p/traffic.megaphone.fm/PPLLC8444223608.mp3', 5208, '2026-06-18 00:00:00'::timestamptz, 49000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'TIP823: From Railroads to AI: The Timeless Patterns Behind Market Bubbles w/ Kyle Grieve', 'Kyle Grieve discusses what bubbles are, why they form, and why they always feel different in real time. He’ll examine historical patterns through frameworks from Insana, Kindleberger, and Howard Marks, and explain how investors can protect themselves by focusing on intrinsic value over narratives rather than speculation. IN THIS EPISODE YOU’LL LEARN: (00:00:00) Intro (00:02:31) Why understanding bubbles is critical for long-term investor survival (00:04:31) How “this time is different” fuels every historical bubble (00:05:37) Why smart money, incentives, and career risk inflate bubbles (00:07:', 'https://www.podtrac.com/pts/redirect.mp3/pdst.fm/e/pscrb.fm/rss/p/traffic.megaphone.fm/PPLLC4861513935.mp3', 3962, '2026-06-14 00:00:00'::timestamptz, 50000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'TIP822: QXO (QXO): Can One of the World''s Best Consolidators Strike Lightning Again? w/ Kyle Grieve &amp; Shawn O''Malley', 'Kyle Grieve and Shawn O’Malley analyze QXO, the ambitious building-products distribution company led by serial industry consolidator Brad Jacobs, a man who has turned multiple boring industries into extraordinary wealth-creation machines throughout his career. Tune in as they debate whether Brad Jacobs'' unparalleled track record as a capital allocator is enough to justify investing in a business that is still very much a work in progress. IN THIS EPISODE YOU’LL LEARN: (00:00:00) Intro (00:02:03) How Brad Jacobs built multiple billion-dollar companies from scratch (00:05:49) The structure QXO u', 'https://www.podtrac.com/pts/redirect.mp3/pdst.fm/e/pscrb.fm/rss/p/traffic.megaphone.fm/PPLLC5724149332.mp3', 4814, '2026-06-11 00:00:00'::timestamptz, 51000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'TIP821: Grab Holdings (GRAB): Why Uber Surrendered Southeast Asia w/ Shawn O’Malley &amp; Daniel Mahncke', 'Shawn O''Malley and Daniel Mahncke explore Grab Holdings (ticker: GRAB). In this episode, you''ll learn how Grab was able to quickly grow across eight countries in Southeast Asia, and what local adaptations they made to outmaneuver Uber, which eventually ceded its entire market share to Grab.&amp;nbsp;&amp;nbsp; Despite Grab’s astronomical successes, the company’s stock is down 70% since IPO, and investors are wondering if perhaps now is finally a good entry point after the company reached its first full year of profitability. Shawn and Daniel discuss and estimate Grab’s intrinsic value, plus so', 'https://www.podtrac.com/pts/redirect.mp3/pdst.fm/e/pscrb.fm/rss/p/traffic.megaphone.fm/PPLLC2770169285.mp3', 4834, '2026-06-07 00:00:00'::timestamptz, 52000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'TIP820: WIX: The Most Asymmetric AI Bet? w/ Daniel Mahncke &amp; Shawn O’Malley', 'Daniel Mahncke and Shawn O''Malley take a deep dive into Wix.com — the Israeli website-building platform whose investment case now turns on two of the most debated questions in the stock today: whether the generative-AI wave that lets anyone spin up a site from a text prompt is the end of Wix or whether Wix is too sticky, and whether the Base 44 acquisition — Wix''s bet on AI-powered app generation — is the next leg of the story or a distraction from the SMB infrastructure business the company already dominates. IN THIS EPISODE YOU’LL LEARN: (00:00:00) Intro (00:01:32) How Wix was founded (00:21', 'https://www.podtrac.com/pts/redirect.mp3/pdst.fm/e/pscrb.fm/rss/p/traffic.megaphone.fm/PPLLC3649821963.mp3', 4414, '2026-06-04 00:00:00'::timestamptz, 53000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'TIP819: Lifco AB (LIFCO-B.ST): The Serial Acquirer Building an Unstoppable Compounding Engine w/ Kyle Grieve &amp; Shawn O''Malley', 'Kyle Grieve and Shawn O’Malley analyze LIFCO, one of the world''s leading industrial serial acquirers operating through three distinct divisions spanning dental supplies, demolition equipment, and niche systems solutions across Europe. IN THIS EPISODE YOU’LL LEARN: (00:00:00) Intro (00:01:39) The fascinating history of LIFCO (00:07:31) How Carl Bennett built the DNA that still guides LIFCO''s acquisition strategy today (00:09:24) Fredrik Karlsson''s legendary track record and why he bought more stock after being removed (00:11:16) The three distinct business segments and how they drive growth ind', 'https://www.podtrac.com/pts/redirect.mp3/pdst.fm/e/pscrb.fm/rss/p/traffic.megaphone.fm/PPLLC4553079365.mp3', 4928, '2026-05-31 00:00:00'::timestamptz, 54000);
END $$;

