-- ---------- MrBallen Podcast: Strange, Dark &amp; Mysterious Stories ----------
DO $$
DECLARE
  v_host_id uuid;
  v_pod_id uuid;
  v_cat uuid;
BEGIN
  SELECT id INTO v_cat FROM categories WHERE name_ar = 'ثقافة وأدب' LIMIT 1;
  INSERT INTO hosts (name_ar, slug, photo_url, cover_url, title_ar, specialty_ar, bio_ar, country, category_id, is_verified, followers_count)
  VALUES ('Ballen Studios', 'mrballen-podcast-strange-dark-mysterious-stories', 'https://is1-ssl.mzstatic.com/image/thumb/Podcasts211/v4/a5/9c/8a/a59c8a0a-0cb2-9862-e0d6-7b5ee4e9e157/mza_12554888833857337425.jpg/600x600bb.jpg', 'https://is1-ssl.mzstatic.com/image/thumb/Podcasts211/v4/a5/9c/8a/a59c8a0a-0cb2-9862-e0d6-7b5ee4e9e157/mza_12554888833857337425.jpg/600x600bb.jpg', 'مقدم', 'ثقافة وأدب', 'بودكاست حقيقي: MrBallen Podcast: Strange, Dark &amp; Mysterious Stories', 'أونلاين', v_cat, true, 50000)
  RETURNING id INTO v_host_id;

  INSERT INTO podcasts (title, description, host_id, category_id, type, cover_url, audience_level, plays_count, rating_avg)
  VALUES ('MrBallen Podcast: Strange, Dark &amp; Mysterious Stories', 'MrBallen Podcast: Strange, Dark and Mysterious Stories is a true crime and mystery podcast that presents strange, dark and mysterious content delivered in story format. The program is hosted by John Allen a.k.a. MrBallen. Subscribe to SiriusXM Podcasts+ to listen to new episodes 7-days early and ad-free. Start a free trial now on Apple Podcasts or by visiting siriusxm.com/podcastsplus.', v_host_id, v_cat, 'cultural', 'https://is1-ssl.mzstatic.com/image/thumb/Podcasts211/v4/a5/9c/8a/a59c8a0a-0cb2-9862-e0d6-7b5ee4e9e157/mza_12554888833857337425.jpg/600x600bb.jpg', 'beginner', 100000, 4.7)
  RETURNING id INTO v_pod_id;

  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Sai Kung Barrier', 'In South China, there is this 100 km long wilderness trail called the MacLehose Trail. And at first glance, it just seems like a pretty normal, beautiful hiking trail. That is, until you begin to research what other hikers have said about what they experienced out on that trail. Let’s just say... some of their experiences are genuinely terrifying. And today, I’m going to tell you one of those experiences. It’s about this man who goes solo hiking out on the MacLehose Trail, and he comes in contact with something that neither he nor anybody else can explain. Story name, preview &amp; link to ori', 'https://dts.podtrac.com/redirect.mp3/stitcher.simplecastaudio.com/814143cd-09c6-426f-920a-7be9b3dc1506/episodes/75274e2e-1ab4-4aca-9d6d-03e5765228b4/audio/128/default.mp3?aid=rss_feed&amp;awCollectionId=814143cd-09c6-426f-920a-7be9b3dc1506&amp;awEpisodeId=75274e2e-1ab4-4aca-9d6d-03e5765228b4&amp;feed=dloY8UYJ', 1463, '2026-11-19 08:00:00'::timestamptz, 5000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Masked Realities (PODCAST EXCLUSIVE EPISODE)', 'Today’s three stories demonstrate that sometimes reality is just not what it seems. &nbsp; You can WATCH all new &amp; exclusive MrBallen podcast episodes on my YouTube channel, just called "MrBallen" - https://www.youtube.com/c/MrBallen If you want to reach out to me, contact me on Instagram, Twitter or any other major social media platform, my username on all of them is @mrballen Hosted by Simplecast, an AdsWizz company. See pcm.adswizz.com for information about our collection and use of personal data for advertising.', 'https://dts.podtrac.com/redirect.mp3/stitcher.simplecastaudio.com/814143cd-09c6-426f-920a-7be9b3dc1506/episodes/00e90d44-7f15-4851-8fb6-b50f78055776/audio/128/default.mp3?aid=rss_feed&amp;awCollectionId=814143cd-09c6-426f-920a-7be9b3dc1506&amp;awEpisodeId=00e90d44-7f15-4851-8fb6-b50f78055776&amp;feed=dloY8UYJ', 2238, '2026-11-18 08:00:00'::timestamptz, 6000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'The Stylist (PODCAST EXCLUSIVE EPISODE)', 'One morning in 2005, a mechanic at a gas station near Spartanburg, South Carolina heard the bell on the front door of the shop jingle. And he looked up just as a young, blonde woman approached the counter. The woman asked for an oil change, and as one of his coworkers helped her, the mechanic just stared at her. Because something about this woman’s face was so deeply disturbing to him, that it made him forget what he was doing. After a second, he got himself together, and went back to work. But after she left, he couldn’t stop thinking about her. He knew he had to do something he’d been puttin', 'https://dts.podtrac.com/redirect.mp3/stitcher.simplecastaudio.com/814143cd-09c6-426f-920a-7be9b3dc1506/episodes/298a3de2-942a-4919-981e-4dcca30f298c/audio/128/default.mp3?aid=rss_feed&amp;awCollectionId=814143cd-09c6-426f-920a-7be9b3dc1506&amp;awEpisodeId=298a3de2-942a-4919-981e-4dcca30f298c&amp;feed=dloY8UYJ', 2236, '2026-11-16 08:00:00'::timestamptz, 7000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Paved Over (PODCAST EXCLUSIVE EPISODE)', 'Today, I''m going to tell you two very disturbing stories that have been published in different places, they''re fairly well-known stories, but in many ways, they''ve been passed down from generation to generation because of how disturbing they are. It''s not entirely clear where the truth ends and the fiction begins, but these stories center around events that actually happened. So, it''s up to you – as you hear my rendition of these stories – what to believe. &nbsp; You can WATCH all new &amp; exclusive MrBallen podcast episodes on my YouTube channel, just called "MrBallen" - https://www.youtube.', 'https://dts.podtrac.com/redirect.mp3/stitcher.simplecastaudio.com/814143cd-09c6-426f-920a-7be9b3dc1506/episodes/a9899e07-9ebb-4999-aa10-3c00aa99bea2/audio/128/default.mp3?aid=rss_feed&amp;awCollectionId=814143cd-09c6-426f-920a-7be9b3dc1506&amp;awEpisodeId=a9899e07-9ebb-4999-aa10-3c00aa99bea2&amp;feed=dloY8UYJ', 2161, '2026-11-13 08:00:00'::timestamptz, 8000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Occupational Hazard', 'Today’s podcast will feature 4 stories about people whose jobs put them face-to-face with the unthinkable. The audio from all four stories has been pulled from our main YouTube channel, which is just called "MrBallen," and has been remastered for today''s podcast. Story names, previews &amp; links to original YouTube videos: #4 -- "Most Dangerous Job" --&nbsp;Horrifying accident in a terrifying profession&nbsp;(Original YouTube link --&nbsp; https://www.youtube.com/watch?v=l74_VQPdxjU ) #3 -- "Silent Flight" --&nbsp;Fighter pilots witness something truly horrifying in the air&nbsp;(Original You', 'https://dts.podtrac.com/redirect.mp3/stitcher.simplecastaudio.com/814143cd-09c6-426f-920a-7be9b3dc1506/episodes/71444194-99de-48b3-b786-a264867e8b44/audio/128/default.mp3?aid=rss_feed&amp;awCollectionId=814143cd-09c6-426f-920a-7be9b3dc1506&amp;awEpisodeId=71444194-99de-48b3-b786-a264867e8b44&amp;feed=dloY8UYJ', 1612, '2026-11-12 08:00:00'::timestamptz, 9000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Prep for Disaster (PODCAST EXCLUSIVE EPISODE)', 'Today, I’m going to tell you four stories about people who are very focused on preparations for something that’s important to them. But during this prep, they each misjudge a single detail that causes an extreme amount of chaos and pain. &nbsp; You can WATCH all new &amp; exclusive MrBallen podcast episodes on my YouTube channel, just called "MrBallen" - https://www.youtube.com/c/MrBallen If you want to reach out to me, contact me on Instagram, Twitter or any other major social media platform, my username on all of them is @mrballen Hosted by Simplecast, an AdsWizz company. See pcm.adswizz.com', 'https://dts.podtrac.com/redirect.mp3/stitcher.simplecastaudio.com/814143cd-09c6-426f-920a-7be9b3dc1506/episodes/efe31161-19b5-4123-9235-47b55d210102/audio/128/default.mp3?aid=rss_feed&amp;awCollectionId=814143cd-09c6-426f-920a-7be9b3dc1506&amp;awEpisodeId=efe31161-19b5-4123-9235-47b55d210102&amp;feed=dloY8UYJ', 1835, '2026-11-11 08:00:00'::timestamptz, 10000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'On the Line (PODCAST EXCLUSIVE EPISODE)', 'One night in August 1992, a sheriff’s deputy raced down an empty road in a rural part of Tennessee. A local woman had been kidnapped that morning, and right this very second, the kidnapper was making a ransom call. That call had been traced to a payphone just up ahead, and the deputy was racing to get there before the suspect left.&nbsp;The deputy sped up to the curb in front of the phone booth and leapt out of the car – but inside the booth, the phone was dangling on its cord... and the suspect was gone. &nbsp; You can WATCH all new &amp; exclusive MrBallen podcast episodes on my YouTube chan', 'https://dts.podtrac.com/redirect.mp3/stitcher.simplecastaudio.com/814143cd-09c6-426f-920a-7be9b3dc1506/episodes/8d0c1f91-0f9c-4854-9dfa-c22a4ec9a125/audio/128/default.mp3?aid=rss_feed&amp;awCollectionId=814143cd-09c6-426f-920a-7be9b3dc1506&amp;awEpisodeId=8d0c1f91-0f9c-4854-9dfa-c22a4ec9a125&amp;feed=dloY8UYJ', 2283, '2026-11-09 08:00:00'::timestamptz, 11000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Guided by the Dead (PODCAST EXCLUSIVE EPISODE)', 'Today, I''m going to tell you two really unbelievable stories that, realistically, we don''t know if they 100% happened. But in each story, there''s pretty compelling witness testimony that something really bizarre actually happened. &nbsp; You can WATCH all new &amp; exclusive MrBallen podcast episodes on my YouTube channel, just called "MrBallen" - https://www.youtube.com/c/MrBallen If you want to reach out to me, contact me on Instagram, Twitter or any other major social media platform, my username on all of them is @mrballen Hosted by Simplecast, an AdsWizz company. See pcm.adswizz.com for in', 'https://dts.podtrac.com/redirect.mp3/stitcher.simplecastaudio.com/814143cd-09c6-426f-920a-7be9b3dc1506/episodes/c550ec06-c4a2-4e9b-a9f7-a52b5ef9b802/audio/128/default.mp3?aid=rss_feed&amp;awCollectionId=814143cd-09c6-426f-920a-7be9b3dc1506&amp;awEpisodeId=c550ec06-c4a2-4e9b-a9f7-a52b5ef9b802&amp;feed=dloY8UYJ', 1862, '2026-11-06 08:00:00'::timestamptz, 12000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Still Here', 'Today''s podcast will feature 2 stories about eyewitness accounts that challenge everything we think we know about death. The audio from all three stories has been pulled from our main YouTube channel, which is just called "MrBallen," and has been remastered for today''s podcast. Story names, previews &amp; links to original YouTube videos: #2 -- "One Last Flight" --&nbsp;A well-known pilot is reported flying in a way that makes no sense&nbsp;(Original YouTube link --&nbsp; https://www.youtube.com/watch?v=Rf6T9YLyTRY ) #1 -- "The Bus Ride Home" --&nbsp;A man hears something while riding an empty', 'https://dts.podtrac.com/redirect.mp3/stitcher.simplecastaudio.com/814143cd-09c6-426f-920a-7be9b3dc1506/episodes/5aebc0a7-4ed8-4788-b9c0-c79c0cae0372/audio/128/default.mp3?aid=rss_feed&amp;awCollectionId=814143cd-09c6-426f-920a-7be9b3dc1506&amp;awEpisodeId=5aebc0a7-4ed8-4788-b9c0-c79c0cae0372&amp;feed=dloY8UYJ', 1616, '2026-11-05 08:00:00'::timestamptz, 13000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'In the Blink of an Eye (PODCAST EXCLUSIVE EPISODE)', 'Today, I’m going to tell you three stories about how just one small moment of distraction can lead to absolute catastrophe. &nbsp; You can WATCH all new &amp; exclusive MrBallen podcast episodes on my YouTube channel, just called "MrBallen" - https://www.youtube.com/c/MrBallen If you want to reach out to me, contact me on Instagram, Twitter or any other major social media platform, my username on all of them is @mrballen Hosted by Simplecast, an AdsWizz company. See pcm.adswizz.com for information about our collection and use of personal data for advertising.', 'https://dts.podtrac.com/redirect.mp3/stitcher.simplecastaudio.com/814143cd-09c6-426f-920a-7be9b3dc1506/episodes/35d316c5-279b-4049-83e7-43bc939e9a01/audio/128/default.mp3?aid=rss_feed&amp;awCollectionId=814143cd-09c6-426f-920a-7be9b3dc1506&amp;awEpisodeId=35d316c5-279b-4049-83e7-43bc939e9a01&amp;feed=dloY8UYJ', 1770, '2026-11-04 08:00:00'::timestamptz, 14000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Rumor Has It (PODCAST EXCLUSIVE EPISODE)', 'One night in February 2012, a farmer in rural Ohio was at home, when he suddenly heard the sound of a revving engine and spinning tires outside.&nbsp;It was coming from a neighboring field that nobody was supposed to be in, so the farmer hurried out to his truck to try and catch the intruder. But by the time he reached the field, whoever it was... had vanished. You can WATCH all new &amp; exclusive MrBallen podcast episodes on my YouTube channel, just called "MrBallen" - https://www.youtube.com/c/MrBallen If you want to reach out to me, contact me on Instagram, Twitter or any other major socia', 'https://dts.podtrac.com/redirect.mp3/stitcher.simplecastaudio.com/814143cd-09c6-426f-920a-7be9b3dc1506/episodes/fde9f0f4-2cb5-4601-ac36-2c8d340da366/audio/128/default.mp3?aid=rss_feed&amp;awCollectionId=814143cd-09c6-426f-920a-7be9b3dc1506&amp;awEpisodeId=fde9f0f4-2cb5-4601-ac36-2c8d340da366&amp;feed=dloY8UYJ', 1792, '2026-11-02 08:00:00'::timestamptz, 15000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
