  VALUES (v_pod_id, 'Spectral', 'Today’s podcast will feature 3 stories about people whose encounters with the supernatural defy explanation. The audio from all three stories has been pulled from our main YouTube channel, which is just called "MrBallen," and has been remastered for today''s podcast. Story names, previews &amp; links to original YouTube videos: #3 -- "The Surfman" --&nbsp;A surfman wakes up from a vivid dream and feels there has to be some deeper meaning to it&nbsp;(Original YouTube link --&nbsp; https://www.youtube.com/watch?v=S_v2HPbi5hM ) #2 -- "Practically Family" --&nbsp;A late-night phone call from a trus', 'https://dts.podtrac.com/redirect.mp3/stitcher.simplecastaudio.com/814143cd-09c6-426f-920a-7be9b3dc1506/episodes/6201981f-46e0-444e-be1f-b31ee3defef0/audio/128/default.mp3?aid=rss_feed&amp;awCollectionId=814143cd-09c6-426f-920a-7be9b3dc1506&amp;awEpisodeId=6201981f-46e0-444e-be1f-b31ee3defef0&amp;feed=dloY8UYJ', 1876, '2026-10-29 07:00:00'::timestamptz, 17000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Killer Without a Face (PODCAST EXCLUSIVE EPISODE)', 'On the evening of July 2nd, 2000, a local man from Galien, Michigan walked slowly through a wooded area with about 30 other people.&nbsp;A woman had gone missing a few days ago, and the man was part of a large volunteer search party that was searching these woods for any sign of her. Now, it was getting dark, so the man decided to call it. But just as he was about to tell the others, he caught a glimpse of something blue on the ground. &nbsp; You can WATCH all new &amp; exclusive MrBallen podcast episodes on my YouTube channel, just called "MrBallen" - https://www.youtube.com/c/MrBallen If you', 'https://dts.podtrac.com/redirect.mp3/stitcher.simplecastaudio.com/814143cd-09c6-426f-920a-7be9b3dc1506/episodes/00a21722-947b-49be-8f89-ff7d7a278ad9/audio/128/default.mp3?aid=rss_feed&amp;awCollectionId=814143cd-09c6-426f-920a-7be9b3dc1506&amp;awEpisodeId=00a21722-947b-49be-8f89-ff7d7a278ad9&amp;feed=dloY8UYJ', 2299, '2026-10-26 07:00:00'::timestamptz, 18000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Fan Favorite - &quot;Holiday Fear&quot;', 'Today''s story is a fan favorite that was previously published as Episode 374. One day in mid-December 2003, Detective Mark Kelly walked into a small kitchen at a home in Fort Worth, Texas. The house belonged to a potential suspect in a homicide case, and while his partner was interviewing that suspect in the other room, Kelly was poking around. He wanted to hurry, because the kitchen he was in was disgusting. There was a layer of dirt on the floor, the dishwasher was open, with dirty plates and silverware still inside, dishes were stacked up in the sink, and used pots and rotting food covered ', 'https://dts.podtrac.com/redirect.mp3/stitcher.simplecastaudio.com/814143cd-09c6-426f-920a-7be9b3dc1506/episodes/801f9e28-065c-4ff2-b860-f7ecfe7f15e4/audio/128/default.mp3?aid=rss_feed&amp;awCollectionId=814143cd-09c6-426f-920a-7be9b3dc1506&amp;awEpisodeId=801f9e28-065c-4ff2-b860-f7ecfe7f15e4&amp;feed=dloY8UYJ', 2427, '2026-10-23 07:00:00'::timestamptz, 19000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Born Together', 'Today’s story is really weird. It’s basically a cross between a medical mystery and a full-blow supernatural story. But independent of what you believe in terms of what actually happened here, what you’re going to hear about is totally bizarre and just inexplicable behavior that was documented over and over again over many years. And so even if you think this is fully rooted in science, I’m telling you there’s not really a great explanation for exactly what went down here. Story name, preview &amp; link to original YouTube video: #1 -- "Born Together" --&nbsp;When separation became impossible,', 'https://dts.podtrac.com/redirect.mp3/stitcher.simplecastaudio.com/814143cd-09c6-426f-920a-7be9b3dc1506/episodes/26e8c781-b86b-44cd-8503-8cd5b9f101bc/audio/128/default.mp3?aid=rss_feed&amp;awCollectionId=814143cd-09c6-426f-920a-7be9b3dc1506&amp;awEpisodeId=26e8c781-b86b-44cd-8503-8cd5b9f101bc&amp;feed=dloY8UYJ', 1514, '2026-10-22 07:00:00'::timestamptz, 20000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
