  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Under Construction (PODCAST EXCLUSIVE EPISODE)', 'On an afternoon in the spring of 1999, a woman walked to her bedroom closet and opened the door with a shaking hand. She’d just gotten a disturbing phone call from someone who begged her to go into this closet, find two specific objects, and get rid of them. But now, as the woman stared at the objects, she knew she couldn’t do that. Instead, she shut the door and called the police. &nbsp; You can WATCH all new &amp; exclusive MrBallen podcast episodes on my YouTube channel, just called "MrBallen" - https://www.youtube.com/c/MrBallen If you want to reach out to me, contact me on Instagram, Twit', 'https://dts.podtrac.com/redirect.mp3/stitcher.simplecastaudio.com/814143cd-09c6-426f-920a-7be9b3dc1506/episodes/3e7c8251-2da1-4427-867f-7374e5c461e3/audio/128/default.mp3?aid=rss_feed&amp;awCollectionId=814143cd-09c6-426f-920a-7be9b3dc1506&amp;awEpisodeId=3e7c8251-2da1-4427-867f-7374e5c461e3&amp;feed=dloY8UYJ', 1995, '2026-10-19 07:00:00'::timestamptz, 22000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'One Last Fare/Mom&apos;s Cooking | Campfire Stories with MrBallen', 'Welcome back to the Campfire! Tonight, I have two very different stories. But each of them are about sisters who stick together, even in the face of truly unimaginable horror. &nbsp; Be sure to WATCH this episode on my YouTube channel on Friday, October 16th at 2:00 p.m. ET! Hosted by Simplecast, an AdsWizz company. See pcm.adswizz.com for information about our collection and use of personal data for advertising.', 'https://dts.podtrac.com/redirect.mp3/stitcher.simplecastaudio.com/814143cd-09c6-426f-920a-7be9b3dc1506/episodes/6f3fe774-749c-4f5f-acf4-bb2fe5dbaf03/audio/128/default.mp3?aid=rss_feed&amp;awCollectionId=814143cd-09c6-426f-920a-7be9b3dc1506&amp;awEpisodeId=6f3fe774-749c-4f5f-acf4-bb2fe5dbaf03&amp;feed=dloY8UYJ', 1827, '2026-10-16 07:00:00'::timestamptz, 23000);
