  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'The Hidden Connection (PODCAST EXCLUSIVE EPISODE)', 'In 2013, a police sergeant in northern France called the local telephone company, and asked to set up a tap on a suspect’s phone. He had a warrant in his hands and was ready to read off the details, but the operator on the line said... "It couldn’t be done." Because that phone number was already being tapped – as part of another murder investigation. &nbsp; You can WATCH all new &amp; exclusive MrBallen podcast episodes on my YouTube channel, just called "MrBallen" - https://www.youtube.com/c/MrBallen If you want to reach out to me, contact me on Instagram, Twitter or any other major social me', 'https://dts.podtrac.com/redirect.mp3/stitcher.simplecastaudio.com/814143cd-09c6-426f-920a-7be9b3dc1506/episodes/43858c66-684c-413b-bb63-dc5476078145/audio/128/default.mp3?aid=rss_feed&amp;awCollectionId=814143cd-09c6-426f-920a-7be9b3dc1506&amp;awEpisodeId=43858c66-684c-413b-bb63-dc5476078145&amp;feed=dloY8UYJ', 1785, '2026-10-12 07:00:00'::timestamptz, 25000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Fan Favorite - &quot;One Foot Out the Door&quot;', 'Today''s story is a fan favorite that was previously published as Episode 372. Just after 7 p.m. on June 16th, 2010, an employee at the Palmdale, California Sheriff’s Department tapped his fingers on his desk and sighed. The department was usually pretty busy, but it had been slow that night, so the shift was dragging. As the employee aimlessly moved around some paperwork, he heard something that made him look up at the front doors of the department. The sound came from outside, and it was muffled, but it sounded like someone yelling. Seconds later, a young woman charged through the front doors', 'https://dts.podtrac.com/redirect.mp3/stitcher.simplecastaudio.com/814143cd-09c6-426f-920a-7be9b3dc1506/episodes/46674184-0d03-47c2-b1a1-554ce6fd9031/audio/128/default.mp3?aid=rss_feed&amp;awCollectionId=814143cd-09c6-426f-920a-7be9b3dc1506&amp;awEpisodeId=46674184-0d03-47c2-b1a1-554ce6fd9031&amp;feed=dloY8UYJ', 2474, '2026-10-09 07:00:00'::timestamptz, 26000);
