  VALUES (v_pod_id, 'From Beyond Vol. III', 'Today’s podcast will feature 3 spooky stories about messages from beyond. The audio from all three stories has been pulled from our main YouTube channel, which is just called "MrBallen," and has been remastered for today''s podcast. Story names, previews &amp; links to original YouTube videos: #3 -- "Into The Coffin" --&nbsp;After a woman is brutally killed in a Hong Kong hotel room, her brother comes up with his own plan to catch the killer&nbsp;(Original YouTube link --&nbsp; https://www.youtube.com/watch?v=6lJ8oTLQSoc ) #2 -- "Another Nightmare" --&nbsp;When a woman insists her house is haun', 'https://dts.podtrac.com/redirect.mp3/stitcher.simplecastaudio.com/814143cd-09c6-426f-920a-7be9b3dc1506/episodes/4a4ed4f1-58a8-44c8-be3c-dc97ffc6ec73/audio/128/default.mp3?aid=rss_feed&amp;awCollectionId=814143cd-09c6-426f-920a-7be9b3dc1506&amp;awEpisodeId=4a4ed4f1-58a8-44c8-be3c-dc97ffc6ec73&amp;feed=dloY8UYJ', 1628, '2026-10-08 07:00:00'::timestamptz, 27000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'The Nightmare Cure (PODCAST EXCLUSIVE EPISODE)', 'Today, I’m going to tell three stories about people whose stressful lives actually drove them to the brink of insanity – until doctors finally discovered the root of all their issues. &nbsp; You can WATCH all new &amp; exclusive MrBallen podcast episodes on my YouTube channel, just called "MrBallen" - https://www.youtube.com/c/MrBallen If you want to reach out to me, contact me on Instagram, Twitter or any other major social media platform, my username on all of them is @mrballen Hosted by Simplecast, an AdsWizz company. See pcm.adswizz.com for information about our collection and use of perso', 'https://dts.podtrac.com/redirect.mp3/stitcher.simplecastaudio.com/814143cd-09c6-426f-920a-7be9b3dc1506/episodes/22fc785b-e86a-4cb0-b701-dca4868c09bd/audio/128/default.mp3?aid=rss_feed&amp;awCollectionId=814143cd-09c6-426f-920a-7be9b3dc1506&amp;awEpisodeId=22fc785b-e86a-4cb0-b701-dca4868c09bd&amp;feed=dloY8UYJ', 1364, '2026-10-07 07:00:00'::timestamptz, 28000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'The Stage Manager (PODCAST EXCLUSIVE EPISODE)', 'One afternoon in December 1980, one of the most famous comedians in France pulled a stack of letters from his mailbox in Paris. As he flipped through them, one caught his eye: It had no postmark or return address, and there was something small and hard inside.&nbsp;He ripped the envelope open and pulled out a bullet, along with a piece of paper that read: “The next one is for you.” &nbsp; You can WATCH all new &amp; exclusive MrBallen podcast episodes on my YouTube channel, just called "MrBallen" - https://www.youtube.com/c/MrBallen If you want to reach out to me, contact me on Instagram, Twit', 'https://dts.podtrac.com/redirect.mp3/stitcher.simplecastaudio.com/814143cd-09c6-426f-920a-7be9b3dc1506/episodes/4bab26ca-2dc1-4007-b200-382d9684bbd1/audio/128/default.mp3?aid=rss_feed&amp;awCollectionId=814143cd-09c6-426f-920a-7be9b3dc1506&amp;awEpisodeId=4bab26ca-2dc1-4007-b200-382d9684bbd1&amp;feed=dloY8UYJ', 2072, '2026-10-05 07:00:00'::timestamptz, 29000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Sometimes the Vanished Never Return | Campfire for a Cause', 'Tonight, I have a very special guest joining me at the Campfire! Liana is a HUGE MrBallen fan, and I wanted to tell a few stories live, just for her. All proceeds from this episode will be donated to Liana’s family to help with medical expenses following her leukemia diagnosis, as well as her father’s ongoing battle with ALS. If you are able to help, please consider donating to their GoFundMe: https://www.gofundme.com/f/support-lianas-battle-with-leukemia?cp_src=d And make sure to WATCH this episode on my YouTube channel next Friday, October 2nd at 2:00 p.m. ET! Hosted by Simplecast, an AdsWiz', 'https://dts.podtrac.com/redirect.mp3/stitcher.simplecastaudio.com/814143cd-09c6-426f-920a-7be9b3dc1506/episodes/b2ce94db-2828-4973-b8c3-6f135d50342a/audio/128/default.mp3?aid=rss_feed&amp;awCollectionId=814143cd-09c6-426f-920a-7be9b3dc1506&amp;awEpisodeId=b2ce94db-2828-4973-b8c3-6f135d50342a&amp;feed=dloY8UYJ', 3470, '2026-10-02 07:00:00'::timestamptz, 30000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Reality Glitch Vol. II', 'Today’s podcast will feature 2 stories that challenge our understanding of reality. The audio from both stories has been pulled from our main YouTube channel, which is just called "MrBallen," and has been remastered for today''s podcast. Story names, previews &amp; links to original YouTube videos: #2 -- "By The Pool" --&nbsp;A doctor is having a relaxing day at his pool when he sees something that can''t escape him&nbsp;(Original YouTube link --&nbsp; https://www.youtube.com/watch?v=fhAi2A2dABU ) #1 -- "The Ride Home" --&nbsp;There is a certain sub-genre of the SDM we have covered a handful of ', 'https://dts.podtrac.com/redirect.mp3/stitcher.simplecastaudio.com/814143cd-09c6-426f-920a-7be9b3dc1506/episodes/4fca8765-b089-4e44-800c-0c0c2c19e485/audio/128/default.mp3?aid=rss_feed&amp;awCollectionId=814143cd-09c6-426f-920a-7be9b3dc1506&amp;awEpisodeId=4fca8765-b089-4e44-800c-0c0c2c19e485&amp;feed=dloY8UYJ', 1636, '2026-10-01 07:00:00'::timestamptz, 31000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Brutal Mercy (PODCAST EXCLUSIVE EPISODE)', 'Today, I’m going to tell you four stories of people who thought their day couldn’t get any worse... but they were wrong. &nbsp; You can WATCH all new &amp; exclusive MrBallen podcast episodes on my YouTube channel, just called "MrBallen" - https://www.youtube.com/c/MrBallen If you want to reach out to me, contact me on Instagram, Twitter or any other major social media platform, my username on all of them is @mrballen Hosted by Simplecast, an AdsWizz company. See pcm.adswizz.com for information about our collection and use of personal data for advertising.', 'https://dts.podtrac.com/redirect.mp3/stitcher.simplecastaudio.com/814143cd-09c6-426f-920a-7be9b3dc1506/episodes/0bff8699-f940-47eb-bb98-938f1acdf62a/audio/128/default.mp3?aid=rss_feed&amp;awCollectionId=814143cd-09c6-426f-920a-7be9b3dc1506&amp;awEpisodeId=0bff8699-f940-47eb-bb98-938f1acdf62a&amp;feed=dloY8UYJ', 1647, '2026-09-30 07:00:00'::timestamptz, 32000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'On Patrol (PODCAST EXCLUSIVE EPISODE)', 'One night in March 1997, a man carried a muddy, black plastic case into a police station in the small town of Higginson, Arkansas.&nbsp;A local police officer had been murdered just three days ago, and the man desperately needed to see the detective who was leading the investigation. So once the man got inside, he headed straight to the detective’s office, where he immediately opened the black case – and pulled out a gun. &nbsp; You can WATCH all new &amp; exclusive MrBallen podcast episodes on my YouTube channel, just called "MrBallen" - https://www.youtube.com/c/MrBallen If you want to reach', 'https://dts.podtrac.com/redirect.mp3/stitcher.simplecastaudio.com/814143cd-09c6-426f-920a-7be9b3dc1506/episodes/a52861d0-193e-4703-8223-5540771769a5/audio/128/default.mp3?aid=rss_feed&amp;awCollectionId=814143cd-09c6-426f-920a-7be9b3dc1506&amp;awEpisodeId=a52861d0-193e-4703-8223-5540771769a5&amp;feed=dloY8UYJ', 1766, '2026-09-28 07:00:00'::timestamptz, 33000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Fan Favorite - &quot;The Receipt&quot;', 'Today''s story is a fan favorite that was previously published as Episode 365. On the afternoon of March 24, 2006, an employee at a moving truck rental company in Ohio opened his desk drawer and grabbed a wad of cash. It had been a slow day, so the employee was using his downtime to organize a few recent payments. The money he’d just grabbed was from an all-cash deal that had happened a few days ago. At the time, the employee had been super busy, so he’d just taken the cash from the customer, flipped through it quickly to make sure the amount seemed right, then shoved the money in the drawer to', 'https://dts.podtrac.com/redirect.mp3/stitcher.simplecastaudio.com/814143cd-09c6-426f-920a-7be9b3dc1506/episodes/fc4cc862-045a-4f18-9284-9e6e3e0a4ebe/audio/128/default.mp3?aid=rss_feed&amp;awCollectionId=814143cd-09c6-426f-920a-7be9b3dc1506&amp;awEpisodeId=fc4cc862-045a-4f18-9284-9e6e3e0a4ebe&amp;feed=dloY8UYJ', 2246, '2026-09-25 07:00:00'::timestamptz, 34000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
