  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Murder In Marseilles (PODCAST EXCLUSIVE EPISODE)', 'One morning in January 1990, a man walked into a police station in Marseille, France, clutching a newspaper. He went up to the desk, and said he’d seen a sketch of a murder suspect in the paper that morning – and he knew who it was. He unrolled the newspaper... and held it up next to his own face. &nbsp; You can WATCH all new &amp; exclusive MrBallen podcast episodes on my YouTube channel, just called "MrBallen" - https://www.youtube.com/c/MrBallen If you want to reach out to me, contact me on Instagram, Twitter or any other major social media platform, my username on all of them is @mrballen ', 'https://dts.podtrac.com/redirect.mp3/stitcher.simplecastaudio.com/814143cd-09c6-426f-920a-7be9b3dc1506/episodes/37bdcac1-5eee-422c-a285-01526e2da927/audio/128/default.mp3?aid=rss_feed&amp;awCollectionId=814143cd-09c6-426f-920a-7be9b3dc1506&amp;awEpisodeId=37bdcac1-5eee-422c-a285-01526e2da927&amp;feed=dloY8UYJ', 1775, '2026-09-21 07:00:00'::timestamptz, 37000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Fan Favorite - &quot;The Watercooler&quot;', 'Today''s story is a fan favorite that was previously published as Episode 361. On a morning in early 1986 in Arizona, someone sat hunched over a desk, furiously writing a letter. And almost every line of this letter included a direct threat of violence this person was going to inflict on the recipient. They kept writing, embellishing every horrible thing that they wanted to do. Finally, they finished writing and read over the letter – it was explicit and terrifying, just as they’d hoped. They put the letter down, glanced at a cardboard box sitting on the floor, and smiled. Nobody would ever sus', 'https://dts.podtrac.com/redirect.mp3/stitcher.simplecastaudio.com/814143cd-09c6-426f-920a-7be9b3dc1506/episodes/0741266a-0b93-4cdf-9e62-8105f0e72864/audio/128/default.mp3?aid=rss_feed&amp;awCollectionId=814143cd-09c6-426f-920a-7be9b3dc1506&amp;awEpisodeId=0741266a-0b93-4cdf-9e62-8105f0e72864&amp;feed=dloY8UYJ', 2220, '2026-09-18 07:00:00'::timestamptz, 38000);
