  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Human Resources (PODCAST EXCLUSIVE EPISODE)', 'One morning in March of 1999, a detective in Norcross, Georgia leaned in closely to his computer screen. He was reviewing video footage his team had recorded at a murder scene – and finally, he arrived at the exact frame he wanted. He zoomed in and smiled. Because the thing he was looking for... wasn''t there. &nbsp; You can WATCH all new &amp; exclusive MrBallen podcast episodes on my YouTube channel, just called "MrBallen" - https://www.youtube.com/c/MrBallen If you want to reach out to me, contact me on Instagram, Twitter or any other major social media platform, my username on all of them i', 'https://dts.podtrac.com/redirect.mp3/stitcher.simplecastaudio.com/814143cd-09c6-426f-920a-7be9b3dc1506/episodes/c54be9e2-5a51-4143-9576-7092d5ae4a22/audio/128/default.mp3?aid=rss_feed&amp;awCollectionId=814143cd-09c6-426f-920a-7be9b3dc1506&amp;awEpisodeId=c54be9e2-5a51-4143-9576-7092d5ae4a22&amp;feed=dloY8UYJ', 1842, '2026-09-14 07:00:00'::timestamptz, 41000);
