  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Open Door Policy (PODCAST EXCLUSIVE EPISODE)', 'In the fall of 2009, a college student sat in a crowded lecture hall in Southern California, listening to his professor. Suddenly, the doors swung open and three campus police officers walked in, followed by a man in a suit. The officers went over and whispered something to the professor, who leaned into his microphone. And before the professor even said a word, the student’s stomach dropped – because he’d just realized what was about to happen. &nbsp; You can WATCH all new &amp; exclusive MrBallen podcast episodes on my YouTube channel, just called "MrBallen" - https://www.youtube.com/c/MrBal', 'https://dts.podtrac.com/redirect.mp3/stitcher.simplecastaudio.com/814143cd-09c6-426f-920a-7be9b3dc1506/episodes/0076179a-d382-4b74-a06a-c04a8fe0cbd8/audio/128/default.mp3?aid=rss_feed&amp;awCollectionId=814143cd-09c6-426f-920a-7be9b3dc1506&amp;awEpisodeId=0076179a-d382-4b74-a06a-c04a8fe0cbd8&amp;feed=dloY8UYJ', 2142, '2026-09-07 07:00:00'::timestamptz, 45000);
