  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'The Clearing', 'One summer day, a man named John Randolph was hiking through a remote forest in Colorado when he began to smell something terrible. Intrigued, he followed the smell until it brought him to this clearing, and in the clearing John saw what looked like an old campsite. Now, John is out in the middle of nowhere, so the idea that somebody was camping out out here, in what looked like a long term settlement, was pretty bizarre to John. John walked into the clearing to see what was going on, and when he turned the corner, he saw something in the middle of the campsite he just couldn’t even process...', 'https://dts.podtrac.com/redirect.mp3/stitcher.simplecastaudio.com/814143cd-09c6-426f-920a-7be9b3dc1506/episodes/3a0c0d48-d0c8-48ee-adb2-9184d64b902d/audio/128/default.mp3?aid=rss_feed&amp;awCollectionId=814143cd-09c6-426f-920a-7be9b3dc1506&amp;awEpisodeId=3a0c0d48-d0c8-48ee-adb2-9184d64b902d&amp;feed=dloY8UYJ', 1468, '2026-09-03 07:00:00'::timestamptz, 47000);
