  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Last Call (PODCAST EXCLUSIVE EPISODE)', 'In the fall of 2010, a detective dug through a dresser in a bedroom near Paris. He was looking for evidence, and when he pulled open the last drawer, he found five cell phones hidden inside. He powered one of them on and checked the call history and messages – then he opened the photos app and froze. He swiped to the next photo, then the one after that. There were dozens of them – and they all showed the same thing. You can WATCH all new & exclusive MrBallen podcast episodes on my YouTube channel, just called "MrBallen" - https://www.youtube.com/c/MrBallen If you want to reach out to me, conta', 'https://dts.podtrac.com/redirect.mp3/stitcher.simplecastaudio.com/814143cd-09c6-426f-920a-7be9b3dc1506/episodes/165ceb2d-8470-4cf7-bde3-ae97273a7736/audio/128/default.mp3?aid=rss_feed&amp;awCollectionId=814143cd-09c6-426f-920a-7be9b3dc1506&amp;awEpisodeId=165ceb2d-8470-4cf7-bde3-ae97273a7736&amp;feed=dloY8UYJ', 2036, '2026-08-24 07:00:00'::timestamptz, 51000);
