-- ---------- The Louis Theroux Podcast ----------
DO $$
DECLARE
  v_host_id uuid;
  v_pod_id uuid;
  v_cat uuid;
BEGIN
  SELECT id INTO v_cat FROM categories WHERE name_ar = 'ثقافة وأدب' LIMIT 1;
  INSERT INTO hosts (name_ar, slug, photo_url, cover_url, title_ar, specialty_ar, bio_ar, country, category_id, is_verified, followers_count)
  VALUES ('Spotify Studios', 'the-louis-theroux-podcast', 'https://is1-ssl.mzstatic.com/image/thumb/Podcasts122/v4/1e/20/d1/1e20d177-1e41-10cf-1e2d-3b895ad3df8e/mza_10878364100163359946.jpeg/600x600bb.jpg', 'https://is1-ssl.mzstatic.com/image/thumb/Podcasts122/v4/1e/20/d1/1e20d177-1e41-10cf-1e2d-3b895ad3df8e/mza_10878364100163359946.jpeg/600x600bb.jpg', 'مقدم', 'ثقافة وأدب', 'بودكاست حقيقي: The Louis Theroux Podcast', 'أونلاين', v_cat, true, 50000)
  RETURNING id INTO v_host_id;

  INSERT INTO podcasts (title, description, host_id, category_id, type, cover_url, audience_level, plays_count, rating_avg)
  VALUES ('The Louis Theroux Podcast', 'Join Louis Theroux as he embarks on a series of in-depth and freewheeling conversations with a curated collection of fascinating figures from across the globe.&amp;nbsp;The Louis Theroux Podcast is a Spotify podcast from Mindhouse, now available everywhere.', v_host_id, v_cat, 'cultural', 'https://is1-ssl.mzstatic.com/image/thumb/Podcasts122/v4/1e/20/d1/1e20d177-1e41-10cf-1e2d-3b895ad3df8e/mza_10878364100163359946.jpeg/600x600bb.jpg', 'beginner', 100000, 4.7)
  RETURNING id INTO v_pod_id;

  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Judd Apatow on making Steve Carell a leading man, attacking the Manosphere and the death of comedy movies', 'In this week’s episode, Louis speaks to producer, director, writer and all-around funny guy Judd Apatow. The pair discuss how Judd made Steve Carell into a leading man, how his films attack the Manosphere and why comedy movies are a dying breed.&amp;nbsp;&amp;nbsp; &amp;nbsp; Warnings: Strong language and adult themes.&amp;nbsp;&amp;nbsp; &amp;nbsp; Links/Attachments:&amp;nbsp; &amp;nbsp; Film: The 40-Year-Old Virgin (2005)&amp;nbsp; https://www.netflix.com/title/70028904&amp;nbsp;&amp;nbsp; &amp;nbsp; Film: Anchorman: The Legend of Ron Burgundy (2004)&amp;nbsp; https://www.youtube.com/watch?v', 'https://traffic.megaphone.fm/GLT5270418279.mp3', 4674, '2026-11-18 00:00:00'::timestamptz, 5000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Megan Phelps-Roper discusses leaving the Westboro Baptist Church, interviewing J.K. Rowling and how social media amplifies our worst impulses', 'Louis is joined by writer, podcaster and subject of not one, not two, but three Louis Theroux documentaries, Megan Phelps-Roper. 20 years on from them meeting, the pair swap notes on Megan’s departure from the church, crossing paths with J.K. Rowling and how social media amplifies our worst impulses.&amp;nbsp; &amp;nbsp; Warnings: Strong language and adult themes.&amp;nbsp;&amp;nbsp; &amp;nbsp; If you''ve been affected by the topics discussed in this episode, visit spotify.com/resources.&amp;nbsp; &amp;nbsp; Links/Attachments:&amp;nbsp; &amp;nbsp; The three video/audio extracts are from ‘The Mo', 'https://traffic.megaphone.fm/GLT8709724565.mp3', 5250, '2026-11-11 00:00:00'::timestamptz, 6000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'John Cooper Clarke on touring with the Buzzcocks, meeting Chuck Berry, and inspiring the Arctic Monkeys', 'In this episode, Louis speaks with the Poet Laureate of Punk, the Bard of Salford, the Doctor: performance poet John Cooper Clarke. The pair discuss John’s time touring with the Buzzcocks, meeting Chuck Berry backstage, and how his poetry inspired Alex Turner to form Arctic Monkeys. &amp;nbsp; &amp;nbsp; Warnings: Strong language and adult themes.&amp;nbsp;&amp;nbsp; &amp;nbsp; Links/Attachments:&amp;nbsp; &amp;nbsp; Book: Have It, John Cooper Clarke (2026)&amp;nbsp; https://www.panmacmillan.com/authors/john-cooper-clarke/have-it/9781037404191&amp;nbsp; &amp;nbsp; Book: I Wanna Be Yours, John ', 'https://traffic.megaphone.fm/GLT3594269910.mp3', 4807, '2026-11-04 00:00:00'::timestamptz, 7000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Naomi Klein discusses the dangers of data centres, Steve Bannon’s hip hop musical and why our tech overlords want to be edgelords', 'Louis sits down with writer, activist and filmmaker Naomi Klein. They discuss Steve Bannon’s hip hop musical, why data centres are so dangerous, and the tech overlords/edgelords that inspired her latest book, End Times Fascism. &amp;nbsp; &amp;nbsp; Warnings: Strong language and adult themes.&amp;nbsp;&amp;nbsp; &amp;nbsp; Links/Attachments:&amp;nbsp; &amp;nbsp; Book: End Times Fascism, Naomi Klein and Astra Taylor (2026)&amp;nbsp; https://naomiklein.org/end-times-fascism/&amp;nbsp;&amp;nbsp; &amp;nbsp; Book: Doppelganger, Naomi Klein (2023)&amp;nbsp; https://naomiklein.org/doppelganger/&amp;n', 'https://traffic.megaphone.fm/GLT3698907628.mp3', 4169, '2026-10-28 00:00:00'::timestamptz, 8000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Vinnie Jones on getting sober, mediating with Steven Seagal, and the Gazza incident', 'Louis is back on the road, this time to visit actor, footballer and professional hard man Vinnie Jones at his Sussex farm. The pair discuss Vinnie’s journey to sobriety, a bizarre standoff with Steven Seagal, and the real story behind those photos with Paul ‘Gazza’ Gascoigne. &amp;nbsp; &amp;nbsp; Warnings: Strong language and adult themes.&amp;nbsp;&amp;nbsp; &amp;nbsp; Links/Attachments:&amp;nbsp; &amp;nbsp; TV Show: The Gentlemen, (2024-present)&amp;nbsp; https://www.netflix.com/title/81437051&amp;nbsp;&amp;nbsp; &amp;nbsp; Book: A Kestrel for a Knave, Barry Hines (1968)&amp;nbsp; https://w', 'https://traffic.megaphone.fm/GLT4309317440.mp3', 4850, '2026-10-20 23:00:00'::timestamptz, 9000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
