  VALUES (v_pod_id, 'S6 EP3: Bob Vylan on his controversial Glastonbury performance', 'Louis is joined by Bobby Vylan, one half of the controversial punk-rap band Bob Vylan. In his first public interview since his contentious performance at Glastonbury - where he led a chant of ‘death to the IDF’ - Bobby discusses why he did it, the subsequent backlash and whether he still stands by the chant. Warnings: Strong language and adult themes. If you’ve been affected by the topics discussed in this episode, Spotify have a website for information and resources. Visit spotify.com/resources X Post: Visa Revoke by Deputy Secretary of State ⁠https://x.com/DeputySecState/status/1939697586920', 'https://traffic.megaphone.fm/GLT9724339614.mp3?updated=1772040447', 3720, '2025-10-24 18:12:00'::timestamptz, 36000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'S6 EP2: Michael Palin discusses Monty Python dynamics, famous fans, and ‘Life of Brian’ controversies', 'In this week’s episode, Louis speaks with the legendary comedian, writer and adventurer Michael Palin. Joining Louis at Spotify HQ, Michael details the fiery group dynamics within Monty Python, having Johnny Cash and George Harrison as famous fans, and the controversies surrounding Life Of Brian. Plus, Michael and Louis discuss whether being ’nice’ is a help or a hindrance. Warnings: Strong language and adult themes. Links/Attachments: TV Show: ‘Michael Palin in Venezuela’ (2025) - Channel 5 https://www.channel5.com/show/michael-palin-in-venezuela TV Show Episode: Whicker’s World from ‘Monty P', 'https://traffic.megaphone.fm/GLT5647727851.mp3?updated=1777030280', 4809, '2025-10-13 23:00:00'::timestamptz, 37000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'S6 EP1: Steve Coogan on falling out of love with Alan Partridge, playing Jimmy Savile, and sobriety', 'Louis sits down with writer, actor and comedian Steve Coogan in the first episode of the new series. Steve discusses falling in and out of love with Alan Partridge, literally wearing Jimmy Savile’s shoes in ‘The Reckoning’, and being sober after his ‘delayed adolescence’. Warning: 1970s mother-in-law jokes are included. Warnings: Strong language and adult themes. If you’ve been affected by the topics discussed in this episode, Spotify have a website for information and resources. Visit spotify.com/resources Links/Attachments: TV Show: ‘On the Hour’ (1991 – 1992) - BBC Radio 4 https://www.bbc.c', 'https://traffic.megaphone.fm/GLT8641816222.mp3?updated=1772040400', 4266, '2025-10-06 23:00:00'::timestamptz, 38000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Season 6 incoming...', 'Louis returns with another season of his chart-topping podcast! Join him on Tuesdays, from October 7th, as he offers up a plentiful cornucopia of starry guests. Watch exclusively on Spotify, or listen wherever you get your podcasts. Learn more about your ad choices. Visit podcastchoices.com/adchoices', 'https://traffic.megaphone.fm/GLT5326087659.mp3?updated=1759145259', 76, '2025-09-29 23:00:00'::timestamptz, 39000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'S5 EP8: Michael Cera on working with Tom Cruise, featuring in ''Barbie'', and never graduating', 'In this very special bonus episode, Louis is joined by actor and writer Michael Cera. Michael tells Louis about his foul-mouthed run-in with Tom Cruise, nearly missing out on his role as Allan in Barbie, and the reason he never graduated from high school. Plus, Louis reveals which Superbad character he most aligns with… Warnings: Strong language Links/Attachments: Film: The Phoenician Scheme (2025) - dir. Wes Anderson https://www.youtube.com/watch?v=GEuMnPl2WI4 TV Show: Arrested Development (2004-2019) - Fox/Netflix https://www.netflix.com/title/70140358 TV Show: The Office (2001-2003) - BBC h', 'https://traffic.megaphone.fm/GLT1154972783.mp3?updated=1772040002', 4774, '2025-06-24 03:07:00'::timestamptz, 40000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'S5 EP7: Danny Dyer describes battling addiction, UFO obsessions, and tackling Shakespeare', 'This week, Louis sits down with Danny Dyer, the Bafta-winning actor and all-round national treasure. The pair discuss Danny’s experience battling addiction while performing on stage, their shared fascination with UFOs, and whether Danny would ever do Shakespeare. Plus, Danny reveals what he really thinks about being described as ‘the people’s Louis Theroux’. Links/Attachments: Via – UK Drug and Alcohol Addiction Charity https://www.viaorg.uk/ TV Show: ‘Who Do You Think You Are? (2007 – Present) - BBC https://www.bbc.co.uk/programmes/b007t575 Book: Wolf Hall, Hilary Mantel (2009) https://www.am', 'https://traffic.megaphone.fm/GLT3648567667.mp3?updated=1772039991', 4892, '2025-06-16 23:00:00'::timestamptz, 41000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'S5 EP6: Ed Sheeran on squeezing Stormzy into his Mini, having breakfast with Van Morrison, and remaining normal', 'In this episode, Louis speaks to pop megastar Ed Sheeran. Joining Louis in the studio, Ed describes squeezing Stormzy into his Mini, a surprising breakfast with Van Morrison, and how to be normal when you’re one of the most famous people in the world. Warning: Strong language, as well as some adult themes. Links/Attachments: Album: ‘Play’, Ed Sheeran (2025) https://open.spotify.com/prerelease/096l4VGKXhhUHyjD8gh1tf Album: ‘Autumn Variations’, Ed Sheeran (2023) https://open.spotify.com/album/5LXOgcszGvUkYzYL4v6wYg Album: ‘Subtract’, Ed Sheeran (2023) https://open.spotify.com/album/2WFFcvzM0CgLa', 'https://traffic.megaphone.fm/GLT1428116279.mp3?updated=1772039963', 4979, '2025-06-09 23:00:00'::timestamptz, 42000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'S5 EP5: Little Simz discusses her new album, growing up with adopted siblings, and working with Drake', 'Louis is joined in the studio by Mercury Prize-winning rapper and actress, Little Simz. The pair discuss the inspiration behind her new album Lotus, growing up with adopted siblings and working with Drake on Top Boy. Prepare for awkward pauses and an unlikely rap collaboration. Warnings: Strong language, as well as some adult themes. Links/Attachments: Album: ''Sometimes I Might Be Introvert’, Little Simz (2021) https://open.spotify.com/album/0DBoWQ52XUHtrZQdfAqOVj Song: ‘Venom’, Little Simz (2019) https://open.spotify.com/album/3h7qY0r0PNgNUS838NqgGv Song: ‘WE PRAY'', Coldplay, Little Simz, Bur', 'https://traffic.megaphone.fm/GLT7981890915.mp3?updated=1772039922', 3514, '2025-06-02 23:00:00'::timestamptz, 43000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'S5 EP4: John Wilson on collaborating with Nathan Fielder, confronting a cult, and hating mockumentaries', 'Louis speaks to John Wilson, fellow documentarian and creator of the cult-favourite series, How To...with John Wilson. The pair swap stories about their respective work, including discussing John’s collaborations with writer and producer Nathan Fielder, how joining an acapella group exposed him to the NXIVM sex-cult, and their shared disdain for mockumentaries. Plus, John turns the tables on Louis… Warnings: Strong language and some adult themes. Links/Attachments: TV Show: ‘How To with John Wilson’ (2020-2023) - HBO https://www.bbc.co.uk/iplayer/episodes/p0cltlm3/how-to-with-john-wilson TV Sh', 'https://traffic.megaphone.fm/GLT8505416888.mp3?updated=1772039900', 4405, '2025-05-26 23:00:00'::timestamptz, 44000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'S5 EP3: Bryan Johnson discusses life-changing psychedelics, superintelligence, and night-time erections', 'In this episode, Louis is joined by tech entrepreneur turned longevity evangelist, Bryan Johnson. Dialling in from his home in Los Angeles, Bryan tells Louis all about his quest to live forever, from the psychedelic experience that changed his life, to the role of superintelligence in the future. Plus, Louis learns the importance of night-time erections. Warnings: Strong language and some adult themes. Links/Attachments: Mind – UK Mental Health Charity https://www.mind.org.uk/ Suicide Prevention UK https://spuk.org.uk/ Book: The Ghost in the Machine, Arthur Koestler (originally published in 19', 'https://traffic.megaphone.fm/GLT6512726818.mp3?updated=1772039865', 5143, '2025-05-19 23:26:00'::timestamptz, 45000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'S5 EP2: Sean Penn on dining with Jack Nicholson and Putin, run-ins with the paparazzi, and his relationship with Zelenskyy', 'Louis travels to Los Angeles to sit down with Hollywood heavyweight and international adventurer, Sean Penn. Renowned for award-winning roles in films like Milk, I Am Sam and Carlito’s Way, Sean discusses his colourful life and career, including dining with Jack Nicholson and Vladimir Putin in Moscow, his relationship with Ukrainian president Volodymyr Zelenskyy and his notorious run-ins with the paparazzi. Warnings: Strong language. Links/Attachments: Fast Times at Ridgemont High (1982) https://www.youtube.com/watch?v=vzva_I8WPAg Mystic River (2003) https://www.youtube.com/watch?v=W7NktJhrRYQ', 'https://traffic.megaphone.fm/GLT8418887847.mp3?updated=1772039835', 5074, '2025-05-13 02:15:00'::timestamptz, 46000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'S5 EP1: Bella Ramsey discusses being a child actor, dealing with critical fandoms and overcoming emetophobia', 'To kick off the new series, Louis is joined in the studio by Bella Ramsey, rising star of ‘Game of Thrones’ and ‘The Last of Us’. Bella delves into their experiences as a child actor, dealing with critical fandoms online, and their phobia of vomiting. Warnings: Some strong language and discussions of sensitive themes, including mental health issues and eating disorders. For further information and support, visit https://resources.byspotify.com/ Links/Attachments: BEAT – UK Eating Disorder Charity https://www.beateatingdisorders.org.uk/get-information-and-support/get-help-for-myself/i-need-supp', 'https://traffic.megaphone.fm/GLT3906855937.mp3?updated=1772039827', 4222, '2025-05-05 23:00:00'::timestamptz, 47000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Louis is back with the fifth season of his podcast!', 'It''s that time again... Louis returns for another series of his podcast. Join him weekly from May 6th as he delves into the lives of fascinating people from across the globe. Watch episodes exclusively on Spotify, or listen wherever you get your podcasts. Learn more about your ad choices. Visit podcastchoices.com/adchoices', 'https://traffic.megaphone.fm/GLT9341080712.mp3?updated=1745870447', 78, '2025-04-28 23:00:00'::timestamptz, 48000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'S4 EP7: Sean Evans discusses his upbringing in Chicago, interview techniques, and no-go guests on ‘Hot Ones’', 'Louis speaks to Sean Evans, the host of Youtube smash-hit ‘Hot Ones’. Dialling in from New York, the pair swap interview techniques, as well as discussing Sean’s upbringing in Chicago and how he utilised chicken wings to create one of the biggest talk shows in the world. Plus, Sean lets Louis know which celebrities were ratings hits and who he’d never have on the show... Warnings: Strong language. Links/Attachments: YouTube: Louis Theroux (me) reacts to his (my) ‘Hot Ones’ episode (2025) https://www.youtube.com/watch?v=x_WT5kxyZ1I YouTube Series: Louis Theroux Attacks the Shark While Eating Sp', 'https://traffic.megaphone.fm/GLT8607904932.mp3?updated=1772039535', 4612, '2025-02-25 00:00:00'::timestamptz, 49000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'S4 EP6: Sharon Horgan on the sadness of comedy, living in squats and FaceTiming Bono', 'Louis sits down in the Spotify studio with Irish actor, writer, and director Sharon Horgan. Sharon discusses her colourful years squatting in London, the fine line between comedy and tragedy, and FaceTiming with Bono while filming Bad Sisters 2. She also spills the beans about almost starring in a Woody Allen film… Warnings: Strong language. ⁠Links/Attachments: TV Show: ‘Bad Sisters’ (2022-2025) - AppleTV+ https://tv.apple.com/gb/show/bad-sisters/umc.cmc.14kr4vv65unannh7doqgvlh20 Film: Home Alone (1990) https://youtu.be/jEDaVHmw7r4?si=rfeHfnepM2T1YCCQ TV Show: ‘Catastrophe’ (2015-2019) - Chann', 'https://traffic.megaphone.fm/GLT9619381941.mp3?updated=1772039496', 4360, '2025-02-18 00:00:00'::timestamptz, 50000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'S4 EP5: Armie Hammer discusses allegations against him, being shunned by famous friends, and his unconventional family history', 'Louis speaks to actor, podcast host and figure of some controversy, Armie Hammer. Dialing in from his new apartment in downtown LA, Armie and Louis discuss the allegations against him, being shunned by famous friends and his unconventional family history. Warnings: Strong language and graphic sexual content, as well as discussions of sensitive themes, including sexual abuse. For further information and support, visit https://resources.byspotify.com/. Links/Attachments: ‘Armie Hammer Breaks His Silence’ – Air Mail https://airmail.news/issues/2023-2-4/armie-hammer-breaks-his-silence Podcast: ‘Th', 'https://traffic.megaphone.fm/GLT5053954861.mp3?updated=1772039468', 4610, '2025-02-11 00:00:00'::timestamptz, 51000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'S4 EP4: Leon Edwards on rubbing shoulders with Andrew Tate, the time Donald Trump saw him fight, and how MMA saved his life', 'Louis is joined in the studio by MMA fighter and UFC welterweight champion, Leon ‘Rocky’ Edwards. Leon talks about rubbing shoulders with Andrew Tate, how MMA saved him from a life of crime and what happened when Donald Trump came to see him fight. Plus, Leon puts Louis’s physical strength to the test… Warnings: Strong language and adult themes Links/Attachments: ‘MMA Fighting’s 2022 Knockout of the Year: Leon Edwards vs. Kamaru Usman’ - MMA Fighting https://www.mmafighting.com/2022/12/25/23524649/mma-fightings-2022-knockout-of-the-year-leon-edwards-vs-kamaru-usman UFC Welterweight Ranking htt', 'https://traffic.megaphone.fm/GLT9104977046.mp3?updated=1772039447', 3979, '2025-02-04 00:00:00'::timestamptz, 52000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'S4 EP3: Jamie Oliver on public feuds, chopping his finger off on live TV, and his controversial jerk rice', 'In this episode, Louis is joined by celebrity chef and best–selling cookbook author, Jamie Oliver. Jamie tells Louis about his public feuds with Gordon Ramsey and Anthony Bourdain, chopping part of his finger off on live TV, and why his jerk rice caused such a stir. Plus, Louis provides some recipe tips… Warnings: Strong language, as well as discussion around food production that may upset some listeners. Visit spotify.com/resources for information and resources. Links/Attachments: TV Show: ‘The Naked Chef’ (1999) – BBC https://www.youtube.com/watch?v=4-CeoHHDYw8 TV Show: ‘Louis Theroux’s Weir', 'https://traffic.megaphone.fm/GLT9203921825.mp3?updated=1772039414', 4279, '2025-01-28 00:00:00'::timestamptz, 53000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'S4 EP2: Jade Thirlwall discusses being ghosted by Harry Styles, clashing with the Gallaghers and coming up on X-Factor', 'Louis sits down with pop-star and former member of Little Mix, Jade Thirlwall. Jade tells Louis about being ghosted by Harry Styles, clashing with the Gallaghers and coming to the public’s attention on X-Factor. Warnings: Some strong language and discussions of sensitive themes, including mental health issues and eating disorders. For further information and support, visit https://resources.byspotify.com/ Links/Attachments: BEAT – UK Eating Disorder Charity https://www.beateatingdisorders.org.uk/get-information-and-support/get-help-for-myself/i-need-support-now/helplines/ TV Show: ‘The X Facto', 'https://traffic.megaphone.fm/GLT4845979998.mp3?updated=1772039390', 4317, '2025-01-21 00:00:00'::timestamptz, 54000);
END $$;

-- ---------- CNN 5 Things ----------
DO $$
DECLARE
  v_host_id uuid;
  v_pod_id uuid;
  v_cat uuid;
BEGIN
  SELECT id INTO v_cat FROM categories WHERE name_ar = 'ثقافة وأدب' LIMIT 1;
  INSERT INTO hosts (name_ar, slug, photo_url, cover_url, title_ar, specialty_ar, bio_ar, country, category_id, is_verified, followers_count)
  VALUES ('CNN Podcasts', 'cnn-5-things', 'https://is1-ssl.mzstatic.com/image/thumb/Podcasts211/v4/b4/bb/35/b4bb3524-380c-7e63-c799-5c0203559cf8/mza_13140286244608796188.jpg/600x600bb.jpg', 'https://is1-ssl.mzstatic.com/image/thumb/Podcasts211/v4/b4/bb/35/b4bb3524-380c-7e63-c799-5c0203559cf8/mza_13140286244608796188.jpg/600x600bb.jpg', 'مقدم', 'ثقافة وأدب', 'بودكاست حقيقي: CNN 5 Things', 'أونلاين', v_cat, true, 50000)
  RETURNING id INTO v_host_id;

  INSERT INTO podcasts (title, description, host_id, category_id, type, cover_url, audience_level, plays_count, rating_avg)
  VALUES ('CNN 5 Things', 'Monday through Friday get up to speed on the biggest headlines of the day with 5 Things. On Saturdays, get a break for your ears with good news from 5 Good Things. And at noon and Sundays, we take you beyond the headlines to help make sense of what everyone is talking about in politics and beyond with One Thing.', v_host_id, v_cat, 'cultural', 'https://is1-ssl.mzstatic.com/image/thumb/Podcasts211/v4/b4/bb/35/b4bb3524-380c-7e63-c799-5c0203559cf8/mza_13140286244608796188.jpg/600x600bb.jpg', 'beginner', 100000, 4.7)
  RETURNING id INTO v_pod_id;

  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'NSA Resolves Major Network Outage', 'A classified internal communications network is back online after nearly four days. Democrats may be gearing up for a legal showdown against the Trump administration over fears of destroyed documents. Russia launched a massive wave of deadly strikes on Ukraine hours after historic trilateral talks. The timeline to close New York City’s notorious Rikers Island jail is getting pushed back. Plus, Anthropic’s staff hit a massive payday. Learn more about your ad choices. Visit podcastchoices.com/adchoices', 'https://www.podtrac.com/pts/redirect.mp3/pdst.fm/e/swap.fm/track/2nzGkisFXQswLYT5s325/traffic.megaphone.fm/WMHY4295829082.mp3', 431, '2026-11-20 18:47:00'::timestamptz, 5000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Tributes Pour In for Fiona the Hippo', 'National cyber director fired and another cyber nominee grilled at Senate hearing. Army delays Iowa detonation that would emit lead dust. Cincinnati zoo mourns Fiona the hippo. Prosecutors charge 14 people for brazen train heists. How Scott Colom got Nike to give new Air Force 1''s to every high school valedictorian. Learn more about your ad choices. Visit podcastchoices.com/adchoices', 'https://www.podtrac.com/pts/redirect.mp3/pdst.fm/e/swap.fm/track/2nzGkisFXQswLYT5s325/traffic.megaphone.fm/WMHY7754296874.mp3', 574, '2026-11-20 12:05:00'::timestamptz, 6000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Trump Wraps Up Trilateral Summit with Xi and Putin', 'US envoy Jared Kushner shares President Donald Trump’s takeaway from talks with his counterparts in China. Trump tells Americans to “relax” after a week of tech outages. A parole board denied Susan Smith’s latest push for release. Homebuyers just took another hit. Plus, the first reviews for Grand Theft Auto VI are in. Learn more about your ad choices. Visit podcastchoices.com/adchoices', 'https://www.podtrac.com/pts/redirect.mp3/pdst.fm/e/swap.fm/track/2nzGkisFXQswLYT5s325/traffic.megaphone.fm/WMHY7530876046.mp3', 444, '2026-11-19 21:57:00'::timestamptz, 7000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Wall Street Welcomes Anthropic', 'As President Donald Trump returns to the US from a China, another round of peace talks are underway in Berlin. Anthropic employees are celebrating the company’s long-awaited IPO. A major IT outage is still sidelining NSA workers - and now disrupting a key intelligence hub. The UN’s top court has issued a historic judgement on atrocities committed against Myanmar’s Rohingya minority. Plus, why the US Army plans to detonate five tons of unstable bomb-making chemicals in Iowa. Learn more about your ad choices. Visit podcastchoices.com/adchoices', 'https://www.podtrac.com/pts/redirect.mp3/pdst.fm/e/swap.fm/track/2nzGkisFXQswLYT5s325/traffic.megaphone.fm/WMHY5532437273.mp3', 496, '2026-11-19 17:09:00'::timestamptz, 8000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Trump''s Historic Talks with Putin, Xi', 'Trump touts close relationships with Xi, Putin at historic talks. Anthropic''s record-breaking IPO. Storm systems causing flooding in CA and FL could impact Thanksgiving travel. Jeffries wins speaker vote as Dems put Trump officials and family members on notice. And say goodbye to the gamers in your life as Grand Theft Auto VI just went live.&amp;nbsp; Learn more about your ad choices. Visit podcastchoices.com/adchoices', 'https://www.podtrac.com/pts/redirect.mp3/pdst.fm/e/swap.fm/track/2nzGkisFXQswLYT5s325/traffic.megaphone.fm/WMHY9834104166.mp3', 572, '2026-11-19 12:04:00'::timestamptz, 9000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Officials Face Questions on Global Threats', 'Lawmakers grilled top Trump administration officials on recent tech outages. House Democrats nominated Hakeem Jeffries for speaker despite threats from incoming progressives. US envoys Steve Witkoff and Jared Kushner head to Germany for another round of Ukraine peace talks. Anthropic’s Wall Street debut tomorrow marks a new chapter for AI. Plus, NASA’s spacecraft just made history again. Learn more about your ad choices. Visit podcastchoices.com/adchoices', 'https://www.podtrac.com/pts/redirect.mp3/pdst.fm/e/swap.fm/track/2nzGkisFXQswLYT5s325/traffic.megaphone.fm/WMHY1631742496.mp3', 482, '2026-11-18 21:53:00'::timestamptz, 10000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Trump Returns to China', 'Chinese leader Xi Jinping gives President Donald Trump an unprecedented airport greeting ahead of an annual regional economic summit. Iran is expanding its attacks across the Gulf region following a US strike inside Iran. Parts of coastal Florida are bracing for more rain after days of persistent downpours and flooding. The White House dropped Trump’s latest pick to lead the Food and Drug Administration. Plus, Cambridge Dictionary has announced its word of the year. Learn more about your ad choices. Visit podcastchoices.com/adchoices', 'https://www.podtrac.com/pts/redirect.mp3/pdst.fm/e/swap.fm/track/2nzGkisFXQswLYT5s325/traffic.megaphone.fm/WMHY1107949972.mp3', 485, '2026-11-18 17:02:00'::timestamptz, 11000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Democrat Mary Peltola Wins Alaska Senate Race', 'DNI blames software patch for outage of highly classified network. Democrat Mary Peltola flips Alaska Senate seat, ousting Republican incumbent Dan Sullivan. NVIDIA board shuts down talk of Jensen Huang return. Waymo pulled off highways after California ban. And the 100 million crab migration. Learn more about your ad choices. Visit podcastchoices.com/adchoices', 'https://www.podtrac.com/pts/redirect.mp3/pdst.fm/e/swap.fm/track/2nzGkisFXQswLYT5s325/traffic.megaphone.fm/WMHY8053816939.mp3', 530, '2026-11-18 12:06:00'::timestamptz, 12000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'The Latest Tech Failure', 'A classified communications network at the National Security Agency goes down. Some Senate Republicans push back on a $50 billion air traffic control request. Jensen Huang says he’d be “honored” to be reinstated as Nvidia CEO. The US officially loses its measles elimination status. Plus, shoppers pull back on big-ticket items ahead of the holidays. Learn more about your ad choices. Visit podcastchoices.com/adchoices', 'https://www.podtrac.com/pts/redirect.mp3/pdst.fm/e/swap.fm/track/2nzGkisFXQswLYT5s325/traffic.megaphone.fm/WMHY4519207916.mp3', 454, '2026-11-17 21:48:00'::timestamptz, 13000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
