  VALUES (v_pod_id, 'Security Guard Stops Gunman At Office Complex', 'Dems look to deliver on affordability. GOP looks for new leadership as Vance blames the Iran war for election losses. Security guard stops gunman who drove into office complex. Melania Trump hosting Ukraine and Russia at the White House. And the world''s best restaurant is...&amp;nbsp; Learn more about your ad choices. Visit podcastchoices.com/adchoices', 'https://www.podtrac.com/pts/redirect.mp3/pdst.fm/e/swap.fm/track/2nzGkisFXQswLYT5s325/traffic.megaphone.fm/WMHY1009126882.mp3', 492, '2026-11-05 12:09:00'::timestamptz, 43000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Trump Reacts to Massive GOP Election Defeat', 'President Donald Trump and Vice President JD Vance share what they thought attributed to Republican midterm losses. House Speaker Mike Johnson says he’s stepping aside from a GOP leadership position in the next Congress. Wall Street votes "yes" on the midterm results. The nation’s largest drugstore retailer is breaking up its health care empire. And, how a woman’s first marathon came to a tragic end. Learn more about your ad choices. Visit podcastchoices.com/adchoices', 'https://www.podtrac.com/pts/redirect.mp3/pdst.fm/e/swap.fm/track/2nzGkisFXQswLYT5s325/traffic.megaphone.fm/WMHY9584172856.mp3', 411, '2026-11-04 22:02:00'::timestamptz, 44000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'What We Can Learn from Democrat''s ''Blue-Nami''', 'Democrats retook both the House and Senate after romping through multiple deep-red states in a historic midterm election. Is this a product of President Donald Trump’s historic unpopularity, or a more fundamental reshaping of our politics? We take stock of the map and how Democrats could approach being in the majority for the final two years of Trump’s term.&amp;nbsp; ---&amp;nbsp; Guest: David Chalian, CNN Washington Bureau Chief/Political Director&amp;nbsp; Host: David Rind&amp;nbsp; Producer: Paola Ortiz&amp;nbsp; Showrunner: Felicia Patinkin&amp;nbsp; Learn more about your ad choices. Visi', 'https://www.podtrac.com/pts/redirect.mp3/pdst.fm/e/swap.fm/track/2nzGkisFXQswLYT5s325/traffic.megaphone.fm/WMHY8925002361.mp3', 850, '2026-11-04 16:57:00'::timestamptz, 45000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Key Takeaways From Historic Midterms', 'Hear from Dems who flipped senate seats. Historic firsts in governor''s races. Trump points the blame elsewhere after stunning rebuke from voters. And how voters weighed in on ballot measures for recreational marijuana and billionaire taxes. Learn more about your ad choices. Visit podcastchoices.com/adchoices', 'https://www.podtrac.com/pts/redirect.mp3/pdst.fm/e/swap.fm/track/2nzGkisFXQswLYT5s325/traffic.megaphone.fm/WMHY7330478955.mp3', 634, '2026-11-04 12:04:00'::timestamptz, 46000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'High-Stakes Fight for Congress Begins', 'Ballot issues are being reported in some areas with pivotal elections. President Donald Trump says he’s ending billions in US aid to Israel. A nine-day manhunt for a convicted murderer who escaped prison is over. Bomb threats disrupt travel across Europe. Plus, why “mogging” is officially having a moment. Learn more about your ad choices. Visit podcastchoices.com/adchoices', 'https://www.podtrac.com/pts/redirect.mp3/pdst.fm/e/swap.fm/track/2nzGkisFXQswLYT5s325/traffic.megaphone.fm/WMHY4748456930.mp3', 408, '2026-11-03 21:47:00'::timestamptz, 47000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Split Ticket Voters: The Mood in Michigan', 'Election Day voting is underway across the country, with control of the House and Senate on the line. We check in on a polling place in Michigan, where some voters are splitting their ticket amid Democratic drama in the key Senate race. ---&amp;nbsp; Guest: Sunlen Serfaty, CNN Correspondent&amp;nbsp; Host: David Rind&amp;nbsp; Producer: Paola Ortiz&amp;nbsp; Showrunner: Felicia Patinkin&amp;nbsp; Editorial Support: Nicky Robertson Learn more about your ad choices. Visit podcastchoices.com/adchoices', 'https://www.podtrac.com/pts/redirect.mp3/pdst.fm/e/swap.fm/track/2nzGkisFXQswLYT5s325/traffic.megaphone.fm/WMHY6242717979.mp3', 688, '2026-11-03 17:25:00'::timestamptz, 48000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Election Day In America!', 'Balance of power on the line as polls open. Supreme Court rejects Trump administration effort to force CA to set aside 20,000 ballots. Storm moves east after deadly flooding in Southwest. Plane crash victims identified. English adventurer returns home after 28 years and 31,000 miles around the world. Learn more about your ad choices. Visit podcastchoices.com/adchoices', 'https://www.podtrac.com/pts/redirect.mp3/pdst.fm/e/swap.fm/track/2nzGkisFXQswLYT5s325/traffic.megaphone.fm/WMHY8285628176.mp3', 559, '2026-11-03 12:16:00'::timestamptz, 49000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Private Jet Nosedives into Road in Florida', 'President Donald Trump wrapped up his midterm campaign with closing remarks at the Reflecting Pool. Some House Republicans are privately pushing to boot Rep. Haley Stevens after her controversial endorsement switch. Rain could impact voter turnout in key races. Federal investigators are trying to determine the cause of a fiery crash in Florida that left behind a massive crater. And, a judge in the Lindsay Clancy triple-murder trial has proposed a timeline for a potential retrial. Learn more about your ad choices. Visit podcastchoices.com/adchoices', 'https://www.podtrac.com/pts/redirect.mp3/pdst.fm/e/swap.fm/track/2nzGkisFXQswLYT5s325/traffic.megaphone.fm/WMHY6175419328.mp3', 458, '2026-11-02 22:46:00'::timestamptz, 50000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'How Do You Plan Against Election Threats from...the Federal Government?', 'Election officials across the country have been preparing for every possible disruption ahead of Election Day – including meddling from the Trump administration. With just hours to go before polls open, we examine the mood amongst officials and how they are training their workers to interact with federal poll monitors. ---&amp;nbsp; Guest: Gabe Cohen, CNN Correspondent&amp;nbsp; Host: David Rind&amp;nbsp; Producer: Paola Ortiz&amp;nbsp; Showrunner: Felicia Patinkin&amp;nbsp; Editorial Support: Maddie Marshall, Marshall Cohen Learn more about your ad choices. Visit podcastchoices.com/adchoices', 'https://www.podtrac.com/pts/redirect.mp3/pdst.fm/e/swap.fm/track/2nzGkisFXQswLYT5s325/traffic.megaphone.fm/WMHY7248355096.mp3', 930, '2026-11-02 16:59:00'::timestamptz, 51000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Haley Stevens Tries To Explain Her Rogers Endorsement in CNN Interview', 'Democrat Haley Stevens speaks to CNN about decision to endorse Republican Mike Rogers in MI Senate race. Trump to deliver final midterm speech at Reflecting Pool. Deadly plane crash in Florida. Ukrainian families reunite thanks to temporary truce brokered by Melania Trump. Paramedic reunites with preemie she saved. Learn more about your ad choices. Visit podcastchoices.com/adchoices', 'https://www.podtrac.com/pts/redirect.mp3/pdst.fm/e/swap.fm/track/2nzGkisFXQswLYT5s325/traffic.megaphone.fm/WMHY4489030732.mp3', 607, '2026-11-02 11:43:00'::timestamptz, 52000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Is MAHA Due for a Makeover?', 'Health issues like vaccines and pesticides have emerged as pressing midterm issues in some key battleground states, scrambling traditional political lines. But it comes as the broader ''Make America Healthy Again’ movement is dealing with fractures that could imperil the momentum that helped propel President Donald Trump back to the White House in 2024. We explore politicians from both sides of the aisle are trying to win over disaffected MAHA voters across the country.&amp;nbsp; ---&amp;nbsp; Guest: Sarah Owermohle, CNN Reporter&amp;nbsp; Host: David Rind&amp;nbsp; Producer: Paola Ortiz&amp;nb', 'https://www.podtrac.com/pts/redirect.mp3/pdst.fm/e/swap.fm/track/2nzGkisFXQswLYT5s325/traffic.megaphone.fm/WMHY9826220458.mp3', 1251, '2026-11-01 09:30:00'::timestamptz, 53000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Bet You Didn’t Know This About Halloween', 'A social experiment involving hundreds of phone calls is challenging assumptions about how divided the US is. He’s explored all seven continents by wheelchair, overcoming the odds and hoping to inspire millions to do the same. Hear just how successful a first-of-its-kind cancer vaccine was.&amp;nbsp;How running became a lifeline for a New York City marathoner experiencing homelessness. Plus,&amp;nbsp;some of Halloween’s most beloved traditions have surprisingly strange origins. &amp;nbsp; Host/Producer: Krista Bo Polanco&amp;nbsp; Producer: Eryn Mathewson&amp;nbsp; Showrunner: Felicia Patinkin', 'https://www.podtrac.com/pts/redirect.mp3/pdst.fm/e/swap.fm/track/2nzGkisFXQswLYT5s325/traffic.megaphone.fm/WMHY4847400177.mp3', 1188, '2026-10-31 08:30:00'::timestamptz, 54000);
END $$;

-- ---------- The ArsenalVision Podcast - Arsenal FC ----------
DO $$
DECLARE
  v_host_id uuid;
  v_pod_id uuid;
  v_cat uuid;
BEGIN
  SELECT id INTO v_cat FROM categories WHERE name_ar = 'ثقافة وأدب' LIMIT 1;
  INSERT INTO hosts (name_ar, slug, photo_url, cover_url, title_ar, specialty_ar, bio_ar, country, category_id, is_verified, followers_count)
  VALUES ('ArsenalVision Podcast LLC', 'the-arsenalvision-podcast-arsenal-fc', 'https://is1-ssl.mzstatic.com/image/thumb/Podcasts211/v4/c8/26/d1/c826d172-cbe8-a0a4-ec29-9d8be2ca1465/mza_268114483940059750.jpg/600x600bb.jpg', 'https://is1-ssl.mzstatic.com/image/thumb/Podcasts211/v4/c8/26/d1/c826d172-cbe8-a0a4-ec29-9d8be2ca1465/mza_268114483940059750.jpg/600x600bb.jpg', 'مقدم', 'ثقافة وأدب', 'بودكاست حقيقي: The ArsenalVision Podcast - Arsenal FC', 'أونلاين', v_cat, true, 50000)
  RETURNING id INTO v_host_id;

  INSERT INTO podcasts (title, description, host_id, category_id, type, cover_url, audience_level, plays_count, rating_avg)
  VALUES ('The ArsenalVision Podcast - Arsenal FC', 'Twice weekly Arsenal podcast covering the latest news, performances, tactics and more with thoughtfulness and a bit of humor. Interested in advertising on this podcast? Email sales@bluewirepods.com!', v_host_id, v_cat, 'cultural', 'https://is1-ssl.mzstatic.com/image/thumb/Podcasts211/v4/c8/26/d1/c826d172-cbe8-a0a4-ec29-9d8be2ca1465/mza_268114483940059750.jpg/600x600bb.jpg', 'beginner', 100000, 4.7)
  RETURNING id INTO v_pod_id;

  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Are Alex Scott, Odegaard and Havertz Arsenal’s Next Big Squad Decisions?', 'On this edition of the ArsenalVision Podcast, Elliot is joined by Paul to discuss rumours that Bournemouth are softening their stance on selling Alex Scott and what a move could mean for Zubimendi and Myles Lewis-Skelly, debate the Odegaard and Havertz contract calls, and preview the trip to Newcastle. Chapters: 00:00 Intro Music 05:56 Bournemouth Softening on Alex Scott? 10:25 Zubimendi Out, Alex Scott In? 18:20 What Scott Means for Myles Lewis-Skelly 23:08 Can Myles Cover Enough Ground? 30:19 Sign Scott Even If It Costs Us Myles? 36:48 Contract Renewals: Keeping the Squad Together 43:42 Re-S', 'https://prfx.byspotify.com/e/pscrb.fm/rss/p/mgln.ai/e/256/bluewire.simplecastaudio.com/8bbbd80a-92c8-48e6-a618-34e8e1a0bc59/episodes/a49534b6-99bc-4dd5-9cf7-4622865571ed/audio/128/default.mp3?aid=rss_feed&amp;awCollectionId=8bbbd80a-92c8-48e6-a618-34e8e1a0bc59&amp;awEpisodeId=a49534b6-99bc-4dd5-9cf7-4622865571ed&amp;feed=sjbSL_pM', 3726, '2026-11-19 16:23:22'::timestamptz, 5000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Ben White&apos;s Last Laugh &amp; Arsenal&apos;s Transfer Market Conundrum', 'On this edition of the ArsenalVision Podcast, Elliot is joined by Tim to send love to Andrew, celebrate Ben White''s big night in England''s win over Spain, map out the run of games that could define Arsenal''s season, and debate whether Arsenal should pay up for a forward like Antonio Nusa in January. Chapter timings below. Chapters: 00:00 Intro Music 03:07 Love and Support for Andrew 06:20 Ben White''s Big Night Against Spain 07:51 Doorbell Music 09:45 How the Media Covered Ben White 19:28 England Beat Spain: The Arsenal Angle 27:53 The Run That Could Define the Season 32:48 Where Can Arsenal Af', 'https://prfx.byspotify.com/e/pscrb.fm/rss/p/mgln.ai/e/256/bluewire.simplecastaudio.com/8bbbd80a-92c8-48e6-a618-34e8e1a0bc59/episodes/b8bb8702-b1a9-4af9-9597-605dad461511/audio/128/default.mp3?aid=rss_feed&amp;awCollectionId=8bbbd80a-92c8-48e6-a618-34e8e1a0bc59&amp;awEpisodeId=b8bb8702-b1a9-4af9-9597-605dad461511&amp;feed=sjbSL_pM', 4341, '2026-11-16 16:25:52'::timestamptz, 6000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Arsenal&apos;s Former Fitness Chief on Saka, Injuries and the Calendar', 'On this edition of the ArsenalVision Podcast, Elliot is joined by Darren Burgess, Juventus Director of Performance and Arsenal''s former Head of High Performance, to talk about who really decides when a player is fit, whether the football calendar can be managed at all, how training and rotation have changed, and what it all means for young stars like Bukayo Saka and Max Dowman. Chapter timings below. Chapters: 00:00 Intro Music 02:46 From 93 Rejection Letters to the World Cup 07:57 Arsenal''s Move Away From the Wenger Model 11:46 Bringing Data Into Elite Performance 16:14 Who Decides If a Playe', 'https://prfx.byspotify.com/e/pscrb.fm/rss/p/mgln.ai/e/256/bluewire.simplecastaudio.com/8bbbd80a-92c8-48e6-a618-34e8e1a0bc59/episodes/fb889c85-8de2-4f49-b31e-97fb51fefbb1/audio/128/default.mp3?aid=rss_feed&amp;awCollectionId=8bbbd80a-92c8-48e6-a618-34e8e1a0bc59&amp;awEpisodeId=fb889c85-8de2-4f49-b31e-97fb51fefbb1&amp;feed=sjbSL_pM', 3440, '2026-11-12 06:00:00'::timestamptz, 7000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Hilarious and Consequential Premier League Weekend For Arsenal', 'On this edition of the ArsenalVision Podcast, Elliot is joined by Tim and Paul to enjoy a chaotic weekend for Arsenal''s rivals and break down the 1-0 win over Hull, from Madueke''s standout display and the chances that went begging to Havertz, Tzolis and a midfield still finding its balance, before looking ahead to the tough run after the international break. Chapter timings below. Chapters: 00:00 Intro Music 03:41 Emery Storms Off and a Chaotic Weekend 14:12 City Lose at Forest: Sizing Up the Title Race 19:27 Hull: Grinding Out a Win on a Short Week 25:34 21 Shots, Missed Chances and the Perfe', 'https://prfx.byspotify.com/e/pscrb.fm/rss/p/mgln.ai/e/256/bluewire.simplecastaudio.com/8bbbd80a-92c8-48e6-a618-34e8e1a0bc59/episodes/eee76b23-1b11-4c67-a9f8-d94dd7f9a78a/audio/128/default.mp3?aid=rss_feed&amp;awCollectionId=8bbbd80a-92c8-48e6-a618-34e8e1a0bc59&amp;awEpisodeId=eee76b23-1b11-4c67-a9f8-d94dd7f9a78a&amp;feed=sjbSL_pM', 4265, '2026-11-09 15:55:21'::timestamptz, 8000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Arsenal Win Game of Two Halves but Much Bigger Tests Lie Ahead', 'On this edition of the ArsenalVision Podcast, Elliot is joined by Clive to break down Arsenal''s 2-1 win at Slavia Prague, from a sharp first half for Gyokeres and Madueke to a sloppy second half, Arteta''s rotation calls and Saliba''s return, and to preview Saturday''s game against Hull. Chapter timings below. Chapters: 00:00 Intro Music 04:37 Why Clive Loved It From the Pub 07:04 A Win in Prague, but Arteta Isn''t Happy 12:43 A Loaded Bench and the Race for the Top Two 17:15 Gyokeres and Madueke Deliver 23:07 Zubimendi and Merino Get Their Chance 26:59 Eze Just Needs One to Go In 28:48 Second Hal', 'https://prfx.byspotify.com/e/pscrb.fm/rss/p/mgln.ai/e/256/bluewire.simplecastaudio.com/8bbbd80a-92c8-48e6-a618-34e8e1a0bc59/episodes/08baa0c9-7181-46c6-aa61-4d9c65bd72ce/audio/128/default.mp3?aid=rss_feed&amp;awCollectionId=8bbbd80a-92c8-48e6-a618-34e8e1a0bc59&amp;awEpisodeId=08baa0c9-7181-46c6-aa61-4d9c65bd72ce&amp;feed=sjbSL_pM', 4135, '2026-11-05 16:17:36'::timestamptz, 9000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Arsenal End Anfield Drought With Quality and Composure', 'On this edition of the ArsenalVision Podcast, Elliot is joined by Tim and Tayo Popoola to celebrate Arsenal''s 1-0 win at Anfield, the first there in 14 years, from Kai Havertz''s winner and another defensive masterclass to Bruno''s role, Tzolis''s start and what the result means for the title race. Chapter timings below. Chapters: 00:00 Intro Music 05:02 Breaking the Anfield Jinx: How Good Was That? 18:14 A Big Shot Fired in the Title Race 22:52 Beating Liverpool''s Press, Sloppy in Execution 27:55 Bruno Guimaraes or Myles Lewis-Skelly at Anfield 34:28 Where Bruno Fits in Arsenal''s Midfield 42:01 ', 'https://prfx.byspotify.com/e/pscrb.fm/rss/p/mgln.ai/e/256/bluewire.simplecastaudio.com/8bbbd80a-92c8-48e6-a618-34e8e1a0bc59/episodes/7916465d-af21-4bf4-8c89-b204ffbfca7f/audio/128/default.mp3?aid=rss_feed&amp;awCollectionId=8bbbd80a-92c8-48e6-a618-34e8e1a0bc59&amp;awEpisodeId=7916465d-af21-4bf4-8c89-b204ffbfca7f&amp;feed=sjbSL_pM', 5842, '2026-11-02 16:52:16'::timestamptz, 10000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Fleetwood Fallout, Max Dowman&apos;s Red &amp; Liverpool vs Arsenal Preview', 'On this edition of the ArsenalVision Podcast, Elliot is joined by Clive and Paul to discuss Arsenal''s League Cup exit on penalties at Fleetwood Town, Max Dowman''s red card and Arteta''s reaction, and what the extra rest could mean for the season, before previewing Sunday''s trip to Anfield. Chapter timings below. Chapters: 00:00 Intro Music 05:15 How Bad Was Losing to Fleetwood? 08:01 Ten Changes and the Effort Question 12:27 Is This a Black Eye for the Club? 20:00 Havertz and Gyokeres Misfire 29:00 Should Max Dowman Have Been Sent Off? 37:41 Arteta''s Reaction to Dowman''s Red 44:29 Is Dowman Get', 'https://prfx.byspotify.com/e/pscrb.fm/rss/p/mgln.ai/e/256/bluewire.simplecastaudio.com/8bbbd80a-92c8-48e6-a618-34e8e1a0bc59/episodes/029a5ea1-1264-4d7c-bb18-c78ab25981f0/audio/128/default.mp3?aid=rss_feed&amp;awCollectionId=8bbbd80a-92c8-48e6-a618-34e8e1a0bc59&amp;awEpisodeId=029a5ea1-1264-4d7c-bb18-c78ab25981f0&amp;feed=sjbSL_pM', 4993, '2026-10-29 18:12:19'::timestamptz, 11000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Squad Depth Powers Arsenal To Comfortable Everton Win', 'On this edition of the ArsenalVision Podcast, Elliot is joined by Poz and Clive to discuss Arsenal''s 2-0 win over Everton, from Arteta''s rotation and the return of the set-piece goal to Rice and Odegaard in midfield, a front three finding form and Myles Lewis-Skelly''s quiet brilliance. They also look ahead to Fleetwood in the League Cup and the trip to Anfield. Chapter timings below. Chapters: 00:00 Intro Music 05:33 How Good Was That? Arsenal 2-0 Everton 10:59 The Day the First XI Died 18:29 Has the Title Freed Arteta to Rotate? 24:35 A Set-Piece Goal, Finally 28:39 Gabriel''s Scare and the Ko', 'https://prfx.byspotify.com/e/pscrb.fm/rss/p/mgln.ai/e/256/bluewire.simplecastaudio.com/8bbbd80a-92c8-48e6-a618-34e8e1a0bc59/episodes/a7c282b2-a6e2-4e67-8b35-20cbd1fc6e33/audio/128/default.mp3?aid=rss_feed&amp;awCollectionId=8bbbd80a-92c8-48e6-a618-34e8e1a0bc59&amp;awEpisodeId=a7c282b2-a6e2-4e67-8b35-20cbd1fc6e33&amp;feed=sjbSL_pM', 4889, '2026-10-26 05:00:00'::timestamptz, 12000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Arsenal Hold Bayern at the Allianz, but What Does Losing Saka Cost?', 'On this edition of the ArsenalVision Podcast, Elliot is joined by Kaya Kaynak and Michael Timbs to discuss Arsenal''s 2-2 draw with Bayern Munich at the Allianz, from Saka''s injury and the nights Eze and Madueke had to Kane''s role, the midfield balance and Gyokeres putting his hand up. They also look around Europe and preview Everton at the Emirates. Chapter timings below. Chapters: 00:00 Intro Music 03:52 A Point at the Allianz: How Good Was That? 12:07 Saka''s Injury and What We Know 18:22 Rotation, Blame and Life Without Saka 24:26 Eze''s Big Night at the Allianz 31:41 Madueke Gets His Flowers', 'https://prfx.byspotify.com/e/pscrb.fm/rss/p/mgln.ai/e/256/bluewire.simplecastaudio.com/8bbbd80a-92c8-48e6-a618-34e8e1a0bc59/episodes/07d45199-12aa-4794-bccb-76aa4e6d0bc4/audio/128/default.mp3?aid=rss_feed&amp;awCollectionId=8bbbd80a-92c8-48e6-a618-34e8e1a0bc59&amp;awEpisodeId=07d45199-12aa-4794-bccb-76aa4e6d0bc4&amp;feed=sjbSL_pM', 4878, '2026-10-22 15:57:56'::timestamptz, 13000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Is Narrow Forest Win The Hallmark of Champions or Cause For Concern?', 'On this edition of the ArsenalVision Podcast, Elliot is joined by Tim and Clive to discuss Arsenal''s 1-0 win at Forest, from the blunt first half and Madueke''s impact off the bench to the triple sub, the centre backs and the late chances we gave away. They also weigh up Man City''s perfect start and preview the trip to Bayern Munich. Chapter timings below. Chapters: 00:00 Intro Music 04:40 One Shot on Target: Champions or Warning Sign? 12:17 Breaking Down Forest''s Christmas Tree 18:00 Too Patient, Not Threatening Enough? 24:25 Talent vs Tactics and the Shots on Target Myth 32:16 Full-Back Balan', 'https://prfx.byspotify.com/e/pscrb.fm/rss/p/mgln.ai/e/256/bluewire.simplecastaudio.com/8bbbd80a-92c8-48e6-a618-34e8e1a0bc59/episodes/8fe85e0d-7705-439b-9e3f-b65b345682ed/audio/128/default.mp3?aid=rss_feed&amp;awCollectionId=8bbbd80a-92c8-48e6-a618-34e8e1a0bc59&amp;awEpisodeId=8fe85e0d-7705-439b-9e3f-b65b345682ed&amp;feed=sjbSL_pM', 4970, '2026-10-19 15:44:41'::timestamptz, 14000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
