DO $$
DECLARE
  v_host_id uuid;
  v_pod_id uuid;
  v_cat uuid;
BEGIN
  SELECT id INTO v_cat FROM categories WHERE name_ar = 'ثقافة وأدب' LIMIT 1;
  INSERT INTO hosts (name_ar, slug, photo_url, cover_url, title_ar, specialty_ar, bio_ar, country, category_id, is_verified, followers_count)
  VALUES ('KSL Podcasts', 'cold', 'https://is1-ssl.mzstatic.com/image/thumb/Podcasts221/v4/a5/32/25/a5322553-e279-ce81-7095-f59c0cdabd1e/mza_6864620435701807236.jpg/600x600bb.jpg', 'https://is1-ssl.mzstatic.com/image/thumb/Podcasts221/v4/a5/32/25/a5322553-e279-ce81-7095-f59c0cdabd1e/mza_6864620435701807236.jpg/600x600bb.jpg', 'مقدم', 'ثقافة وأدب', 'بودكاست حقيقي: COLD', 'أونلاين', v_cat, true, 50000)
  RETURNING id INTO v_host_id;

  INSERT INTO podcasts (title, description, host_id, category_id, type, cover_url, audience_level, plays_count, rating_avg)
  VALUES ('COLD', '&lt;p&gt;COLD&lt;em&gt; &lt;/em&gt;is a narrative podcast series focused on missing persons cases. Investigative journalist and host Dave Cawley takes on a single story with each season.&lt;/p&gt; &lt;p&gt;&amp;nbsp;&lt;/p&gt; &lt;p&gt;&lt;em&gt;Season 1: Susan Powell Case Files&lt;/em&gt;, the &lt;em&gt;Cold&lt;/em&gt; journey begins with Dave&amp;rsquo;s investigation into the unsolved disappearance of Susan Powell&amp;hellip; and the man with the most to gain from her death.&lt;/p&gt; &lt;p&gt;&amp;nbsp;&lt;/p&gt; &lt;p&gt;&lt;em&gt;Season 2: Justice for Joyce Yost&lt;/em&gt; delves into th', v_host_id, v_cat, 'cultural', 'https://is1-ssl.mzstatic.com/image/thumb/Podcasts221/v4/a5/32/25/a5322553-e279-ce81-7095-f59c0cdabd1e/mza_6864620435701807236.jpg/600x600bb.jpg', 'beginner', 100000, 4.7)
  RETURNING id INTO v_pod_id;

  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Deceived | Lori and Alex | 5', '&lt;div&gt;Long before missing children and murder headlines, Alex Cox and Lori Vallow were just brother and sister. Through new interviews with their family, host Nate Eaton explores the siblings&amp;rsquo; upbringing, Lori&amp;rsquo;s early marriages and Alex&amp;rsquo;s fiercely protective role in her life.&lt;br&gt;&lt;br&gt;&lt;/div&gt; &lt;div&gt;But a troubling allegation from Alex&amp;rsquo;s ex-wife also raises questions about their bond and whether warning signs went unrecognized.&lt;/div&gt; &lt;div&gt;&amp;nbsp;&lt;/div&gt; &lt;div&gt;Want to listen ad-free and get the next episode', 'https://pds.cdnstream1.com/p/bonneville/cold/deceived-lori-and-alex-5/audio.mp3', 2642, '2026-11-19 10:05:00'::timestamptz, 5000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Deceived | Feel the Fire | 4', '&lt;div&gt;A search of Chad Daybell&amp;rsquo;s property brings the months-long investigation to a devastating turning point. Nate Eaton and detectives recount the day that changed the case and stayed with them long after.&lt;/div&gt; &lt;div&gt;&lt;br&gt;For Lori&amp;rsquo;s mother and sister Summer, the news flips their world upside down. In a recorded jailhouse call, Summer confronts Lori and demands answers from the sister she thought she knew.&lt;/div&gt; &lt;div&gt;&amp;nbsp;&lt;/div&gt; &lt;div&gt;Want to listen ad-free and get the next episode a week early? Join the &lt;a href=&#34;htt', 'https://pds.cdnstream1.com/p/bonneville/cold/deceived-feel-the-fire-4/audio.mp3', 2749, '2026-11-12 10:05:05'::timestamptz, 6000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Deceived | Proof of Life | 3', '&lt;p&gt;With Lori Vallow in jail and no sign of the children, investigators search for the last proof that JJ and Tylee were alive. Recorded calls reveal Chad and Lori&amp;rsquo;s unsettling private world, while Tylee&amp;rsquo;s best friend shares memories of the teenager behind the headlines and the messages that don&amp;rsquo;t sound like her.&lt;/p&gt; &lt;p&gt;As detectives sift through thousands of text messages, videos, photos and emails, a pattern begins to emerge.&lt;/p&gt; &lt;p&gt;Want to listen ad-free and get the next episode a week early? Join the &lt;a href=&#34;https://coldins', 'https://pds.cdnstream1.com/p/bonneville/cold/deceived-proof-of-life-3/audio.mp3', 2761, '2026-11-05 10:00:00'::timestamptz, 7000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Deceived | Hawaii | 2', '&lt;p&gt;An anonymous tip sends Nate Eaton to the beaches of Kauai in search of Lori Vallow and Chad Daybell to confront them with the question at the heart of the case: Where are the children JJ Vallow &amp;amp; Tylee Ryan?&lt;br&gt;&lt;br&gt;And a new interview with an Idaho police officer who flew out to Hawaii offers a revealing look at the woman at the center of the case.&lt;/p&gt; &lt;p&gt;Want to listen ad-free and get the next episode a week early? Join the &lt;a href=&#34;https://coldinsiderclub.supercast.com/&#34;&gt;COLD Insider Club&lt;/a&gt;.&lt;/p&gt; &lt;p&gt;If you enjoy COLD/D', 'https://pds.cdnstream1.com/p/bonneville/cold/deceived-hawaii-2/audio.mp3', 2508, '2026-10-29 09:05:00'::timestamptz, 8000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Deceived | Warning Signs | 1', '&lt;p&gt;A promising first date. Troubling stories of an estranged wife. Then, silence. Nancy Jo Hancock recalls her evening with Charles Vallow &amp;ndash; and a discovery months later that cast their date in a different light.&lt;br&gt;&lt;br&gt;Months later, in eastern Idaho, journalist Nate Eaton follows a strange missing-children case and begins uncovering a troubling web of deaths, disappearances, and extreme beliefs.&lt;/p&gt; &lt;p&gt;Want to listen ad-free and get the next episode a week early? Join the &lt;a href=&#34;https://coldinsiderclub.supercast.com/&#34;&gt;COLD Insider Club&l', 'https://pds.cdnstream1.com/p/bonneville/cold/deceived-warning-signs-1/audio.mp3', 2029, '2026-10-29 09:00:00'::timestamptz, 9000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Announcing Deceived: The Daybell Story', '&lt;p&gt;COLD host Dave Cawley provides a status update as the latest season draws to a close. Up next in the feed, we&#39;ll be sharing episodes of a new true crime show from KSL Podcasts. It&#39;s called Deceived: The Daybell Story, hosted by Nate Eaton of &lt;a href=&#34;https://www.eastidahonews.com/&#34;&gt;East Idaho News&lt;/a&gt; and produced by Ben Keubrick (lead producer of COLD season 3). Episodes of Deceived will begin appearing in the COLD podcast feed starting October 29.&lt;/p&gt;', 'https://pds.cdnstream1.com/p/bonneville/cold/announcing-deceived-the-794b7c/audio.mp3', 314, '2026-10-23 15:05:00'::timestamptz, 10000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Blamed on Bundy | Reckoning | 6', '&lt;div&gt;Heidi Holmberg and Tori Riddle face their father in court, taking their power back decades after suffering abuse at Tom Jackson&amp;rsquo;s hands.&lt;br&gt;&lt;br&gt;But even as Tom receives punishment from a judge, a new accuser emerges. The story she shares about her encounter with a former East Layton cop complicates the Nancy Baird investigation.&lt;/div&gt; &lt;div&gt;&amp;nbsp;&lt;/div&gt; &lt;div&gt;In this finale episode, the story returns to Nancy&amp;rsquo;s son Brant Baird and his search for answers about his missing mother. Tucked away in Nancy&amp;rsquo;s cedar chest, B', 'https://pds.cdnstream1.com/p/bonneville/cold/blamed-on-bundy-reckonin-b7572c/audio.mp3', 4442, '2026-10-21 09:05:00'::timestamptz, 11000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Blamed on Bundy | Reputation Damage | 5', '&lt;div&gt;The waiting game begins as former East Layton police officer Tom Jackson faces new criminal charges over allegations of child sex abuse against his daughters during the 1980s. A rift emerges among Jackson&amp;rsquo;s family, with some blood relatives refusing to believe he could be capable of such terrible acts.&lt;/div&gt; &lt;div&gt;&amp;nbsp;&lt;/div&gt; &lt;div&gt;Jackson&amp;rsquo;s comments to COLD also draw attention to Nancy Perry Baird&amp;rsquo;s ex-boyfriend, John Sparks, and his brother, Davis County Sheriff Kelly Sparks. COLD host Dave Cawley confronts Sheriff Sparks ab', 'https://pds.cdnstream1.com/p/bonneville/cold/blamed-on-bundy-reputati-cab887/audio.mp3', 4884, '2026-10-14 09:05:00'::timestamptz, 12000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Blamed on Bundy | Kicking the Hornet&#39;s Nest | 4', '&lt;p class=&#34;MsoNormal&#34;&gt;&lt;span style=&#34;font-family: -apple-system, BlinkMacSystemFont, &#39;Segoe UI&#39;, Roboto, Oxygen, Ubuntu, Cantarell, &#39;Open Sans&#39;, &#39;Helvetica Neue&#39;, sans-serif;&#34;&gt;The Nancy Baird case file, kept away from prying eyes for decades, is at last released to COLD in 2023. Contained within are surprise revelations about the last people known to have seen Nancy alive.&lt;/span&gt;&lt;/p&gt; &lt;p dir=&#34;ltr&#34;&gt;But when COLD host Dave Cawley&amp;rsquo;s investigation into the Nancy Baird case reached the family of former East Layton p', 'https://pds.cdnstream1.com/p/bonneville/cold/blamed-on-bundy-kicking-fa1e58/audio.mp3', 4878, '2026-10-07 09:05:00'::timestamptz, 13000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Blamed on Bundy | The Book of Regrets | 3', '&lt;p dir=&#34;ltr&#34;&gt;Days before his execution, serial killer Ted Bundy denied knowing anything about the disappearance of Nancy Baird. That didn&amp;rsquo;t stop police and the press from declaring Bundy the killer. That folklore loomed large for Nancy&amp;rsquo;s son, Brant.&lt;/p&gt; &lt;p dir=&#34;ltr&#34;&gt;Meanwhile, one of the police officers who investigated Nancy&amp;rsquo;s case wandered a proverbial wilderness following his arrest for child sex crimes. In Idaho, Tom Jackson found a new family, among a community of people who knew nothing of his past.&lt;/p&gt; &lt;p dir=&#34;', 'https://pds.cdnstream1.com/p/bonneville/cold/blamed-on-bundy-the-book-b332ab/audio.mp3', 4144, '2026-09-30 09:05:00'::timestamptz, 14000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Blamed on Bundy | Birds of a Feather | 2', '&lt;p dir=&#34;ltr&#34;&gt;A young man who demonstrated astonishing &amp;ldquo;powers&amp;rdquo; arrived in Utah five years following the disappearance of Nancy Baird. James Hydrick wowed police, including a former officer who investigated Nancy&amp;rsquo;s case, with his telekinetic abilities.&lt;/p&gt; &lt;p dir=&#34;ltr&#34;&gt;James Hydrick&amp;rsquo;s amazing talents drew fame and followers. But they were all an act, a fraud. Hydrick soon landed in prison for sex offenses against children.&lt;/p&gt; &lt;p dir=&#34;ltr&#34;&gt;The former East Layton cop, Tom Jackson, also ran afoul of the ', 'https://pds.cdnstream1.com/p/bonneville/cold/blamed-on-bundy-birds-of-629317/audio.mp3', 4368, '2026-09-23 09:10:00'::timestamptz, 15000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Blamed on Bundy | Everyone Knew Everyone | 1', '&lt;p dir=&#34;ltr&#34;&gt;Impatient customers lined up at the cash register late on the afternoon of Friday, July 4th, 1975. The gas station clerk, Nancy Perry Baird, was nowhere to be found. A police officer soon discovered Nancy&amp;rsquo;s purse, keys and car were left behind. So was Nancy&amp;rsquo;s 4-year-old son, Brant.&lt;/p&gt; &lt;p dir=&#34;ltr&#34;&gt;In this episode, investigative reporter Dave Cawley traces Nancy Baird&amp;rsquo;s life from her childhood to her disappearance. He reveals how a tiny, untrained police department in East Layton, Utah fumbled the case. That is, until', 'https://pds.cdnstream1.com/p/bonneville/cold/blamed-on-bundy-everyone-6f15d3/audio.mp3', 4549, '2026-09-23 09:05:00'::timestamptz, 16000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Introducing COLD: Blamed on Bundy - The Disappearance of Nancy Baird', '&lt;p dir=&#34;ltr&#34;&gt;A serial killer was on the prowl during the summer of 1975, when Nancy Perry Baird vanished from the gas station where she worked. Police pinned Nancy&#39;s disappearance on Ted Bundy, even though no evidence tied the notorious killer to the case.&lt;/p&gt; &lt;p dir=&#34;ltr&#34;&gt;Five decades later, a former police officer&#39;s daughter listened to&amp;nbsp;&lt;a href=&#34;https://thecoldpodcast.com/season-3/bonus-the-convenient-alternative/&#34; target=&#34;_blank&#34; rel=&#34;noopener&#34;&gt;an episode of COLD about the Nancy Baird case&lt;/a&gt;. She heard ', 'https://pds.cdnstream1.com/p/bonneville/cold/introducing-cold-blamed-9c4768/audio.mp3', 164, '2026-09-16 09:05:00'::timestamptz, 17000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'The Susan Powell Case Files | Ambiguous Grief | Bonus Episode 12', '&lt;p class=&#34;MsoNormal&#34;&gt;About a year after Susan Cox Powell disappeared from her home in West Valley City, Utah, a man entered a mom-and-pop bookstore one town over and stabbed the owner of the shop to death. The November, 2010 murder of Sherry Black was an inverse of the Susan Powell case: a body and physical evidence, but no suspect. It took police a decade before investigative genetic genealogy led them to Sherry Black&#39;s killer. That man is now in prison for life.&lt;/p&gt; &lt;p class=&#34;MsoNormal&#34;&gt;Black&#39;s daughter, Heidi Miller, spent a decade of her life trapp', 'https://pds.cdnstream1.com/p/bonneville/cold/the-susan-powell-case-fi-85ba20/audio.mp3', 1454, '2026-09-10 09:00:05'::timestamptz, 18000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Lost Boy', '&lt;p&gt;A 3-year-old boy wanders away from camp in the Uinta Mountains, leading to a panicked search. Uinta Triangle host Dave Cawley covered the case of Benjamin Myrup&#39;s disappearance when it happened. In this bonus episode, Dave revisits the case years later to learn what Benjamin&#39;s parents experienced behind the scenes of the search.&lt;/p&gt;', 'https://pds.cdnstream1.com/p/bonneville/cold/lost-boy/audio.mp3', 1768, '2026-05-20 09:02:00'::timestamptz, 19000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Ute Words', '&lt;p&gt;The word &#34;Uinta&#34; is foreign to many people, but not to native speakers of the Ute language. Larry Cesspooch, a member of the&amp;nbsp;&lt;a href=&#34;https://indian.utah.gov/ute-indian-tribe-of-the-uintah-ouray-reservation/&#34; target=&#34;_blank&#34; rel=&#34;noopener&#34;&gt;Ute Indian Tribe of the Uintah and Ouray Reservation&lt;/a&gt;, shares what the Uinta Mountains mean to himself and his people. Uinta Triangle host Dave Cawley also asks for Larry&#39;s help in learning the meaning of other Ute placenames, which are critical in helping keep the Ute language from becomin', 'https://pds.cdnstream1.com/p/bonneville/cold/ute-words/audio.mp3', 1414, '2026-05-20 09:01:00'::timestamptz, 20000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'The Disappearance of Lynn Simmons', '&lt;p&gt;Late in the summer of 1940, a government surveyor named Lynn Simmons vanished near Lamotte Peak in the High Uintas. Crowds of searchers scoured the mountain wilderness but never found any trace of Lynn. Over time, his case was forgotten by all but a few relatives. In this bonus episode, Uinta Triangle host Dave Cawley connects with Lynn&#39;s family to bring his memory back to the forefront.&lt;/p&gt;', 'https://pds.cdnstream1.com/p/bonneville/cold/the-disappearance-of-lyn-fd3a3b/audio.mp3', 1054, '2026-05-20 09:00:00'::timestamptz, 21000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Uinta Triangle | Episode 9', '&lt;p&gt;New Podcast from the COLD Team:&lt;br&gt;Marilyn Koolstra embarks on an unexpected pilgrimage to the place where her husband, Eric Robinson, lost his life in the Uinta Mountains. The journey into the wilderness tests her physical, mental and emotional limits. But Marilyn doesn&amp;rsquo;t travel alone. Friendships forged through tragedy help carry her through to the end.&lt;/p&gt;', 'https://pds.cdnstream1.com/p/bonneville/cold/uinta-triangle-episode-9/audio.mp3', 4285, '2025-07-08 10:09:00'::timestamptz, 22000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Uinta Triangle | Episode 8', '&lt;p&gt;New Podcast from the COLD Team:&lt;br&gt;Eric Robinson took 77 photographs on his last hike. Those images, recovered with Eric&amp;rsquo;s remains in 2016, tell the story of what he experienced on the Uinta Highline Trail. They also contain clues about why Eric diverted from the trail in his final hours. Dave Cawley follows those breadcrumbs to the brink in search of answers.&lt;/p&gt; &lt;p&gt;&amp;nbsp;&lt;/p&gt;', 'https://pds.cdnstream1.com/p/bonneville/cold/uinta-triangle-episode-8/audio.mp3', 4551, '2025-07-01 10:10:00'::timestamptz, 23000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Uinta Triangle | Episode 7', '&lt;p&gt;New Podcast from the COLD Team: &lt;br&gt;Marilyn Koolstra returns home to Australia without any answers about what happened to her missing husband, Eric Robinson. As months turn to years, she&amp;rsquo;s forced to accept the awful reality of his death at some unknown place in the Uinta Mountains. But an accidental discovery in those mountains will one day stun everyone involved in the search for Eric.&lt;/p&gt; &lt;p&gt;&amp;nbsp;&lt;/p&gt;', 'https://pds.cdnstream1.com/p/bonneville/cold/uinta-triangle-episode-7/audio.mp3', 3945, '2025-06-24 10:08:00'::timestamptz, 24000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Uinta Triangle | Episode 6', '&lt;p&gt;New Podcast from the COLD Team:&amp;nbsp;&lt;br&gt;The last glimmers of hope fade as the search for Eric Robinson enters its final stage. The Duchesne County sheriff, running out of time and money, makes one last push to find him. Searchers brave the weather and the wilderness in the hopes of sending Eric&amp;rsquo;s wife, Marilyn Koolstra, home to Australia with answers about her husband&amp;rsquo;s fate.&lt;/p&gt; &lt;p&gt;&amp;nbsp;&lt;/p&gt;', 'https://pds.cdnstream1.com/p/bonneville/cold/uinta-triangle-episode-6/audio.mp3', 4404, '2025-06-17 10:16:00'::timestamptz, 25000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Uinta Triangle | Episode 5', '&lt;p&gt;New Podcast from the COLD Team:&amp;nbsp;&lt;/p&gt; &lt;p&gt;As news coverage of the search for Eric Robinson spreads, a Boy Scout leader tells of spotting Eric far off the Uinta Highline Trail. This encounter along Yellowstone Creek raises questions about Eric&amp;rsquo;s state of mind, and expands the search area to include an even greater swath of High Uintas Wilderness. Was Eric lost? Uinta Triangle host Dave Cawley poses a new theory.&lt;/p&gt; &lt;p&gt;&amp;nbsp;&lt;/p&gt;', 'https://pds.cdnstream1.com/p/bonneville/cold/uinta-triangle-episode-5/audio.mp3', 4447, '2025-06-10 10:12:00'::timestamptz, 26000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Uinta Triangle | Episode 4', '&lt;p&gt;New Podcast from the COLD Team: The wife of missing trekker Eric Robinson flies halfway around the world, from Australia to Utah, in search of her husband. A rural sheriff struggles to organize an effective rescue across the vast expanse of the High Uintas Wilderness Area. An unlikely meeting along the Uinta Highline Trail brings Eric&amp;rsquo;s friends into contact with some important new allies at Dead Horse Pass.&lt;/p&gt; &lt;p&gt;&amp;nbsp;&lt;/p&gt;', 'https://pds.cdnstream1.com/p/bonneville/cold/uinta-triangle-episode-4/audio.mp3', 3866, '2025-06-03 15:16:00'::timestamptz, 27000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Uinta Triangle | Episode 3', '&lt;p&gt;New podcast from the COLD team: Eric Robinson doesn&amp;rsquo;t show up at the end of the Uinta Highline Trail. Eric&amp;rsquo;s friend reports him missing, kicking off a search-and-rescue mission. Marilyn Koolstra, meanwhile, feels powerless to help her husband from half a world away. Uinta Triangle host Dave Cawley sets off on his own solo hike, looking for clues about Eric&amp;rsquo;s disappearance.&lt;/p&gt; &lt;p&gt;&amp;nbsp;&lt;/p&gt;', 'https://pds.cdnstream1.com/p/bonneville/cold/uinta-triangle-episode-3/audio.mp3', 3774, '2025-05-27 09:10:00'::timestamptz, 28000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Uinta Triangle | Episode 1', '&lt;p&gt;New podcast from the COLD team: Eric Robinson wanted to hike the world&amp;rsquo;s greatest trails. He was happiest when spending weeks in the wild, and he often went out alone. Eric&amp;rsquo;s wife, Marilyn Koolstra, supported him in this goal. But the situation changed when Eric went missing on a solo trek to the Cascade Saddle in New Zealand. This episode traces the origins of Eric Robinson&amp;rsquo;s passion for trekking, the past traumas he tried to soothe in nature, and the midlife romance that brought Marilyn into his life.&lt;/p&gt; &lt;p&gt;&amp;nbsp;&lt;/p&gt;', 'https://pds.cdnstream1.com/p/bonneville/cold/uinta-triangle-episode-1/audio.mp3', 3872, '2025-05-20 12:40:00'::timestamptz, 29000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Uinta Triangle | Episode 2', '&lt;p&gt;New podcast from the COLD team: Eric Robinson forges a new friendship on the John Muir Trail, while an old friendship frays under stresses of the trail. From the High Sierra to the Himalaya, Eric&amp;rsquo;s aspirations in the outdoors continue to grow. His wife, Marilyn Koolstra, accompanies Eric on some of his adventures. But a rift emerges when Eric insists on going out alone after a few close calls with death in the mountains.&lt;/p&gt; &lt;p&gt;&amp;nbsp;&lt;/p&gt;', 'https://pds.cdnstream1.com/p/bonneville/cold/uinta-triangle-episode-2/audio.mp3', 4031, '2025-05-20 12:12:00'::timestamptz, 30000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'The Susan Powell Case Files | Beaches &amp; Airplanes | Bonus Episode 11', '&lt;p class=&#34;MsoNormal&#34;&gt;Susan Cox Powell disappeared 15 years ago. The day after she turned up missing, her four-year-old son Charlie Powell spoke to a detective from the West Valley City, Utah police department. Charlie told the detective his mommy had joined him, his little brother Braden and their dad, Susan&amp;rsquo;s husband Josh Powell, on a camping trip. But Charlie also said Susan didn&amp;rsquo;t come home. She stayed &amp;ldquo;where the crystals are.&amp;rdquo; In this special bonus episode, we explore what Charlie was trying to tell us about Susan&amp;rsquo;s fate. We a', 'https://pds.cdnstream1.com/p/bonneville/cold/the-susan-powell-case-fi-bb03e0/audio.mp3', 2138, '2024-12-06 05:52:00'::timestamptz, 31000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'The Susan Powell Case Files | Mystery Metal | Bonus Episode 10', '&lt;p class=&#34;MsoNormal&#34;&gt;Police in West Valley City, Utah found a charred clump of metal hidden in the back of Josh Powell&amp;rsquo;s minivan on the day after Susan Powell first came up missing. They suspected it was evidence, but could never identify it. Now, on the 15&lt;sup&gt;th&lt;/sup&gt; anniversary of Susan&amp;rsquo;s disappearance, we reveal the likely origin of that mystery metal evidence. In this special bonus episode, you&amp;rsquo;ll also hear from Andrew Robinson, a witness who&amp;rsquo;s never before spoken publicly about what he saw in the days before Susan vanishe', 'https://pds.cdnstream1.com/p/bonneville/cold/the-susan-powell-case-fi-28d8db/audio.mp3', 1747, '2024-12-05 04:10:00'::timestamptz, 32000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Justice for Joyce Yost | Twice Overturned | Bonus Episode 3', '&lt;p&gt;The man who killed Joyce Yost wins a major victory in court, seeing his death sentence overturned for a second time. It all boils down to one line of questioning at Doug Lovell&#39;s 2015 trial. Cold host Dave Cawley attended oral arguments before the Utah Supreme Court and discusses the stunning decision with Talking COLD&#39;s Amy Donaldson.&lt;/p&gt; &lt;p&gt;&amp;nbsp;&lt;/p&gt;', 'https://pds.cdnstream1.com/p/bonneville/cold/justice-for-joyce-yost-t-fd7a37/audio.mp3', 1312, '2024-08-28 07:01:00'::timestamptz, 33000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'The Search For Sheree | Bonus: The Causey Search | 15', '&lt;p&gt;COLD discovers an odd rock pile in the mountains. It looks like a possible grave. Detectives head into the hills, believing the rock pile could hold evidence related to the disappearance of Sheree Warren. In this bonus episode of COLD season 3, you&amp;rsquo;ll join investigative journalist&amp;nbsp;Dave&amp;nbsp;Cawley&amp;nbsp;on the mountain near Utah&amp;rsquo;s Causey Reservoir and hear exactly what happened as detectives and CSI excavated beneath the rocks.&lt;/p&gt; &lt;p&gt;Season 3 of&amp;nbsp;&lt;em&gt;Cold &lt;/em&gt;includes descriptions of rape, sexual assault, murder and', 'https://pds.cdnstream1.com/p/bonneville/cold/the-search-for-sheree-bo-e755ea/audio.mp3', 2243, '2023-09-13 04:00:00'::timestamptz, 34000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'The Search For Sheree | Bonus: The Convenient Alternative | 14', '&lt;p&gt;Ten years before Sheree Warren disappeared, another young mother vanished from her workplace in the suburbs of Ogden, Utah. Nancy Perry Baird&amp;rsquo;s case shares many similarities with Sheree Warren&amp;rsquo;s. Both were young mothers, recently divorced, working to support themselves. Police in both cases theorized a serial killer might be responsible. To this day, many of Nancy Baird&#39;s own relatives believe Ted Bundy abducted and killed her; a claim Bundy denied.&lt;/p&gt; &lt;p&gt;Cold has obtained exclusive access to the Nancy Baird case files. In this bonus episode of Col', 'https://pds.cdnstream1.com/p/bonneville/cold/the-search-for-sheree-bo-66c22e/audio.mp3', 5366, '2023-05-15 07:01:00'::timestamptz, 35000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'The Search For Sheree | Talking Cold: Burning Questions with Dave Cawley | 13', '&lt;p&gt;Amy and Sheryl sit down with Cold host and investigative reporter Dave Cawley to ask him your burning questions about Cold season 3, The Search for Sheree Warren. What about the jacket Sheree was wearing? And why didn&amp;rsquo;t police look harder at the last known person to see Sheree before she disappeared? Amy and Sheryl also discuss ethical questions with Associate Professor of Journalism at Weber State University, Dr. Jean Norman.&lt;/p&gt; &lt;p&gt;&amp;nbsp;&lt;/p&gt;', 'https://pds.cdnstream1.com/p/bonneville/cold/the-search-for-sheree-ta-773a9a/audio.mp3', 1987, '2023-05-08 07:01:00'::timestamptz, 36000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'The Search For Sheree | Talking Cold: When Obscene Calls Escalate | 12', '&lt;p&gt;If you get an unsolicited sexual call or nude picture sent to you, is that a crime? You may be surprised by the answer. One of the suspects in the disappearance of Sheree Warren in 1985 was caught making lewd phone calls to women multiple times. Do these types of crimes often escalate to other, more aggressive behaviors? Joining hosts Amy Donaldson &amp;amp; Sheryl Worsley for the discussion on this edition of Talking Cold: prosecutor and division director of the Salt Lake County Special Victims Unit Anna Rossi Anderson and former FBI profiler and host of the &lt;em&gt;Killer Psyche&l', 'https://pds.cdnstream1.com/p/bonneville/cold/the-search-for-sheree-ta-c1bc7b/audio.mp3', 2205, '2023-05-01 07:01:00'::timestamptz, 37000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'The Search for Sheree | Talking Cold: Who Owns Your Case? | 11', '&lt;p&gt;Who handles your case if you go missing or are murdered? Talking Cold is the after-show podcast that dives into the key issues raised in COLD. Season 3 of COLD tells the story of Sheree Warren, who disappeared from Salt Lake City, Utah in 1985. Her case remains unsolved today, partially because of police squabbles over jurisdiction. Talking Cold hosts Amy Donaldson and Sheryl Worsley ask retired Salt Lake County Sheriff Aaron Kennard and former Roy, Utah police chief Carl Merino why police egos and invisible borders sometimes get in the way of solving crimes.&lt;/p&gt; &lt;p&gt;&amp;n', 'https://pds.cdnstream1.com/p/bonneville/cold/the-search-for-sheree-ta-da47a4/audio.mp3', 2480, '2023-04-24 07:01:00'::timestamptz, 38000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'The Search for Sheree | Last Man Standing | 10', '&lt;p&gt;Cary Hartmann returns to Ogden after leaving prison, only to face fresh suspicion. Charles Warren&amp;rsquo;s health declines, leaving him unable to clear up lingering questions. The &lt;em&gt;Cold&lt;/em&gt; team pieces together the evidence to provide the most likely scenario in the unsolved cold case disappearance of Sheree Warren.&lt;/p&gt; &lt;p&gt;Season 3 of &lt;em&gt;Cold&lt;/em&gt; includes descriptions of rape, sexual assault, murder and domestic violence. Please take care when listening. Free resources for escaping domestic abuse are available at &lt;a href=&#34;http://theh', 'https://pds.cdnstream1.com/p/bonneville/cold/the-search-for-sheree-la-388a4c/audio.mp3', 4243, '2023-04-17 07:02:00'::timestamptz, 39000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'The Search for Sheree | A Picture in the Lobby | 9', '&lt;p&gt;A human skull is discovered on a hillside next to a busy Utah highway. Roy City police detective John Frawley digs into an abandoned box of Sheree Warren case files. Sheree&amp;rsquo;s ex-husband, Charles Warren, botches an opportunity to clear himself as a suspect in her disappearance.&lt;/p&gt; &lt;p&gt;Season 3 of &lt;em&gt;Cold &lt;/em&gt;includes descriptions of rape, sexual assault, murder and domestic violence. Please take care when listening. Free resources for escaping domestic abuse are available at &lt;a href=&#34;http://thehotline.org/&#34;&gt;&lt;span class=&#34;s1&#34;&g', 'https://pds.cdnstream1.com/p/bonneville/cold/the-search-for-sheree-a-62b983/audio.mp3', 4514, '2023-04-10 07:02:00'::timestamptz, 40000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'The Search for Sheree | Fool Me Once | 8', '&lt;p&gt;Two pivotal recordings are revealed: Cary Hartmann&#39;s police interview about Sheree Warren and a secret interrogation of Cary&amp;rsquo;s brother, Jack Hartmann. Investigator Shane Minor looks for the missing piece he needs before he can arrest Cary.&lt;/p&gt; &lt;p&gt;Season 3 of &lt;em&gt;Cold&lt;/em&gt; includes descriptions of rape, sexual assault, murder and domestic violence. Please take care when listening. Free resources for escaping domestic abuse are available at &lt;a href=&#34;http://thehotline.org/&#34;&gt;&lt;span class=&#34;s1&#34;&gt;thehotline.org&lt;/span&gt;&lt;/', 'https://pds.cdnstream1.com/p/bonneville/cold/the-search-for-sheree-fo-7e2d75/audio.mp3', 4086, '2023-04-03 07:02:00'::timestamptz, 41000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'The Search for Sheree | Purgatory | 7', '&lt;p&gt;Investigator Shane Minor heads up the mountain behind Causey Reservoir in search of Sheree Warren&amp;rsquo;s remains. Cary Hartmann begins to accept responsibility for the crimes he was convicted of, and at long last agrees to speak with police about Sheree&amp;rsquo;s disappearance.&lt;/p&gt; &lt;p&gt;Season 3 of Cold includes descriptions of rape, sexual assault, murder and domestic violence. Please take care when listening. Free resources for escaping domestic abuse are available at &lt;a href=&#34;http://thehotline.org/&#34;&gt;&lt;span class=&#34;s1&#34;&gt;thehotline.org&lt;/sp', 'https://pds.cdnstream1.com/p/bonneville/cold/the-search-for-sheree-pu-d52d3b/audio.mp3', 4067, '2023-03-27 07:02:00'::timestamptz, 42000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'The Search for Sheree | Lying Liars | 6', '&lt;p&gt;A jailhouse snitch tells the FBI that Cary Hartmann killed Sheree Warren. Cary tries to convince the parole board he&#39;s innocent. Sheree&amp;rsquo;s family members hold a memorial and have her declared legally deceased. Ogden police detective Shane Minor follows up on a longshot lead in the search for Sheree.&lt;/p&gt; &lt;p&gt;Season 3 of &lt;em&gt;Cold &lt;/em&gt;includes descriptions of rape, sexual assault, murder and domestic violence. Please take care when listening. Free resources for escaping domestic abuse are available at &lt;a href=&#34;http://thehotline.org/&#34;&gt;&lt', 'https://pds.cdnstream1.com/p/bonneville/cold/the-search-for-sheree-ly-787cab/audio.mp3', 4622, '2023-03-20 07:01:00'::timestamptz, 43000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'The Search for Sheree | Nighthawk | 5', '&lt;p&gt;Cary Hartmann brings look-alikes to a police lineup in the Ogden City Rapist case. His TV reporter friend Larry Lewis tests the boundaries of journalistic ethics when Cary goes to trial. Police detective Jack Bell receives a letter about Sheree Warren and the TV show &amp;ldquo;Unsolved Mysteries.&amp;rdquo;&lt;/p&gt; &lt;p&gt;Season 3 of Cold includes descriptions of rape, sexual assault, murder and domestic violence. Please take care when listening. Free resources for escaping domestic abuse are available at &lt;a href=&#34;http://thehotline.org/&#34;&gt;&lt;span class=&#34;s1&#34;&', 'https://pds.cdnstream1.com/p/bonneville/cold/the-search-for-sheree-ni-ed95c8/audio.mp3', 4389, '2023-03-13 07:01:00'::timestamptz, 44000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'The Search for Sheree | The Supper Club | 4', '&lt;p&gt;An anonymous caller reports finding a body in the mountains, near Causey Reservoir. Police search, thinking they might find the remains of Sheree Warren. Ogden detectives try to link Cary Hartmann and the lingerie survey phone calls to the Ogden City Rapist, but the case isn&amp;rsquo;t as simple as it seems. New witnesses place Sheree Warren with Cary on the night of her disappearance.&lt;/p&gt; &lt;p&gt;Season 3 of Cold includes descriptions of rape, sexual assault, murder and domestic violence. Please take care when listening. Free resources for escaping domestic abuse are availabl', 'https://pds.cdnstream1.com/p/bonneville/cold/the-search-for-sheree-th-6fc782/audio.mp3', 4889, '2023-03-06 08:01:00'::timestamptz, 45000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'The Search for Sheree | Cherish the Love | 3', '&lt;p&gt;A serial rapist is stalking the streets of Ogden, Utah. Police are on the hunt for both the rapist and the source of a string of lingerie survey phone calls. Cary Hartmann turns to psychics and a private investigator in his search for his missing girlfriend, Sheree Warren. Meanwhile, detective Jack Bell begins to learn one of his key suspects is harboring secrets.&lt;/p&gt; &lt;p&gt;Season 3 of &lt;em&gt;Cold&lt;/em&gt; includes descriptions of rape, sexual assault, murder and domestic violence. Please take care when listening. Free resources for escaping domestic abuse are available ', 'https://pds.cdnstream1.com/p/bonneville/cold/the-search-for-sheree-ch-e78f67/audio.mp3', 4752, '2023-02-27 08:01:00'::timestamptz, 46000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'The Search for Sheree | Go Ask Alice | 2', '&lt;p&gt;The last person known to see Sheree Warren alive describes her final day. Sheree plans to meet her estranged husband Charles &amp;ldquo;Chuck&amp;rdquo; Warren after work, but neither Sheree nor Chuck make that meeting. Sheree&amp;rsquo;s car surfaces weeks later in Las Vegas, Nevada but no one can say how it got there. Police detective Jack Bell turns up the heat on Chuck Warren.&lt;/p&gt; &lt;p&gt;Season 3 of Cold includes descriptions of rape, sexual assault, murder and domestic violence. Please take care when listening. Free resources for escaping domestic abuse are available at &', 'https://pds.cdnstream1.com/p/bonneville/cold/the-search-for-sheree-go-c8ee0d/audio.mp3', 4080, '2023-02-20 08:02:00'::timestamptz, 47000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'The Search for Sheree | Everything Escalates | 1', '&lt;p&gt;It all starts with a phone call. A woman receives a late-night lingerie survey call that turns obscene. The man on the line says he wants to meet her. With the help of police, she sets a trap and captures the caller. But all he receives is a slap on the wrist. Years later, that man will meet and begin dating a young mother named Sheree Warren. Only a few months later, Sheree Warren disappears.&lt;/p&gt; &lt;p&gt;Season 3 of Cold includes descriptions of rape, sexual assault, murder and domestic violence. Please take care when listening. Free resources for escaping domestic abuse are a', 'https://pds.cdnstream1.com/p/bonneville/cold/the-search-for-sheree-ev-76bd16/audio.mp3', 4085, '2023-02-20 08:01:00'::timestamptz, 48000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Introducing: The Search for Sheree Warren', '&lt;p&gt;Sheree Warren left her job in Salt Lake City on an October evening in 1985. She told a coworker she was headed to meet her estranged husband, Charles Warren, at a car dealership, but she never made it. Sheree vanished. When her car mysteriously surfaced weeks later, hundreds of miles away in Las Vegas, no one could say how it got there.&lt;/p&gt; &lt;p&gt;Season 3: The Search for Sheree follows two suspects: Sheree&#39;s estranged husband Charles, and her new boyfriend Cary Hartmann. Both men raised suspicion for investigators. Investigative journalist Dave Cawley digs into the double', 'https://pds.cdnstream1.com/p/bonneville/cold/introducing-the-search-f-3f2836/audio.mp3', 232, '2022-10-31 16:16:31'::timestamptz, 49000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Justice for Joyce Yost | Location, Location, Location | Bonus Episode 2', '&lt;p&gt;Breaking down the evidence in the search for the remains of Joyce Yost. Cold takes you to three locations where our investigation suggests Doug Lovell might have buried Joyce Yost on the night he killed her. They are: a concrete dump pit, a mountain cabin and a remote canyon where Doug and Rhonda Lovell were suspected of poaching. Come along as cadaver dogs enter the aspen forest in search of answers in a 36-year-old mystery.&lt;/p&gt; &lt;p&gt;Joyce Yost had never met the man who followed her home on an April night in 1985, who kidnapped and raped her. He threatened to kill her, but ', 'https://pds.cdnstream1.com/p/bonneville/cold/justice-for-joyce-yost-l-1e1725/audio.mp3', 3747, '2021-07-21 11:00:00'::timestamptz, 50000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Justice for Joyce Yost | Satanic Panic | Bonus Episode 1', '&lt;p&gt;Stories of satanic cults, human sacrifice and horrifying child abuse: the satanic panic that gripped the United States during the 1980s and early &#39;90s came very close to knocking the cold case investigation into Joyce Yost&#39;s disappearance completely off the rails. This bonus episode of Cold season 2 examines the reports of satanic ritual abuse that were prevalent at the time. Mike King, a police officer who gained experience investigating cults with his bust of the polygamist &#34;Zion Society&#34; group in 1991, recounts the raid. King also discusses his work probing satanic ', 'https://pds.cdnstream1.com/p/bonneville/cold/justice-for-joyce-yost-s-421d96/audio.mp3', 3508, '2021-07-21 04:00:00'::timestamptz, 51000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Justice for Joyce Yost | Talking Cold | Discussion of Episode 13', '&lt;p&gt;Doug Lovell sent a letter to a journalist, sparking her curiosity. Candice Madsen started looking into the murder of Joyce Yost as a result of Doug&#39;s letter, which ultimately led to Cold season 2. Candice joins Amy, Sheryl and Dave Cawley to talk about the lessons they&#39;ve each taken from the case. Sheryl and Dave then wrap up with big moments from episode 13.&lt;/p&gt; &lt;p&gt;Talking Cold is honest and frank conversations about the issues brought forward in the latest episode of the Cold podcast. We begin with Cold season 2: Justice for Joyce. Three ladies, Amy Donaldson, An', 'https://pds.cdnstream1.com/p/bonneville/cold/justice-for-joyce-yost-t-c13fbf/audio.mp3', 2317, '2021-06-25 08:00:00'::timestamptz, 52000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Justice for Joyce Yost | Last Chance | 13', '&lt;p&gt;A KSL employee receives a letter after talking about suicide prevention on the radio. It&#39;s from a man living on death row, who tells the story of how a little mouse helped him endure a period of darkness and despair. But is that inmate, Doug Lovell, telling an honest story? Or is the letter an attempt to cultivate a character witness? Cold season 2, Justice for Joyce, reaches its finale with a look at where Doug Lovell&#39;s appeal stands in 2021, as well as look back at what&#39;s changed since the murder of Joyce Yost.&lt;/p&gt; &lt;p&gt;Joyce Yost had never met the man who foll', 'https://pds.cdnstream1.com/p/bonneville/cold/justice-for-joyce-yost-l-fac385/audio.mp3', 4279, '2021-06-23 04:10:00'::timestamptz, 53000);
  INSERT INTO episodes (podcast_id, title, description, audio_url, duration_seconds, published_at, plays_count)
  VALUES (v_pod_id, 'Justice for Joyce Yost | Talking Cold | Discussion of Episode 12', '&lt;p&gt;Life on death row is something we don&#39;t hear much about. Our guest is former Utah State prison warden Ken Shulsen. He worked almost every job at the prison including overseeing several high-profile executions. He was once taken hostage in a prison riot. Amy and Sheryl also talk big moments from Episode 12 and Cold host Dave Cawley responds to a voicemail question.&lt;/p&gt; &lt;p&gt;Talking Cold is honest and frank conversations about the issues brought forward in the latest episode of the Cold podcast. We begin with Cold season 2: Justice for Joyce. Three ladies, Amy Donaldson, A', 'https://pds.cdnstream1.com/p/bonneville/cold/justice-for-joyce-yost-t-0bdcdf/audio.mp3', 3244, '2021-06-18 06:30:00'::timestamptz, 54000);
END $$;

